// ─────────────────────────────────────────────────────────────────────────────
// LOCAL FILESYSTEM STORAGE SHIM
// ─────────────────────────────────────────────────────────────────────────────
// We migrated off Google Cloud Storage (Cloud Run) to SparkedHost.
// All bot data now lives on local disk under /home/container/shubba-files.
// This shim exposes the same API as @google-cloud/storage so the rest of
// the codebase doesn't need to change.
//
// Mapping:
//   bucket.file('foo.json').download()     → fs.readFileSync(BASE/foo.json)
//   bucket.file('foo.json').save(data)     → fs.writeFileSync(BASE/foo.json)
//   bucket.file('foo.json').exists()       → fs.existsSync
//   bucket.file('foo.json').delete()       → fs.unlinkSync
//   bucket.file('foo.json').getMetadata()  → fs.statSync (size/timestamps)
//   bucket.file('foo.json').copy(dest)     → fs.copyFileSync
//   bucket.upload(localPath, {dest})       → fs.copyFileSync
//   bucket.getFiles({prefix})              → fs.readdirSync filtered
//
// Teaser files in /teasers/ are served publicly via the dashboard HTTP
// server so Discord links keep working — see TEASER URL handler below.
// ─────────────────────────────────────────────────────────────────────────────

const STORAGE_BASE = process.env.SHUBBA_STORAGE_DIR || '/home/container/shubba-files';
