const PUBLIC_BASE_URL = process.env.PUBLIC_BASE_URL || `http://212.192.28.228:25547`;

class LocalFile {
    constructor(bucket, fileName) {
        this.bucket = bucket;
        this.name = fileName;
        this.fullPath = path.join(STORAGE_BASE, fileName);
    }
    async exists() {
        return [fs.existsSync(this.fullPath)];
    }
    async download() {
        return [fs.readFileSync(this.fullPath)];
    }
    async save(data, opts) {
        fs.mkdirSync(path.dirname(this.fullPath), { recursive: true });
        fs.writeFileSync(this.fullPath, typeof data === 'string' ? data : Buffer.from(data));
        return undefined;
    }
    async delete() {
        try { fs.unlinkSync(this.fullPath); } catch(e) { if (e.code !== 'ENOENT') throw e; }
        return [{}];
    }
    async getMetadata() {
        const s = fs.statSync(this.fullPath);
        return [{ name: this.name, size: s.size, updated: s.mtime.toISOString(), contentType: undefined }];
    }
    async copy(destFile) {
        fs.mkdirSync(path.dirname(destFile.fullPath), { recursive: true });
        fs.copyFileSync(this.fullPath, destFile.fullPath);
        return [destFile, {}];
    }
    publicUrl() {
        return `${PUBLIC_BASE_URL}/files/${this.name}`;
    }
}

class LocalBucket {
    constructor(name) { this.name = name; }
    file(fileName) { return new LocalFile(this, fileName); }
    async upload(localPath, opts) {
        const dest = (opts && opts.destination) || path.basename(localPath);
        const destPath = path.join(STORAGE_BASE, dest);
        fs.mkdirSync(path.dirname(destPath), { recursive: true });
        fs.copyFileSync(localPath, destPath);
        return [new LocalFile(this, dest), {}];
    }
    async getFiles(opts) {
        const prefix = (opts && opts.prefix) || '';
        const results = [];
        const walk = (dir) => {
            if (!fs.existsSync(dir)) return;
            for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
                const full = path.join(dir, entry.name);
                if (entry.isDirectory()) walk(full);
                else {
                    const rel = path.relative(STORAGE_BASE, full).replace(/\\/g, '/');
                    if (rel.startsWith(prefix)) results.push(new LocalFile(this, rel));
                }
            }
        };
        walk(STORAGE_BASE);
        return [results];
    }
}

