// ============================================================
// ADMIN DASHBOARD — Shubba Control Panel
// ============================================================
// Credentials are ENV-ONLY. This dashboard is reachable on a PUBLIC IP (see
// PUBLIC_BASE_URL above), so there is deliberately NO default and NO fallback:
// if either var is unset the panel refuses EVERY login instead of shipping a
// well-known password. Set DASHBOARD_USER / DASHBOARD_PASS to enable it.
// The startup check further down reports it when the dashboard is locked.
const DASHBOARD_USER = process.env.DASHBOARD_USER || '';
const DASHBOARD_PASS = process.env.DASHBOARD_PASS || '';
const DASHBOARD_ENABLED = Boolean(DASHBOARD_USER && DASHBOARD_PASS);

const BOT_START_TIME = Date.now();

/**
 * Constant-time string compare, so the public-facing panel can't leak the
 * password byte-by-byte through response timing.
 */
function credsMatch(a, b) {
    const ab = Buffer.from(String(a), 'utf8');
    const bb = Buffer.from(String(b), 'utf8');
    if (ab.length !== bb.length) return false;
    return require('crypto').timingSafeEqual(ab, bb);
}

/**
 * Basic-auth gate for /dashboard, /admin and every /api/ route.
 * FAILS CLOSED: with no credentials configured, nobody authenticates.
 */
function requireAuth(req) {
    if (!DASHBOARD_ENABLED) return false;   // unconfigured → locked, never open
    const auth = req.headers['authorization'] || '';
    if (!auth.startsWith('Basic ')) return false;
    const decoded = Buffer.from(auth.slice(6), 'base64').toString('utf8');
    return credsMatch(decoded, `${DASHBOARD_USER}:${DASHBOARD_PASS}`);
}

function sendAuth(res) {
    res.writeHead(401, { 'WWW-Authenticate': 'Basic realm="Shubba Admin"', 'Content-Type': 'text/plain' });
    res.end('Unauthorized');
}

function sendJSON(res, data, status = 200) {
    res.writeHead(status, {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Authorization, Content-Type',
        'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    });
    res.end(JSON.stringify(data));
}

function uptime() {
    const s = Math.floor((Date.now() - BOT_START_TIME) / 1000);
    const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
    return `${h}h ${m}m ${sec}s`;
}

const DASHBOARD_HTML_B64 = '';
const DASHBOARD_HTML = Buffer.from(DASHBOARD_HTML_B64, 'base64').toString('utf8');



// ── Dashboard HTTP server ────────────────────────────────────
const dashboardServer = http.createServer(async (req, res) => {
    const url = new URL(req.url, 'http://localhost');
    const path = url.pathname;

    // Handle CORS preflight
    if (req.method === 'OPTIONS') {
        res.writeHead(204, {
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Headers': 'Authorization, Content-Type',
            'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
        });
        res.end();
        return;
    }

    // Favicon — inline SVG duck emoji as ICO substitute
    if (path === '/favicon.ico') {
        // Base64-encoded 32x32 favicon (duck emoji rendered as SVG)
        const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="90">🦆</text></svg>`;
        res.writeHead(200, { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'public, max-age=86400' });
        res.end(svg);
        return;
    }

    // Health check — no auth needed
    if (path === '/health') {
        res.writeHead(200, { 'Content-Type': 'text/plain' });
        res.end('OK\n');
        return;
    }

    // ── PUBLIC FILE SERVING (no auth) ──────────────────────────────────────
    // Serves files from the storage directory so Discord teaser links work.
    // /files/<path> → STORAGE_BASE/<path>
    if (path.startsWith('/files/')) {
        const requested = decodeURIComponent(path.slice('/files/'.length));
        // Defense: prevent path traversal
        const safePath = require('path').normalize(requested).replace(/^(\.\.[\/\\])+/, '');
        const fullPath = require('path').join(STORAGE_BASE, safePath);
        if (!fullPath.startsWith(STORAGE_BASE)) {
            res.writeHead(403); res.end('Forbidden'); return;
        }
        if (!fs.existsSync(fullPath) || !fs.statSync(fullPath).isFile()) {
            res.writeHead(404); res.end('Not Found'); return;
        }
        const stat = fs.statSync(fullPath);
        const ext = require('path').extname(safePath).toLowerCase().slice(1);
        const mimeMap = {
            'mp4': 'video/mp4', 'mov': 'video/quicktime', 'webm': 'video/webm',
            'mkv': 'video/x-matroska', 'avi': 'video/x-msvideo',
            'gif': 'image/gif', 'png': 'image/png', 'jpg': 'image/jpeg',
            'jpeg': 'image/jpeg', 'webp': 'image/webp',
            'mp3': 'audio/mpeg', 'wav': 'audio/wav', 'ogg': 'audio/ogg',
            'json': 'application/json', 'txt': 'text/plain', 'pdf': 'application/pdf'
        };
        const contentType = mimeMap[ext] || 'application/octet-stream';

        // Honor Range requests (Discord embeds and browsers seek into videos)
        const range = req.headers.range;
        if (range) {
            const m = /bytes=(\d+)-(\d*)/.exec(range);
            if (m) {
                const start = parseInt(m[1], 10);
                const end = m[2] ? parseInt(m[2], 10) : stat.size - 1;
                if (start < stat.size && end < stat.size && start <= end) {
                    res.writeHead(206, {
                        'Content-Type': contentType,
                        'Content-Range': `bytes ${start}-${end}/${stat.size}`,
                        'Accept-Ranges': 'bytes',
                        'Content-Length': end - start + 1,
                        'Cache-Control': 'public, max-age=31536000'
                    });
                    fs.createReadStream(fullPath, { start, end }).pipe(res);
                    return;
                }
            }
        }
        res.writeHead(200, {
            'Content-Type': contentType,
            'Content-Length': stat.size,
            'Accept-Ranges': 'bytes',
            'Cache-Control': 'public, max-age=31536000'
        });
        fs.createReadStream(fullPath).pipe(res);
        return;
    }
    // ───────────────────────────────────────────────────────────────────────

    // Dashboard HTML — auth required
    if (path === '/dashboard' || path === '/admin') {
        if (!requireAuth(req)) return sendAuth(res);
        const creds = Buffer.from(`${DASHBOARD_USER}:${DASHBOARD_PASS}`).toString('base64');
        const html = DASHBOARD_HTML.replace('__CREDS__', creds);
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(html);
        return;
    }

    // ── API routes — all require auth ────────────────────────
    if (path.startsWith('/api/')) {
        if (!requireAuth(req)) return sendAuth(res);

        // For multipart uploads, do NOT pre-consume the stream — the route handler reads it directly
        const isMultipart = (req.headers['content-type'] || '').includes('multipart/form-data');

        // Read body — GET requests have no body; multipart POSTs are handled per-route
        let body = '';
        if (!isMultipart && (req.method === 'POST' || req.method === 'PUT' || req.method === 'PATCH')) {
            body = await new Promise(resolve => {
                const chunks = [];
                req.on('data', d => chunks.push(d));
                req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
            });
        }
        let parsed = {};
        try { if (body) parsed = JSON.parse(body); } catch(e) {}

        // ════════════════════════════════════════════════════════
        // SUPERCHARGED API ROUTES
        // ════════════════════════════════════════════════════════

        // GET /api/overview
        if (path === '/api/overview' && req.method === 'GET') {
            const guild = client.guilds.cache.first();
            const solCount = Object.values(SOLUTIONS_BY_VERSION).reduce((a,v) => a + v.length, 0);
            const threads = Array.from(activeThreadIndex.values()).slice(0, 20).map(t => ({ name: t.title, url: t.url, createdAt: t.createdAt }));
            return sendJSON(res, {
                online: !!client.user, botTag: client.user?.tag || '—', uptime: uptime(),
                activeThreads: activeThreadIndex.size, openTickets: ticketChannels.size,
                warnedUsers: Object.keys(moderationData).length,
                faqCount: faqEmbeds.length, rulesCount: rulesData.length,
                knowledgeEntries: customKnowledgeEntries.length, solutionsCount: solCount,
                guildMembers: guild?.memberCount || '—', threads, versions: LATEST_VERSIONS,
            });
        }

        // GET /api/members
        if (path === '/api/members' && req.method === 'GET') {
            const guild = client.guilds.cache.first();
            if (!guild) return sendJSON(res, { members: [] });
            try {
                const members = await guild.members.fetch();
                const result = Array.from(members.values())
                    .filter(m => !m.user.bot)
                    .sort((a, b) => (a.user.username||'').localeCompare(b.user.username||''))
                    .map(m => ({
                        id: m.id, username: m.user.username,
                        displayName: m.displayName || m.user.username,
                        warnings: (moderationData[m.id]?.warnings || []).length,
                        roles: m.roles.cache.filter(r => r.name !== '@everyone').map(r => ({ id: r.id, name: r.name })),
                    }));
                return sendJSON(res, { members: result });
            } catch(e) { return sendJSON(res, { members: [], error: e.message }); }
        }

        // GET /api/threads
        if (path === '/api/threads' && req.method === 'GET') {
            return sendJSON(res, { threads: Array.from(activeThreadIndex.values()).map(t => ({ name: t.title, url: t.url, createdAt: t.createdAt, threadId: t.threadId })) });
        }

        // GET /api/moderation — enriched with full warnings + usernames
        if (path === '/api/moderation' && req.method === 'GET') {
            const guild = client.guilds.cache.first();
            const entries = await Promise.all(Object.entries(moderationData).map(async ([userId, d]) => {
                let username = 'Unknown';
                try {
                    const member = guild ? await guild.members.fetch(userId).catch(() => null) : null;
                    username = member?.user?.username || (await client.users.fetch(userId).catch(() => null))?.username || userId;
                } catch(e) {}
                return { userId, username, count: d.warnings.length, warnings: d.warnings || [], lastWarning: d.warnings[d.warnings.length - 1] || {} };
            }));
            return sendJSON(res, { entries });
        }

        // POST /api/moderation/clear
        if (path === '/api/moderation/clear' && req.method === 'POST') {
            const { userId } = parsed;
            if (!userId) return sendJSON(res, { error: 'userId required' }, 400);
            delete moderationData[userId];
            await saveModerationToGCS();
            return sendJSON(res, { message: `Warnings cleared for ${userId}` });
        }

        // POST /api/moderation/warn
        if (path === '/api/moderation/warn' && req.method === 'POST') {
            const { userId, reason } = parsed;
            if (!userId) return sendJSON(res, { error: 'userId required' }, 400);
            if (!moderationData[userId]) moderationData[userId] = { warnings: [] };
            moderationData[userId].warnings.push({ reason: reason || 'Dashboard warn', date: new Date().toISOString(), by: 'Dashboard' });
            await saveModerationToGCS();
            return sendJSON(res, { message: `Warning issued to ${userId} (${moderationData[userId].warnings.length}/3)` });
        }

        // POST /api/moderation/mute
        if (path === '/api/moderation/mute' && req.method === 'POST') {
            const { userId, duration, reason } = parsed;
            if (!userId) return sendJSON(res, { error: 'userId required' }, 400);
            const guild = client.guilds.cache.first();
            const member = guild ? await guild.members.fetch(userId).catch(() => null) : null;
            if (!member) return sendJSON(res, { error: 'Member not found in guild' }, 404);
            await member.timeout(duration || 3600000, reason || 'Muted via dashboard');
            return sendJSON(res, { message: `Muted ${member.user.username} for ${Math.round((duration||3600000)/60000)} minutes` });
        }

        // POST /api/moderation/kick
        if (path === '/api/moderation/kick' && req.method === 'POST') {
            const { userId, reason } = parsed;
            if (!userId) return sendJSON(res, { error: 'userId required' }, 400);
            const guild = client.guilds.cache.first();
            const member = guild ? await guild.members.fetch(userId).catch(() => null) : null;
            if (!member) return sendJSON(res, { error: 'Member not found' }, 404);
            const name = member.user.username;
            await member.kick(reason || 'Kicked via dashboard');
            return sendJSON(res, { message: `Kicked ${name}` });
        }

        // POST /api/moderation/ban
        if (path === '/api/moderation/ban' && req.method === 'POST') {
            const { userId, reason } = parsed;
            if (!userId) return sendJSON(res, { error: 'userId required' }, 400);
            const guild = client.guilds.cache.first();
            if (!guild) return sendJSON(res, { error: 'Guild not found' }, 500);
            await guild.members.ban(userId, { reason: reason || 'Banned via dashboard' });
            return sendJSON(res, { message: `Banned user ${userId}` });
        }

        // GET /api/knowledge
        if (path === '/api/knowledge' && req.method === 'GET') {
            return sendJSON(res, { entries: customKnowledgeEntries });
        }

        // POST /api/knowledge/add
        if (path === '/api/knowledge/add' && req.method === 'POST') {
            const { text } = parsed;
            if (!text) return sendJSON(res, { error: 'text required' }, 400);
            customKnowledgeEntries.push({ text, addedBy: 'Dashboard', addedAt: new Date().toISOString() });
            await saveCustomKnowledgeToGCS();
            return sendJSON(res, { message: `Knowledge entry #${customKnowledgeEntries.length} added` });
        }

        // POST /api/knowledge/delete
        if (path === '/api/knowledge/delete' && req.method === 'POST') {
            const { index } = parsed;
            if (index < 0 || index >= customKnowledgeEntries.length) return sendJSON(res, { error: 'Invalid index' }, 400);
            const removed = customKnowledgeEntries.splice(index, 1)[0];
            await saveCustomKnowledgeToGCS();
            return sendJSON(res, { message: `Deleted entry: "${removed.text.substring(0,60)}..."` });
        }

        // POST /api/knowledge/test
        if (path === '/api/knowledge/test' && req.method === 'POST') {
            const { question } = parsed;
            if (!question) return sendJSON(res, { error: 'question required' }, 400);
            try {
                const prompt = `${PUNCHY_STATIC_KNOWLEDGE}\n${buildCustomKnowledge()}\n\nQuestion: ${question}\nAnswer briefly and directly:`;
                const answer = await callGemini(prompt, false);
                return sendJSON(res, { answer });
            } catch(e) { return sendJSON(res, { answer: 'Error: ' + e.message }); }
        }

        // POST /api/knowledge/test-wiki — replay harness.
        //
        // Runs a question through the REAL wiki-answer path: same prompt builder
        // (lib/wiki-prompt.js), same ingested corpus, same model chain, same
        // post-processing as a forum thread. Nothing is posted to Discord.
        //
        // Exists so "did the answers actually improve?" can be measured against
        // known-bad historical questions instead of argued about.
        if (path === '/api/knowledge/test-wiki' && req.method === 'POST') {
            const { question, lang, threadName, conversationContext } = parsed;
            if (!question) return sendJSON(res, { error: 'question required' }, 400);
            try {
                const detectedLang = lang || detectLanguage(question);
                const langInfo = SUPPORTED_LANGUAGES[detectedLang] || SUPPORTED_LANGUAGES['EN-US'];
                const freshKnowledge = await getFreshKnowledge(false, detectedLang);
                const wikiLinks = WIKI_PAGES.map(page => {
                    const meta = getWikiPageMeta(page, detectedLang);
                    return `${meta?.title || page.replace(/-/g, ' ')}: <${wikiPageUrl(page, detectedLang)}>`;
                }).join('\n');

                const prompt = buildWikiAnswerPrompt({
                    question,
                    threadName: threadName || 'replay harness',
                    langInfo,
                    relevanceMap: buildWikiRelevanceMap(detectedLang),
                    wikiLinks,
                    freshKnowledge,
                    staticKnowledge: PUNCHY_STATIC_KNOWLEDGE,
                    customKnowledge: buildCustomKnowledge(),
                    conversationContext: conversationContext || '',
                });

                const raw = await callGeminiWiki(prompt);
                const answer = qualityCheckResponse(raw, detectedLang);
                return sendJSON(res, {
                    answer,
                    detectedLang,
                    promptChars: prompt.length,
                    wikiChars: (freshKnowledge || '').length,
                });
            } catch(e) { return sendJSON(res, { error: String(e.message) }, 500); }
        }

        // GET /api/faq
        if (path === '/api/faq' && req.method === 'GET') {
            return sendJSON(res, { embeds: faqEmbeds });
        }

        // POST /api/faq/save — direct save without AI
        if (path === '/api/faq/save' && req.method === 'POST') {
            const { embeds } = parsed;
            if (!Array.isArray(embeds)) return sendJSON(res, { error: 'embeds array required' }, 400);
            faqEmbeds = embeds;
            await saveFAQToGCS();
            return sendJSON(res, { message: `FAQ saved (${embeds.length} sections)` });
        }

        // POST /api/faq/edit — AI-powered edit
        if (path === '/api/faq/edit' && req.method === 'POST') {
            const { instruction } = parsed;
            if (!instruction) return sendJSON(res, { error: 'instruction required' }, 400);
            const fakeMsgObj = { content: `edit faq — ${instruction}`, author: { username: 'Dashboard' }, reply: async () => {} };
            await handleFAQEdit(fakeMsgObj);
            return sendJSON(res, { message: 'FAQ edit applied.' });
        }

        // GET /api/rules
        if (path === '/api/rules' && req.method === 'GET') {
            return sendJSON(res, { rules: rulesData });
        }

        // POST /api/rules/save — direct save without AI
        if (path === '/api/rules/save' && req.method === 'POST') {
            const { rules } = parsed;
            if (!Array.isArray(rules)) return sendJSON(res, { error: 'rules array required' }, 400);
            rulesData = rules;
            await saveRulesToGCS();
            return sendJSON(res, { message: `Rules saved (${rules.length} rules)` });
        }

        // POST /api/rules/edit — AI-powered edit
        if (path === '/api/rules/edit' && req.method === 'POST') {
            const { instruction } = parsed;
            if (!instruction) return sendJSON(res, { error: 'instruction required' }, 400);
            const fakeMsgObj = { content: `edit rules — ${instruction}`, author: { username: 'Dashboard' }, reply: async () => {} };
            await handleRulesEdit(fakeMsgObj);
            return sendJSON(res, { message: 'Rules edit applied.' });
        }

        // GET /api/solutions
        if (path === '/api/solutions' && req.method === 'GET') {
            return sendJSON(res, { solutions: SOLUTIONS_BY_VERSION, currentVersion: CURRENT_VERSION_SET });
        }

        // GET /api/system
        if (path === '/api/system' && req.method === 'GET') {
            return sendJSON(res, {
                uptime: uptime(), memory: process.memoryUsage(), nodeVersion: process.version,
                activeThreadCount: activeThreadIndex.size, processingCount: processingThreads.size,
                pausedCount: pausedThreads.size, ticketCount: ticketChannels.size,
            passiveMode: isPassiveModeActive(),
            passiveModeExpiry: passiveModeExpiry ? new Date(passiveModeExpiry).toISOString() : null,
                discordStatus: client.ws.status === 0 ? 'Connected' : 'Disconnected',
                solutionsVersion: CURRENT_VERSION_SET,
            });
        }

        // GET /api/modstats — latest snapshot summary (for live display)
        if (path === '/api/modstats' && req.method === 'GET') {
            const latest = modAnalyticsHistory[modAnalyticsHistory.length - 1] || null;
            const summary = buildModSummary(latest);
            return sendJSON(res, {
                latest,
                summary,
                snapshotCount: modAnalyticsHistory.length,
                nextRefresh: latest ? new Date(new Date(latest.timestamp).getTime() + MOD_ANALYTICS_INTERVAL_MS).toISOString() : null
            });
        }

        // GET /api/modstats/history — full snapshot history (for time-series charts)
        if (path === '/api/modstats/history' && req.method === 'GET') {
            // Optional ?limit=N to cap response size
            const url = new URL(req.url, `http://${req.headers.host}`);
            const limit = parseInt(url.searchParams.get('limit')) || modAnalyticsHistory.length;
            const trimmed = modAnalyticsHistory.slice(-limit);
            // Build a flat time-series suitable for chart libraries
            const series = trimmed.map(s => ({
                timestamp: s.timestamp,
                punchy_mr:        s.results.punchy_mr?.total ?? null,
                punchy_cf:        s.results.punchy_cf?.total ?? null,
                hmi_mr:           s.results.hmi_mr?.total ?? null,
                hmi_cf:           s.results.hmi_cf?.total ?? null,
                hmi_refoxed_cf:   s.results.hmi_refoxed_cf?.total ?? null,
                hmi_reforged_cf:  s.results.hmi_reforged_cf?.total ?? null,
                hmi_reforged_mr:  s.results.hmi_reforged_mr?.total ?? null,
            }));
            return sendJSON(res, { series, count: trimmed.length });
        }

        // POST /api/modstats/refresh — manual refresh trigger (admin)
        if (path === '/api/modstats/refresh' && req.method === 'POST') {
            try {
                const snap = await collectModSnapshot();
                await saveModSnapshotToGCS(snap);
                return sendJSON(res, { message: 'Refreshed', summary: buildModSummary(snap) });
            } catch(e) {
                return sendJSON(res, { error: e.message }, 500);
            }
        }

        // GET /api/dependents — last published results + live progress
        if (path === '/api/dependents' && req.method === 'GET') {
            const now = Date.now();
            const lastScrapedTs = punchyDependentsResults ? new Date(punchyDependentsResults.lastScraped).getTime() : null;
            return sendJSON(res, {
                results: punchyDependentsResults,
                isScrapingNow: isDependentsScraping,
                progress: punchyDependentsProgress,
                workingPartial: punchyDependentsWorking ? {
                    startedAt: punchyDependentsWorking.startedAt,
                    totalChecked: punchyDependentsWorking.totalChecked,
                    dependants: punchyDependentsWorking.dependants.length,
                    mentions: punchyDependentsWorking.mentions.length,
                    progressByType: punchyDependentsWorking.progressByType,
                } : null,
                nextChunk: lastScrapedTs ? new Date(lastScrapedTs + DEPENDENTS_CHUNK_INTERVAL_MS).toISOString() : null,
            });
        }

        // POST /api/dependents/refresh — manually run the next chunk now
        if (path === '/api/dependents/refresh' && req.method === 'POST') {
            if (isDependentsScraping) {
                return sendJSON(res, { error: 'A chunk is already running' }, 409);
            }
            // Fire-and-forget — chunk takes ~30s
            runDependentsChunk().catch(e => console.error('[dependents] manual chunk error:', e.message));
            return sendJSON(res, { message: 'Next chunk started — refresh in ~30s for updated progress' });
        }

        // GET /api/logs
        if (path === '/api/logs' && req.method === 'GET') {
            const logs = dashboardLogs.splice(0);
            return sendJSON(res, { logs });
        }

        // GET /api/dotcommands
        if (path === '/api/dotcommands' && req.method === 'GET') {
            return sendJSON(res, { commands: dotCommandsStore });
        }

        // POST /api/dotcommands/save — full replace
        if (path === '/api/dotcommands/save' && req.method === 'POST') {
            const { commands } = parsed;
            if (!Array.isArray(commands)) return sendJSON(res, { error: 'commands array required' }, 400);
            // Validate each entry
            for (const c of commands) {
                if (!c.command || !c.response) return sendJSON(res, { error: 'Each command needs command + response fields' }, 400);
                if (!/^[a-z0-9_-]+$/i.test(c.command)) return sendJSON(res, { error: `Invalid command name: ${c.command} (letters, numbers, - _ only)` }, 400);
            }
            dotCommandsStore = commands;
            await saveDotCommandsToGCS();
            return sendJSON(res, { message: `Saved ${commands.length} dot commands` });
        }

        // POST /api/dotcommands/add
        if (path === '/api/dotcommands/add' && req.method === 'POST') {
            const { command, response, description } = parsed;
            if (!command || !response) return sendJSON(res, { error: 'command and response required' }, 400);
            if (!/^[a-z0-9_-]+$/i.test(command)) return sendJSON(res, { error: 'Command name must be letters, numbers, - _ only' }, 400);
            if (dotCommandsStore.find(c => c.command.toLowerCase() === command.toLowerCase())) {
                return sendJSON(res, { error: `Command .${command} already exists` }, 400);
            }
            dotCommandsStore.push({ command: command.toLowerCase(), response, description: description || '' });
            await saveDotCommandsToGCS();
            return sendJSON(res, { message: `Added .${command}` });
        }

        // POST /api/dotcommands/delete
        if (path === '/api/dotcommands/delete' && req.method === 'POST') {
            const { command } = parsed;
            const before = dotCommandsStore.length;
            dotCommandsStore = dotCommandsStore.filter(c => c.command.toLowerCase() !== command?.toLowerCase());
            if (dotCommandsStore.length === before) return sendJSON(res, { error: `Command .${command} not found` }, 404);
            await saveDotCommandsToGCS();
            return sendJSON(res, { message: `Deleted .${command}` });
        }

        // POST /api/dotcommands/update
        if (path === '/api/dotcommands/update' && req.method === 'POST') {
            const { command, response, description } = parsed;
            const entry = dotCommandsStore.find(c => c.command.toLowerCase() === command?.toLowerCase());
            if (!entry) return sendJSON(res, { error: `Command .${command} not found` }, 404);
            if (response) entry.response = response;
            if (description !== undefined) entry.description = description;
            await saveDotCommandsToGCS();
            return sendJSON(res, { message: `Updated .${command}` });
        }
        if (path === '/api/reactions' && req.method === 'GET') {
            return sendJSON(res, { roles: reactionRolesStore });
        }

        // POST /api/reactions/add
        if (path === '/api/reactions/add' && req.method === 'POST') {
            const { messageId, emoji, roleId, description } = parsed;
            if (!messageId || !emoji || !roleId) return sendJSON(res, { error: 'messageId, emoji, roleId required' }, 400);
            reactionRolesStore.push({ messageId, emoji, roleId, description: description || '' });
            await saveReactionRolesToGCS();
            return sendJSON(res, { message: `Reaction role added: ${emoji} → role ${roleId}` });
        }

        // POST /api/reactions/delete
        if (path === '/api/reactions/delete' && req.method === 'POST') {
            const { index } = parsed;
            if (index < 0 || index >= reactionRolesStore.length) return sendJSON(res, { error: 'Invalid index' }, 400);
            const removed = reactionRolesStore.splice(index, 1)[0];
            await saveReactionRolesToGCS();
            return sendJSON(res, { message: `Removed reaction role ${removed.emoji}` });
        }

        // GET /api/channels
        if (path === '/api/channels' && req.method === 'GET') {
            const guild = client.guilds.cache.first();
            if (!guild) return sendJSON(res, { channels: [] });
            const channels = Array.from(guild.channels.cache.values())
                .filter(c => c.type !== 4) // exclude category channels from the list
                .sort((a, b) => (a.rawPosition || 0) - (b.rawPosition || 0))
                .map(c => ({
                    id: c.id, name: c.name, type: c.type?.toString() || 'GUILD_TEXT',
                    parentName: c.parent?.name || null, parentId: c.parentId || null,
                    topic: c.topic || null,
                }));
            return sendJSON(res, { channels });
        }

        // POST /api/channels/create
        if (path === '/api/channels/create' && req.method === 'POST') {
            const { name, type, topic, nsfw, parentId } = parsed;
            if (!name) return sendJSON(res, { error: 'name required' }, 400);
            const guild = client.guilds.cache.first();
            if (!guild) return sendJSON(res, { error: 'Guild not found' }, 500);
            const { ChannelType } = require('discord.js');
            const typeMap = {
                GUILD_TEXT: ChannelType.GuildText, GUILD_VOICE: ChannelType.GuildVoice,
                GUILD_FORUM: ChannelType.GuildForum, GUILD_ANNOUNCEMENT: ChannelType.GuildAnnouncement,
            };
            const ch = await guild.channels.create({
                name, topic: topic || undefined, nsfw: !!nsfw,
                parent: parentId || undefined,
                type: typeMap[type] ?? ChannelType.GuildText,
            });
            return sendJSON(res, { message: `Channel #${ch.name} created (${ch.id})` });
        }

        // GET /api/automessages
        if (path === '/api/automessages' && req.method === 'GET') {
            return sendJSON(res, { messages: autoMessagesStore });
        }

        // POST /api/automessages/add
        if (path === '/api/automessages/add' && req.method === 'POST') {
            const { channel, content, trigger, interval, sendAt } = parsed;
            if (!channel || !content || !trigger) return sendJSON(res, { error: 'channel, content, trigger required' }, 400);

            // Validate scheduled_once requires sendAt
            if (trigger === 'scheduled_once') {
                if (!sendAt) return sendJSON(res, { error: 'sendAt (ISO timestamp) required for scheduled_once' }, 400);
                const sendAtMs = new Date(sendAt).getTime();
                if (isNaN(sendAtMs)) return sendJSON(res, { error: 'sendAt must be a valid ISO timestamp' }, 400);
                if (sendAtMs <= Date.now()) return sendJSON(res, { error: 'sendAt must be in the future' }, 400);
            }

            const entry = { channel, content, trigger, interval: interval || 3600000, createdAt: new Date().toISOString() };
            if (trigger === 'scheduled_once') entry.sendAt = sendAt;
            autoMessagesStore.push(entry);
            await saveAutoMessagesToGCS();

            if (trigger === 'scheduled') {
                // Recurring interval
                const iv = setInterval(async () => {
                    try {
                        const ch = await client.channels.fetch(channel).catch(() => null)
                            || client.channels.cache.find(c => c.name === channel);
                        if (ch?.isTextBased()) await ch.send(content);
                    } catch(e) { console.log('Auto message error:', e.message); }
                }, entry.interval);
                autoMessageIntervals.push(iv);
            } else if (trigger === 'scheduled_once') {
                // One-time send at specific date/time
                const delay = new Date(sendAt).getTime() - Date.now();
                console.log(`📅 Scheduled one-time message for ${sendAt} (${Math.round(delay/60000)}min from now) → channel ${channel}`);
                const to = setTimeout(async () => {
                    try {
                        const ch = await client.channels.fetch(channel).catch(() => null)
                            || client.channels.cache.find(c => c.name === channel);
                        if (ch?.isTextBased()) {
                            await ch.send(content);
                            console.log(`✅ Sent scheduled message to channel ${channel}`);
                        }
                        // Remove from store after firing
                        const idx = autoMessagesStore.findIndex(m => m.sendAt === sendAt && m.channel === channel && m.content === content);
                        if (idx >= 0) {
                            autoMessagesStore.splice(idx, 1);
                            await saveAutoMessagesToGCS();
                        }
                    } catch(e) { console.error('Scheduled-once send error:', e.message); }
                }, delay);
                autoMessageIntervals.push(to);
            }
            return sendJSON(res, { message: `Auto message saved (trigger: ${trigger})` });
        }

        // POST /api/automessages/delete
        if (path === '/api/automessages/delete' && req.method === 'POST') {
            const { index } = parsed;
            if (index < 0 || index >= autoMessagesStore.length) return sendJSON(res, { error: 'Invalid index' }, 400);
            autoMessagesStore.splice(index, 1);
            await saveAutoMessagesToGCS();
            return sendJSON(res, { message: 'Auto message deleted' });
        }

        // POST /api/training/text
        if (path === '/api/training/text' && req.method === 'POST') {
            const { text, type: ttype, priority } = parsed;
            if (!text) return sendJSON(res, { error: 'text required' }, 400);
            const entry = { text, addedBy: 'Training Studio', addedAt: new Date().toISOString() };
            customKnowledgeEntries.push(entry);
            await saveCustomKnowledgeToGCS();
            trainingHistory.push({ type: 'text', preview: text.substring(0, 80), date: new Date().toISOString(), size: text.length });
            await saveTrainingHistoryToGCS();
            DYNAMIC_KNOWLEDGE_CACHE = {}; // invalidate cache
            return sendJSON(res, { message: `Training text saved and added to knowledge base (#${customKnowledgeEntries.length})` });
        }

        // POST /api/training/upload — multipart file upload
        if (path === '/api/training/upload' && req.method === 'POST') {
            try {
                // Parse multipart manually (basic implementation)
                const contentType = req.headers['content-type'] || '';
                const boundary = contentType.match(/boundary=([^\s;]+)/)?.[1];
                if (!boundary) return sendJSON(res, { error: 'No boundary in multipart' }, 400);

                // Get raw body
                const rawBody = await new Promise((resolve) => {
                    const chunks = [];
                    req.on('data', c => chunks.push(c));
                    req.on('end', () => resolve(Buffer.concat(chunks)));
                });

                // Split by boundary
                const boundaryBuf = Buffer.from('--' + boundary);
                let count = 0;
                const parts = rawBody.toString('latin1').split('--' + boundary);
                for (const part of parts) {
                    if (!part.includes('filename=')) continue;
                    const nameMatch = part.match(/filename="([^"]+)"/);
                    const fname = nameMatch?.[1] || 'upload.txt';
                    const bodyStart = part.indexOf('\r\n\r\n') + 4;
                    const bodyEnd = part.lastIndexOf('\r\n');
                    if (bodyStart < 4 || bodyEnd < 0) continue;
                    const fileContent = part.substring(bodyStart, bodyEnd);
                    if (fileContent.length > 100000) { // 100KB limit per file
                        continue;
                    }
                    // Add as knowledge entry
                    customKnowledgeEntries.push({ text: `[File: ${fname}]\n${fileContent.substring(0, 5000)}`, addedBy: 'Training Upload', addedAt: new Date().toISOString() });
                    trainingHistory.push({ type: 'file', name: fname, preview: fname, date: new Date().toISOString(), size: fileContent.length });
                    count++;
                }
                await saveCustomKnowledgeToGCS();
                await saveTrainingHistoryToGCS();
                DYNAMIC_KNOWLEDGE_CACHE = {};
                return sendJSON(res, { message: `${count} file(s) processed and added to knowledge base` });
            } catch(e) {
                return sendJSON(res, { error: 'Upload failed: ' + e.message }, 500);
            }
        }

        // POST /api/training/images
        if (path === '/api/training/images' && req.method === 'POST') {
            try {
                const contentType = req.headers['content-type'] || '';
                const boundary = contentType.match(/boundary=([^\s;]+)/)?.[1];
                const rawBody = await new Promise((resolve) => {
                    const chunks = [];
                    req.on('data', c => chunks.push(c));
                    req.on('end', () => resolve(Buffer.concat(chunks)));
                });
                const parts = rawBody.toString('latin1').split('--' + (boundary||''));
                let context = '';
                let imgCount = 0;
                for (const part of parts) {
                    if (part.includes('name="context"')) {
                        const bodyStart = part.indexOf('\r\n\r\n') + 4;
                        context = part.substring(bodyStart).replace(/\r\n--$/, '').trim();
                    } else if (part.includes('filename=')) {
                        const nameMatch = part.match(/filename="([^"]+)"/);
                        const fname = nameMatch?.[1] || 'image.png';
                        // Accept any file with an image extension
                        if (/\.(png|jpg|jpeg|gif|webp|bmp|svg)$/i.test(fname)) {
                            trainingHistory.push({ type: 'image', name: fname, preview: fname + (context ? ` (${context.substring(0,40)})` : ''), date: new Date().toISOString(), size: 0 });
                            imgCount++;
                        }
                    }
                }
                if (context) {
                    customKnowledgeEntries.push({ text: `[Image training context]: ${context}`, addedBy: 'Training Studio', addedAt: new Date().toISOString() });
                    await saveCustomKnowledgeToGCS();
                }
                await saveTrainingHistoryToGCS();
                DYNAMIC_KNOWLEDGE_CACHE = {};
                return sendJSON(res, { message: `${imgCount} image(s) logged` + (context ? ` with context: "${context.substring(0,50)}"` : '') });
            } catch(e) {
                return sendJSON(res, { error: 'Image upload failed: ' + e.message }, 500);
            }
        }

        // GET /api/training/history
        if (path === '/api/training/history' && req.method === 'GET') {
            return sendJSON(res, { items: trainingHistory.slice().reverse() });
        }

        // POST /api/training/delete
        if (path === '/api/training/delete' && req.method === 'POST') {
            const { index } = parsed;
            const reversed = trainingHistory.slice().reverse();
            const actualIndex = trainingHistory.length - 1 - index;
            if (actualIndex < 0 || actualIndex >= trainingHistory.length) return sendJSON(res, { error: 'Invalid index' }, 400);
            trainingHistory.splice(actualIndex, 1);
            await saveTrainingHistoryToGCS();
            return sendJSON(res, { message: 'Training item deleted' });
        }

        // POST /api/action/*
        if (path.startsWith('/api/action/') && req.method === 'POST') {
            const action = path.replace('/api/action/', '');
            if (action === 'refresh-knowledge') {
                DYNAMIC_KNOWLEDGE_CACHE = {};
                getFreshKnowledge(true).catch(() => {});
                return sendJSON(res, { message: 'Knowledge cache cleared and refreshing...' });
            }
            if (action === 'post-faq') {
                const faqChannel = await client.channels.fetch(FAQ_CHANNEL_ID).catch(() => null);
                if (!faqChannel) return sendJSON(res, { error: 'FAQ channel not found' }, 500);
                let posted = 0, edited = 0;
                for (const e of faqEmbeds) {
                    const text = `**${e.title}**\n\n${e.description || '*(no content)*'}`.substring(0, 1990);
                    const existingId = faqMessageIds[e.id];
                    if (existingId) {
                        try { const msg = await faqChannel.messages.fetch(existingId); if (msg.content !== text) { await msg.edit(text); edited++; } continue; } catch(err) { delete faqMessageIds[e.id]; }
                    }
                    const sent = await faqChannel.send(text); faqMessageIds[e.id] = sent.id; posted++;
                }
                await saveFAQToGCS();
                return sendJSON(res, { message: `FAQ updated: ${posted} new, ${edited} edited` });
            }
            if (action === 'post-rules') {
                const rulesChannel = await client.channels.fetch(RULES_CHANNEL_ID).catch(() => null);
                if (!rulesChannel) return sendJSON(res, { error: 'Rules channel not found' }, 500);
                let posted = 0, edited = 0;
                for (const r of rulesData) {
                    const text = `**${r.number}.│${r.title}**\n${r.body}`.substring(0, 1990);
                    const existingId = rulesMessageIds[r.id];
                    if (existingId) {
                        try { const msg = await rulesChannel.messages.fetch(existingId); if (msg.content !== text) { await msg.edit(text); edited++; } continue; } catch(err) { delete rulesMessageIds[r.id]; }
                    }
                    const sent = await rulesChannel.send(text); rulesMessageIds[r.id] = sent.id; posted++;
                }
                await saveRulesToGCS();
                return sendJSON(res, { message: `Rules updated: ${posted} new, ${edited} edited` });
            }
            if (action === 'refresh-versions') { await fetchModrinthVersions(); return sendJSON(res, { message: 'Modrinth versions refreshed' }); }
            if (action === 'clear-thread-index') { activeThreadIndex.clear(); return sendJSON(res, { message: 'Thread index cleared' }); }
            if (action === 'reset-faq') { faqEmbeds = JSON.parse(JSON.stringify(DEFAULT_FAQ_EMBEDS)); faqMessageIds = {}; await saveFAQToGCS(); return sendJSON(res, { message: 'FAQ reset to defaults' }); }
            if (action === 'reset-rules') { rulesData = JSON.parse(JSON.stringify(DEFAULT_RULES)); rulesMessageIds = {}; await saveRulesToGCS(); return sendJSON(res, { message: 'Rules reset to defaults' }); }
            if (action === 'clear-warnings') { moderationData = {}; await saveModerationToGCS(); return sendJSON(res, { message: 'All warnings cleared' }); }
            if (action === 'clear-solutions') { SOLUTIONS_BY_VERSION = {}; await saveSolutionsToGCS(); return sendJSON(res, { message: 'All solutions cleared' }); }
            if (action === 'restart') { sendJSON(res, { message: 'Restarting in 1s...' }); setTimeout(() => process.exit(0), 1000); return; }
            return sendJSON(res, { error: 'Unknown action' }, 404);
        }

        return sendJSON(res, { error: 'Not found' }, 404);
    }

    // Root — redirect to dashboard
    if (path === '/') {
        res.writeHead(302, { 'Location': '/dashboard' });
        res.end();
        return;
    }

    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('Not found');
});

// Dashboard log buffer — captures recent console activity
const dashboardLogs = [];
const origLog = console.log.bind(console);
const origError = console.error.bind(console);
const origWarn = console.warn.bind(console);
console.log = (...args) => {
    origLog(...args);
    const text = args.join(' ');
    let type = 'default';
    if (text.includes('✅')) type = 'success';
    else if (text.includes('📌') || text.includes('🔄') || text.includes('thread')) type = 'info';
    dashboardLogs.push({ text, type, time: Date.now() });
    if (dashboardLogs.length > 200) dashboardLogs.shift();
};
console.error = (...args) => {
    origError(...args);
    dashboardLogs.push({ text: args.join(' '), type: 'error', time: Date.now() });
    if (dashboardLogs.length > 200) dashboardLogs.shift();
};
console.warn = (...args) => {
    origWarn(...args);
    dashboardLogs.push({ text: args.join(' '), type: 'warn', time: Date.now() });
    if (dashboardLogs.length > 200) dashboardLogs.shift();
};

dashboardServer.listen(PORT, () => {
    console.log(`🚀 Shubba running on port ${PORT} — Dashboard at /dashboard`);
});

// --- 1. CONFIGURATION ---
// SECRETS ARE ENV-ONLY. Nothing sensitive is hardcoded here so this file is
// safe to commit to a public repo. Set these in the SparkedHost panel
// (Startup → Variables) or a local .env. Missing required ones fail fast below.
const DISCORD_TOKEN = process.env.DISCORD_TOKEN;
const CLIENT_ID     = process.env.CLIENT_ID || '1465165237358559386';
const GEMINI_API_KEY = process.env.GEMINI_API_KEY;

// ── GEMINI MODEL ROUTING (multi-model failover) ───────────────────────────
// Each free-tier model has its OWN daily quota bucket, so when one model hits
// its cap, Shubba rotates to the next instead of going down. Chains are tried
// left→right; a model that 429s (daily) is parked until 00:00 UTC, a model that
// 404s (not enabled on this key) is dropped for the process. See lib/gemini-chain.js.
//
// Defaults promote support replies from flash-lite → flash (smarter) with
// flash-lite as the safety net. To jump to the newer 3.x line once you've
// confirmed it's enabled on your key, just set the chain env vars — no redeploy:
//   GEMINI_CHAIN_STANDARD="gemini-3.5-flash,gemini-2.5-flash,gemini-2.5-flash-lite"
//   GEMINI_CHAIN_WIKI="gemini-3.5-flash,gemini-2.5-flash,gemini-2.5-flash-lite"
// Legacy single-model vars (GEMINI_MODEL_STANDARD / _WIKI) still work — they're
// pinned to the FRONT of the chain for backward compatibility.
// Defaults lead with gemini-3.7-flash and fall back across FIVE separate
// free-quota buckets:
//   3.7-flash → 3.6-flash → 3.5-flash → 2.5-flash → 2.5-flash-lite
//
// Why 3.7-flash at the front (verified 2026-08-14 against Google's own docs):
//   - Model ID confirmed on https://ai.google.dev/gemini-api/docs/models and its
//     dedicated page https://ai.google.dev/gemini-api/docs/models/gemini-3.7-flash
//     (page last updated 2026-08-13). Guessing an ID would 404 it out of the
//     chain silently, so these were read off the docs, not assumed.
//   - https://ai.google.dev/gemini-api/docs/pricing lists it as "Free of charge"
//     on the free tier, same as every other model in this chain.
//   - Google bills it as their most capable Flash model, aimed at complex
//     reasoning — which is exactly this workload: log/crash triage plus
//     multilingual replies (EN/BR/ES/RU) in one turn.
//   3.6-flash stays as the immediate fallback because it is the model already
//   verified working on this project's key, so a bad rollout degrades by one
//   notch instead of going down.
//
// Any model not enabled on a given key is auto-dropped (404) at runtime, so
// leading with the newest is safe even on older keys.
const GEMINI_CHAIN_STANDARD = parseChain(
    process.env.GEMINI_CHAIN_STANDARD || 'gemini-3.7-flash,gemini-3.6-flash,gemini-3.5-flash,gemini-2.5-flash,gemini-2.5-flash-lite',
    process.env.GEMINI_MODEL_STANDARD // legacy override → front of chain
);
const GEMINI_CHAIN_WIKI = parseChain(
    process.env.GEMINI_CHAIN_WIKI || 'gemini-3.7-flash,gemini-3.6-flash,gemini-3.5-flash,gemini-2.5-flash,gemini-2.5-flash-lite',
    process.env.GEMINI_MODEL_WIKI
);
// Back-compat: some older code paths still read these single names.
const GEMINI_MODEL_STANDARD = GEMINI_CHAIN_STANDARD[0];
const GEMINI_MODEL_WIKI     = GEMINI_CHAIN_WIKI[0];

// The runner is built lazily (after geminiLimiter is defined further down).
let _geminiRunner = null;
function getGeminiRunner() {
    if (!_geminiRunner) {
        _geminiRunner = createGeminiRunner({
            apiKey: GEMINI_API_KEY,
            httpPost: axios.post,
            limiter: (typeof geminiLimiter !== 'undefined') ? geminiLimiter : null,
            log: (m) => console.log(m),
        });
    }
    return _geminiRunner;
}
