// Fail fast with a clear message if required secrets are missing, instead of
// dying deep inside a Discord/Gemini call with a cryptic error.
(function requireSecrets() {
    const missing = [];
    if (!DISCORD_TOKEN) missing.push('DISCORD_TOKEN');
    if (!GEMINI_API_KEY) missing.push('GEMINI_API_KEY');
    if (missing.length) {
        console.error('❌ Missing required environment variable(s): ' + missing.join(', '));
        console.error('   Set them in the SparkedHost panel (Startup → Variables) or a local .env file.');
        console.error('   Secrets are no longer hardcoded — see docs/DEPLOY.md.');
        process.exit(1);
    }

    // Optional secrets: the bot still boots, but the feature they gate stays OFF.
    // Reported (not fatal) so a half-configured host is obvious from the log.
    // NOTE: only vars declared ABOVE this point may be referenced here — later
    // `const`s (CF_API_KEY, TRELLO_KEY, …) are still in the temporal dead zone
    // and warn at their own declaration instead.
    if (!DASHBOARD_ENABLED) {
        console.warn('⚠️ DASHBOARD_USER / DASHBOARD_PASS not set — the admin dashboard is LOCKED.');
        console.warn('   Every /dashboard, /admin and /api request will get 401 until both are set.');
        console.warn('   This is intentional: the panel is exposed on a public IP, so it never');
        console.warn('   falls back to a built-in password. See .env.example and docs/DEPLOY.md.');
    }
})();

// One-time startup fingerprint (safe: length + last 4 chars only) so a bad key
// source can be confirmed via the log file without exposing the secret.
shubbaLogError('startup-diag', `GEMINI key len=${GEMINI_API_KEY.length} tail=…${GEMINI_API_KEY.slice(-4)} | standard=${GEMINI_CHAIN_STANDARD[0]}`);

// ── GROQ (alternative AI provider — set USE_GROQ=true to use) ─────────────
// NOTE: Groq's free tier has a 12,000 TPM (tokens-per-minute) limit, which is
// too small for Shubba's prompts (typically 30-40k tokens once knowledge base
// is included). To use Groq, you need their Dev tier (paid).
// Default is OFF — Shubba uses Gemini paid tier instead.
const GROQ_API_KEY = process.env.GROQ_API_KEY || ''; // optional; only used when USE_GROQ=true
const GROQ_URL = 'https://api.groq.com/openai/v1/chat/completions';
const GROQ_MODEL = process.env.GROQ_MODEL || 'llama-3.3-70b-versatile';
const USE_GROQ = process.env.USE_GROQ === 'true'; // default OFF
// ───────────────────────────────────────────────────────────────────────────

/**
 * Determine if a task needs advanced thinking or can use flash response
 * @param {string} content - Message content
 * @param {boolean} hasLogFile - Whether log files are present
 * @param {boolean} isDeepAnalysis - Whether this is a deep analysis request
 * @returns {object} - { useThinking: boolean, reason: string }
 */
function shouldUseThinking(content, hasLogFile = false, isDeepAnalysis = false) {
    const contentLower = content.toLowerCase();
    
    // Always use thinking for deep analysis
    if (isDeepAnalysis || hasLogFile) {
        return { useThinking: true, reason: "Deep analysis with log files" };
    }
    
    // Use thinking for complex troubleshooting
    const complexKeywords = [
        'crash', 'error', 'not working', 'broken', 'bug',
        'conflict', 'incompatible', 'issue', 'problem',
        'analyze', 'debug', 'investigate', 'diagnose'
    ];
    
    const hasComplexKeyword = complexKeywords.some(keyword => contentLower.includes(keyword));
    
    // Use thinking if message is long and complex
    const isLongMessage = content.length > 200;
    const hasMultipleQuestions = (content.match(/\?/g) || []).length > 1;
    
    if (hasComplexKeyword && (isLongMessage || hasMultipleQuestions)) {
        return { useThinking: true, reason: "Complex troubleshooting request" };
    }
    
    // Use flash for simple questions and responses
    const simplePatterns = [
        /what\s+(is|are)\s+the\s+latest/i,
        /how\s+to\s+install/i,
        /where\s+(can|do)\s+i/i,
        /^(hi|hello|hey|thanks|thank you)/i,
        /which\s+version/i
    ];
    
    if (simplePatterns.some(pattern => pattern.test(content))) {
        return { useThinking: false, reason: "Simple question" };
    }
    
    // Default: use flash for efficiency
    return { useThinking: false, reason: "Standard response" };
}

/**
 * Call Groq's Llama model with the OpenAI-compatible chat completions API.
 * Used as the primary AI backend (fast, free tier, 70B param model).
 *
 * Auto-retries on transient errors (5xx, network) but not on 4xx (auth, malformed).
 * Honors Groq's Retry-After header on 429.
 */
async function callGroq(prompt, opts = {}) {
    const { temperature = 0.7, maxTokens = 8192, label = 'standard' } = opts;
    console.log(`⚡ Calling Groq ${GROQ_MODEL} (${label})`);

    let lastErr;
    for (let attempt = 0; attempt < 3; attempt++) {
        try {
            return await geminiLimiter.execute(async () => {
                const res = await axios.post(GROQ_URL, {
                    model: GROQ_MODEL,
                    messages: [{ role: 'user', content: prompt }],
                    temperature,
                    max_tokens: maxTokens
                }, {
                    headers: {
                        'Authorization': `Bearer ${GROQ_API_KEY}`,
                        'Content-Type': 'application/json'
                    },
                    timeout: 120000,
                    maxContentLength: 100 * 1024 * 1024
                });

                const text = res.data?.choices?.[0]?.message?.content;
                if (!text) throw new Error('Empty Groq response');
                return text;
            });
        } catch (err) {
            lastErr = err;
            const apiMsg = err.response?.data?.error?.message || err.response?.data?.error || '';
            if (apiMsg) console.error(`🔴 Groq API error: ${apiMsg}`);

            const status = err.response?.status;
            // 429 — honor Retry-After if Groq sends it, otherwise fall through to retry
            if (status === 429) {
                const retryAfter = parseInt(err.response.headers?.['retry-after']) || 30;
                console.warn(`⚠️ Groq 429 (rate limit). Waiting ${retryAfter}s...`);
                await new Promise(r => setTimeout(r, retryAfter * 1000));
                continue;
            }
            // Other 4xx — don't retry, the request is broken
            if (status && status >= 400 && status < 500) {
                console.error(`❌ Groq returned ${status} — not retrying`);
                throw err;
            }

            if (attempt < 2) {
                const delay = (attempt + 1) * 3000;
                console.warn(`⚠️ Groq attempt ${attempt + 1} failed (${err.message}), retrying in ${delay / 1000}s...`);
                await new Promise(r => setTimeout(r, delay));
            }
        }
    }
    throw lastErr;
}

/**
 * Build the generationConfig for ONE specific model in a chain.
 *
 * generationConfig is not model-agnostic, and the chain aborts on 400 by design
 * (so real bugs aren't masked). That combination means a knob the front model
 * accepts but the tail model rejects would take the whole chain down instead of
 * failing over — the cheap safety-net model would never get to serve. So the
 * config is resolved per model rather than once for the front of the chain.
 *
 * thinkingBudget:-1 = dynamic budget (model decides how much to think). Gemini 3
 * prefers `thinking_level`, but Google's docs state thinking_budget "remains
 * supported for backward compatibility", and thinkingBudget is what this key is
 * already verified working with — so we keep it rather than swap in a field name
 * we could not confirm the exact REST spelling of. Sending both would be a 400.
 */
function buildGenConfig(model, { temperature, maxOutputTokens, useThinking }) {
    const cfg = { temperature, maxOutputTokens };
    // flash-lite is the last-resort bucket; it is kept on a plain config so it
    // can always answer, whatever the smarter models upstream were configured for.
    if (useThinking && model && !model.includes('flash-lite')) {
        cfg.thinkingConfig = { thinkingBudget: -1 };
    }
    return cfg;
}

/**
 * Call Gemini with automatic multi-model failover and retry on transient failures.
 * 4xx errors are never retried — they indicate a permanent problem.
 *
 * useThinking=false → thinkingConfig omitted entirely (2.5 Pro rejects thinkingBudget:0)
 * useThinking=true  → thinkingBudget:-1 (dynamic budget, model decides how much to think)
 */
async function callGemini(prompt, useThinking = false) {
    // Route to Groq if enabled (default OFF — Groq's 12k TPM too small for Shubba's prompts)
    if (USE_GROQ) {
        return callGroq(prompt, { temperature: 0.7, maxTokens: 8192, label: 'standard' });
    }
    const { text } = await getGeminiRunner().runGeminiChain(prompt, {
        models: GEMINI_CHAIN_STANDARD,
        genConfigFor: (model) => buildGenConfig(model, { temperature: 0.7, maxOutputTokens: 8192, useThinking }),
        timeout: 120000,
        label: `standard(thinking:${useThinking})`,
    });
    return text;
}

/**
 * Wiki-specific Gemini call — uses thinking mode for deeper reasoning
 * and higher output tokens to allow thorough, well-referenced answers.
 */
async function callGeminiWiki(prompt) {
    // Route to Groq if enabled — use larger output budget for wiki-deep responses
    if (USE_GROQ) {
        return callGroq(prompt, { temperature: 0.5, maxTokens: 8000, label: 'wiki-deep' });
    }
    const { text } = await getGeminiRunner().runGeminiChain(prompt, {
        models: GEMINI_CHAIN_WIKI,
        genConfigFor: (model) => buildGenConfig(model, { temperature: 0.5, maxOutputTokens: 16384, useThinking: true }),
        timeout: 180000,
        label: 'wiki-deep',
    });
    return text;
}

