async function updateAddonPinnedPost(guild) {
    try {
        const forum = await client.channels.fetch(ADDON_FORUM_ID).catch(() => null);
        if (!forum) return;
        const content = await buildAddonPinnedContent(guild);

        // Always prefer the hardcoded canonical post ID. This prevents Shubba from
        // ever creating a duplicate when the original post falls out of the
        // recent-archived window or the in-memory ID drifts.
        const targetThreadId = ADDON_PINNED_POST_ID || addonPinnedMessageId;

        if (targetThreadId) {
            // Fetch the thread directly by ID — bypasses the 20-archived limit
            try {
                const pinnedThread = await client.channels.fetch(targetThreadId).catch(() => null);
                if (pinnedThread && pinnedThread.parentId === ADDON_FORUM_ID) {
                    // Unarchive if archived (so we can edit)
                    if (pinnedThread.archived) {
                        await pinnedThread.setArchived(false).catch(() => {});
                    }
                    const starter = await pinnedThread.fetchStarterMessage().catch(() => null);
                    if (starter) {
                        await starter.edit(content);
                        // Persist the canonical ID so storage stays consistent
                        if (addonPinnedMessageId !== targetThreadId) {
                            addonPinnedMessageId = targetThreadId;
                            await saveAddonRolesToGCS();
                        }
                        console.log(`✅ Updated existing addon pinned post (${targetThreadId})`);
                        return;
                    } else {
                        console.warn(`⚠️ Pinned post ${targetThreadId} exists but has no starter message — skipping (will not recreate)`);
                        return; // DO NOT recreate — the post exists, we just couldn't fetch the starter
                    }
                } else {
                    console.warn(`⚠️ Hardcoded addon pinned post ${targetThreadId} not found — bot needs review before creating new one`);
                    // Don't auto-create when there's a hardcoded ID set — that would mean the canonical
                    // post was deleted, which warrants manual confirmation.
                    return;
                }
            } catch(e) {
                console.log('⚠️ Could not update pinned addon post:', e.message);
                return; // Don't fall through to create — preserves the existing post
            }
        }

        // Only reaches here if no canonical ID is set AND no stored ID exists
        console.log('ℹ️ No addon pinned post ID known — creating new canonical post...');

        // Create the pinned post if it doesn't exist
        // Re-fetch the forum to ensure availableTags is populated
        const freshForum = await client.channels.fetch(ADDON_FORUM_ID, { force: true }).catch(() => forum);
        const allTags = freshForum.availableTags || [];
        console.log(`🏷️ Addon forum tags available: ${allTags.map(t => t.name).join(', ') || 'none'}`);

        const tagNames = ['⏯️ Animation Pack', '⚙️ Mod Compat', '🛠️ Position Fix'];
        const appliedTags = allTags
            .filter(t => tagNames.some(n => t.name === n))
            .map(t => t.id);

        // If we still have no tags, use the first available tag as fallback
        if (!appliedTags.length && allTags.length) {
            appliedTags.push(allTags[0].id);
            console.log(`⚠️ Target tags not found, using fallback tag: ${allTags[0].name}`);
        }

        const thread = await freshForum.threads.create({
            name: '📌 About This Forum — Read First',
            message: { content },
            appliedTags: appliedTags.length ? appliedTags : undefined,
            reason: 'Shubba auto-created addon forum instructions',
        });
        // Pin it
        await thread.pin().catch(() => {});
        addonPinnedMessageId = thread.id;
        await saveAddonRolesToGCS();
        console.log('✅ Addon forum pinned post created');
    } catch(e) { console.log('⚠️ updateAddonPinnedPost error:', e.message); }
}

/**
 * Back-register every existing addon forum thread into addonRolesStore.
 *
 * Why this exists: addonRolesStore only gets populated at thread create time.
 * Threads that pre-date Shubba's addon-tracking system never got registered,
 * which causes /editrole, /deleterole, /createrole etc. to error with
 * "This thread isn't registered as an addon post."
 *
 * This walks all active + archived threads in the addon forum and registers
 * any that are missing. If a role with the matching name (or "addon-<thread name>"
 * pattern) already exists in the guild, it auto-links it.
 */
async function backRegisterExistingAddons(guild) {
    try {
        const forum = await client.channels.fetch(ADDON_FORUM_ID).catch(() => null);
        if (!forum) return;

        // Collect all threads in the forum (active + archived)
        const seen = new Set();
        const allThreads = [];

        const active = await forum.threads.fetchActive().catch(() => null);
        if (active) {
            for (const [, t] of active.threads) {
                if (!seen.has(t.id)) { seen.add(t.id); allThreads.push(t); }
            }
        }

        // Walk archived in pages — Discord limits each page, so paginate via `before`
        let lastBefore = undefined;
        let archivedFetched = 0;
        const ARCHIVED_CAP = 500;
        while (archivedFetched < ARCHIVED_CAP) {
            const arc = await forum.threads.fetchArchived({ limit: 100, before: lastBefore }).catch(() => null);
            if (!arc || arc.threads.size === 0) break;
            for (const [, t] of arc.threads) {
                if (!seen.has(t.id)) { seen.add(t.id); allThreads.push(t); }
            }
            archivedFetched += arc.threads.size;
            const oldest = Array.from(arc.threads.values()).sort((a,b) => a.archiveTimestamp - b.archiveTimestamp)[0];
            if (!oldest) break;
            lastBefore = oldest.id;
            if (!arc.hasMore) break;
        }

        let registered = 0;
        let linkedRoles = 0;

        for (const thread of allThreads) {
            // Skip the pinned info post itself
            if (thread.id === ADDON_PINNED_POST_ID) continue;

            if (addonRolesStore[thread.id]) continue; // already registered

            // Try to find a matching role for this thread by name.
            // Existing addon roles in your server appear to follow the thread title;
            // we attempt a few common naming patterns to auto-link them.
            const candidates = [
                thread.name,
                thread.name.toLowerCase(),
                `addon-${thread.name.toLowerCase()}`,
                `${thread.name} addon`,
            ];
            const role = guild.roles.cache.find(r =>
                candidates.some(c => r.name.toLowerCase() === c.toLowerCase())
            );

            addonRolesStore[thread.id] = {
                threadId: thread.id,
                threadName: thread.name,
                roleId: role ? role.id : null,
                roleName: role ? role.name : null,
                creatorId: thread.ownerId || null,
                pendingReactors: [],
                backRegistered: true, // flag so we know this wasn't created live
            };
            registered++;
            if (role) linkedRoles++;
        }

        if (registered > 0) {
            await saveAddonRolesToGCS();
            console.log(`🔧 Back-registered ${registered} existing addon thread(s) — auto-linked ${linkedRoles} role(s) by name`);
        } else {
            console.log(`✅ All ${allThreads.length} addon threads already registered`);
        }
    } catch(e) {
        console.log('⚠️ backRegisterExistingAddons error:', e.message);
    }
}

/**
 * Comprehensive post-migration audit:
 *   1. For every addon thread missing a roleId, infer the correct role from
 *      🔥-reactor overlap with role members. Uses GLOBAL assignment so each
 *      role is linked to at most one thread (no duplicates).
 *   2. For every (now-linked) addon thread, apply the role to every 🔥-reactor
 *      who doesn't have it yet.
 *
 * Safe to run repeatedly — only adds roles, never removes them.
 */
async function auditAddonRoles(guild) {
    const addons = Object.values(addonRolesStore).filter(a => a.threadId);
    if (!addons.length) return;
    console.log(`🔍 Comprehensive addon audit on ${addons.length} thread(s)...`);

    // Pre-fetch all guild members so role.members works without per-call API hits
    try { await guild.members.fetch(); } catch(e) { console.warn('⚠️ Could not pre-fetch members:', e.message); }

    // ── DEDUP PASS: clean up any existing duplicates in the store ───────────
    // (Could happen if a previous audit greedily linked the same role to multiple
    // threads. We keep the FIRST thread that claims each roleId, null the rest.)
    {
        const claimedRoleIds = new Set();
        let cleared = 0;
        for (const addon of Object.values(addonRolesStore)) {
            if (!addon.roleId) continue;
            if (claimedRoleIds.has(addon.roleId)) {
                console.log(`🧹 Clearing duplicate role link on thread "${addon.threadName}" (role ${addon.roleId} already linked to another thread)`);
                addon.roleId = null;
                addon.roleName = null;
                cleared++;
            } else {
                claimedRoleIds.add(addon.roleId);
            }
        }
        if (cleared > 0) console.log(`🧹 Cleared ${cleared} duplicate role link(s)`);
    }

    // ── COLLECT: compute reactor sets + candidate scores for unlinked threads ─
    const threadData = []; // { addon, reactorIds, candidates: [{ roleId, role, ratio, overlap }] }
    for (const addon of addons) {
        try {
            const thread = await client.channels.fetch(addon.threadId).catch(() => null);
            if (!thread) continue;

            const starter = await thread.fetchStarterMessage().catch(() => null);
            if (!starter) continue;

            const reaction = starter.reactions.cache.get('🔥') ||
                Array.from(starter.reactions.cache.values()).find(r => r.emoji.name === '🔥');

            const reactorIds = new Set();
            if (reaction) {
                const reactors = await reaction.users.fetch().catch(() => null);
                if (reactors) {
                    for (const [uid, u] of reactors) {
                        if (!u.bot) reactorIds.add(uid);
                    }
                }
            }

            const entry = { addon, reactorIds, candidates: [] };

            if (!addon.roleId && reactorIds.size > 0) {
                for (const [roleId, role] of guild.roles.cache) {
                    if (role.id === guild.id) continue;
                    if (role.managed) continue;
                    if (role.members.size === 0) continue;
                    if (role.members.size > 200) continue;

                    let overlap = 0;
                    for (const memberId of role.members.keys()) {
                        if (reactorIds.has(memberId)) overlap++;
                    }
                    if (overlap < 2) continue;

                    const ratio = overlap / role.members.size;
                    if (ratio < 0.5) continue; // require ≥50% match

                    entry.candidates.push({ roleId, role, ratio, overlap });
                }
            }
            threadData.push(entry);
        } catch(e) {
            console.log(`⚠️ Audit collect error for ${addon.threadId}: ${e.message}`);
        }
    }

    // ── ASSIGN: greedy global matching by descending score ──────────────────
    // Build flat list of (thread, candidate) pairs across all threads, sort by
    // (ratio desc, overlap desc), then walk it assigning each role to the FIRST
    // thread that wants it (and that hasn't been claimed yet).
    const claimedRoles = new Set();
    // Pre-claim any roles already linked elsewhere in the store so we don't try
    // to re-assign them.
    for (const addon of Object.values(addonRolesStore)) {
        if (addon.roleId) claimedRoles.add(addon.roleId);
    }
    const claimedThreads = new Set();

    const pairs = [];
    for (const entry of threadData) {
        if (entry.addon.roleId) continue; // already linked
        for (const cand of entry.candidates) {
            pairs.push({ entry, cand });
        }
    }
    pairs.sort((a, b) => {
        if (b.cand.ratio !== a.cand.ratio) return b.cand.ratio - a.cand.ratio;
        return b.cand.overlap - a.cand.overlap;
    });

    let totalRelinked = 0;
    for (const { entry, cand } of pairs) {
        if (claimedRoles.has(cand.roleId)) continue;
        if (claimedThreads.has(entry.addon.threadId)) continue;

        // Overlap alone is not evidence. A two-member role whose holders both
        // reacted scored 100% under the old thresholds — that is how "Helper"
        // got attached to an addon post and then handed to every reactor.
        const verdict = canAutoLinkRole(cand.role, entry.addon, cand);
        if (!verdict.allowed) {
            console.log(`🛑 Not linking "${entry.addon.threadName}" → "${cand.role.name}": ${verdict.reason}`);
            continue;
        }

        entry.addon.roleId = cand.roleId;
        entry.addon.roleName = cand.role.name;
        claimedRoles.add(cand.roleId);
        claimedThreads.add(entry.addon.threadId);
        totalRelinked++;
        console.log(`🔗 Linked thread "${entry.addon.threadName}" → role "${cand.role.name}" (${cand.overlap}/${cand.role.members.size} reactors match, ${Math.round(cand.ratio*100)}% ratio)`);
    }

    // ── PHASE 2: Apply role to missing reactors ─────────────────────────────
    let totalFixed = 0;
    for (const entry of threadData) {
        const { addon, reactorIds } = entry;
        if (!addon.roleId || reactorIds.size === 0) continue;

        let fixed = 0;
        for (const userId of reactorIds) {
            try {
                const member = await guild.members.fetch(userId).catch(() => null);
                if (!member) continue;
                if (!member.roles.cache.has(addon.roleId)) {
                    await member.roles.add(addon.roleId, 'Addon audit: 🔥 reactor restored after migration');
                    fixed++;
                }
            } catch(e) {}
        }
        if (fixed > 0) {
            console.log(`✅ Applied "${addon.roleName}" to ${fixed} missing reactor(s) in "${addon.threadName}"`);
            totalFixed += fixed;
        }
    }

    if (totalRelinked > 0 || totalFixed > 0) {
        await saveAddonRolesToGCS();
        console.log(`✅ Audit complete — re-linked ${totalRelinked} role(s), restored ${totalFixed} missing assignment(s)`);
    } else {
        console.log(`✅ Audit complete — all addon roles correctly linked and assigned`);
    }
}

