async function loadDashboardStores() {
    try {
        const bucket = storage.bucket(BUCKET_NAME);

        // Load reaction roles
        try {
            const [rrExists] = await bucket.file('reaction_roles.json').exists();
            if (rrExists) {
                const [rrContents] = await bucket.file('reaction_roles.json').download();
                reactionRolesStore = JSON.parse(rrContents.toString('utf8')).roles || [];
            }
        } catch(e) { console.log('⚠️ Reaction roles load error:', e.message); }

        // Load auto messages and restart scheduled ones
        try {
            const [amExists] = await bucket.file('auto_messages.json').exists();
            if (amExists) {
                const [amContents] = await bucket.file('auto_messages.json').download();
                autoMessagesStore = JSON.parse(amContents.toString('utf8')).messages || [];

                // Drop expired one-time scheduled messages (sendAt already passed)
                const expiredOneTime = autoMessagesStore.filter(m => m.trigger === 'scheduled_once' && new Date(m.sendAt).getTime() <= Date.now());
                if (expiredOneTime.length > 0) {
                    console.log(`🗑️ Dropping ${expiredOneTime.length} expired scheduled_once message(s)`);
                    autoMessagesStore = autoMessagesStore.filter(m => !(m.trigger === 'scheduled_once' && new Date(m.sendAt).getTime() <= Date.now()));
                    await saveAutoMessagesToGCS();
                }

                for (const m of autoMessagesStore) {
                    if (m.trigger === 'scheduled') {
                        const iv = setInterval(async () => {
                            try {
                                const ch = await client.channels.fetch(m.channel).catch(() => null)
                                    || client.channels.cache.find(c => c.name === m.channel);
                                if (ch?.isTextBased()) await ch.send(m.content);
                            } catch(e) { console.log('Auto message error:', e.message); }
                        }, m.interval || 3600000);
                        autoMessageIntervals.push(iv);
                    } else if (m.trigger === 'scheduled_once' && m.sendAt) {
                        // Restore one-time scheduled timer
                        const delay = new Date(m.sendAt).getTime() - Date.now();
                        if (delay > 0) {
                            console.log(`📅 Restored scheduled_once message for ${m.sendAt} (${Math.round(delay/60000)}min from now) → ${m.channel}`);
                            const to = setTimeout(async () => {
                                try {
                                    const ch = await client.channels.fetch(m.channel).catch(() => null)
                                        || client.channels.cache.find(c => c.name === m.channel);
                                    if (ch?.isTextBased()) {
                                        await ch.send(m.content);
                                        console.log(`✅ Sent scheduled message to ${m.channel}`);
                                    }
                                    const idx = autoMessagesStore.findIndex(x => x.sendAt === m.sendAt && x.channel === m.channel && x.content === m.content);
                                    if (idx >= 0) {
                                        autoMessagesStore.splice(idx, 1);
                                        await saveAutoMessagesToGCS();
                                    }
                                } catch(e) { console.error('Scheduled-once send error:', e.message); }
                            }, delay);
                            autoMessageIntervals.push(to);
                        }
                    }
                }
            }
        } catch(e) { console.log('⚠️ Auto messages load error:', e.message); }

        // Load training history
        try {
            const [thExists] = await bucket.file('training_history.json').exists();
            if (thExists) {
                const [thContents] = await bucket.file('training_history.json').download();
                trainingHistory = JSON.parse(thContents.toString('utf8')).items || [];
            }
        } catch(e) { console.log('⚠️ Training history load error:', e.message); }

        console.log(`✅ Dashboard stores loaded: ${reactionRolesStore.length} reaction roles, ${autoMessagesStore.length} auto msgs, ${trainingHistory.length} training items`);
    } catch(e) { console.log('⚠️ Dashboard stores load error:', e.message); }
}

