// In-memory FAQ state — loaded from GCS on startup
let faqEmbeds = JSON.parse(JSON.stringify(DEFAULT_FAQ_EMBEDS));

// Maps FAQ entry id → Discord message ID in the FAQ channel
// Persisted to GCS alongside faqEmbeds so edits update existing messages
let faqMessageIds = {};

// ============================================================
// FAQ GCS PERSISTENCE
// ============================================================

/**
 * Load FAQ embeds from Google Cloud Storage.
 * Falls back to DEFAULT_FAQ_EMBEDS if no file exists yet.
 */
async function loadFAQFromGCS() {
    try {
        const bucket = storage.bucket(BUCKET_NAME);
        const file = bucket.file(FAQ_FILE_NAME);

        const [exists] = await file.exists();
        if (!exists) {
            console.log("📝 No FAQ file found in GCS. Using defaults and saving...");
            faqEmbeds = JSON.parse(JSON.stringify(DEFAULT_FAQ_EMBEDS));
            faqMessageIds = {};
            await saveFAQToGCS();
            return;
        }

        const [contents] = await file.download();
        let parsed;
        try {
            parsed = JSON.parse(contents.toString('utf8'));
        } catch (jsonErr) {
            console.error("⚠️ FAQ GCS file is corrupt JSON — resetting to defaults:", jsonErr.message);
            faqEmbeds = JSON.parse(JSON.stringify(DEFAULT_FAQ_EMBEDS));
            faqMessageIds = {};
            await saveFAQToGCS();
            return;
        }

        // Validate structure
        const rawEmbeds = parsed.embeds;
        if (!Array.isArray(rawEmbeds) || rawEmbeds.length === 0) {
            console.error("⚠️ FAQ GCS embeds missing or empty — resetting to defaults.");
            faqEmbeds = JSON.parse(JSON.stringify(DEFAULT_FAQ_EMBEDS));
            faqMessageIds = {};
            await saveFAQToGCS();
            return;
        }

        // Validate each embed — must have id, title, and description as strings
        const valid = rawEmbeds.every(e =>
            e && typeof e.id === 'string' && e.id.length > 0 &&
            typeof e.title === 'string' && e.title.length > 0 &&
            (e.description === undefined || typeof e.description === 'string')
        );

        if (!valid) {
            console.error("⚠️ FAQ GCS has malformed embeds — resetting to defaults.");
            faqEmbeds = JSON.parse(JSON.stringify(DEFAULT_FAQ_EMBEDS));
            faqMessageIds = {};
            await saveFAQToGCS();
            return;
        }

        faqEmbeds = rawEmbeds;
        faqMessageIds = (parsed.messageIds && typeof parsed.messageIds === 'object') ? parsed.messageIds : {};

        console.log(`✅ Loaded FAQ from GCS. ${faqEmbeds.length} sections, ${Object.keys(faqMessageIds).length} tracked messages.`);
    } catch (e) {
        console.error("⚠️ Error loading FAQ from GCS:", e.message);
        faqEmbeds = JSON.parse(JSON.stringify(DEFAULT_FAQ_EMBEDS));
        faqMessageIds = {};
    }
}

async function saveFAQToGCS() {
    try {
        // Validate before saving — never write a corrupt file
        if (!Array.isArray(faqEmbeds) || faqEmbeds.length === 0) {
            console.error("⚠️ Refusing to save FAQ — faqEmbeds is empty or not an array.");
            return;
        }
        const allValid = faqEmbeds.every(e =>
            e && typeof e.id === 'string' && e.id.length > 0 &&
            typeof e.title === 'string' && e.title.length > 0
        );
        if (!allValid) {
            console.error("⚠️ Refusing to save FAQ — one or more entries are malformed.");
            return;
        }

        const bucket = storage.bucket(BUCKET_NAME);
        const file = bucket.file(FAQ_FILE_NAME);
        
        const data = {
            embeds: faqEmbeds,
            messageIds: faqMessageIds,
            lastUpdated: new Date().toISOString(),
            entryCount: faqEmbeds.length
        };
        
        await file.save(JSON.stringify(data, null, 2), {
            contentType: 'application/json',
            metadata: { cacheControl: 'no-cache' }
        });
        
        console.log(`💾 Saved FAQ to GCS. ${faqEmbeds.length} sections.`);
    } catch (e) {
        console.error("⚠️ Error saving FAQ to GCS:", e.message);
    }
}

