// ✨ CUSTOM KNOWLEDGE — GCS PERSISTENCE + OWNER TEACHING
// Owners can teach Shubba new facts at any time via @mention.
// All entries are stored in GCS and injected into every prompt.
// ============================================================

/**
 * Load custom knowledge entries from Google Cloud Storage.
 */
async function loadCustomKnowledgeFromGCS() {
    try {
        const bucket = storage.bucket(BUCKET_NAME);
        const file = bucket.file(CUSTOM_KNOWLEDGE_FILE_NAME);

        const [exists] = await file.exists();
        if (!exists) {
            console.log("📝 No custom knowledge file found in GCS. Starting fresh.");
            customKnowledgeEntries = [];
            return;
        }

        const [contents] = await file.download();
        const parsed = JSON.parse(contents.toString('utf8'));
        customKnowledgeEntries = parsed.entries || [];

        console.log(`✅ Loaded ${customKnowledgeEntries.length} custom knowledge entry/entries from GCS.`);
    } catch (e) {
        console.error("⚠️ Error loading custom knowledge from GCS:", e.message);
        customKnowledgeEntries = [];
    }
}

/**
 * Save custom knowledge entries to Google Cloud Storage.
 */
async function saveCustomKnowledgeToGCS() {
    try {
        const bucket = storage.bucket(BUCKET_NAME);
        const file = bucket.file(CUSTOM_KNOWLEDGE_FILE_NAME);

        const data = {
            entries: customKnowledgeEntries,
            lastUpdated: new Date().toISOString()
        };

        await file.save(JSON.stringify(data, null, 2), {
            contentType: 'application/json',
            metadata: { cacheControl: 'no-cache' }
        });

        console.log(`💾 Saved ${customKnowledgeEntries.length} custom knowledge entry/entries to GCS.`);
    } catch (e) {
        console.error("⚠️ Error saving custom knowledge to GCS:", e.message);
    }
}

/**
 * Build the custom knowledge section for injection into prompts.
 * Returns an empty string if no entries exist.
 */
function buildCustomKnowledge() {
    if (customKnowledgeEntries.length === 0) return "";

    let section = `\n--- OWNER-TAUGHT CUSTOM KNOWLEDGE ---\n`;
    section += `(${customKnowledgeEntries.length} entries added by the development team)\n\n`;

    customKnowledgeEntries.forEach((entry, index) => {
        section += `[Entry ${index + 1}] ${entry.text}\n`;
        section += `  (added by ${entry.addedBy} on ${new Date(entry.addedAt).toLocaleDateString()})\n\n`;
    });

    return section;
}

/**
 * Handle "@Shubba learn: [text]" from an owner.
 * Stores the text as a custom knowledge entry in GCS.
 *
 * Supported formats:
 *   @Shubba learn: [text]
 *   @Shubba remember: [text]
 *   @Shubba note: [text]
 *   @Shubba forget [number] — removes entry at that index
 *   @Shubba what do you know — lists all custom entries
 */
async function handleLearnCommand(message) {
    const contentLower = message.content.toLowerCase();
    const contentRaw = message.content;

    // ── LIST all custom knowledge entries ───────────────────────────────────
    const listPatterns = [
        /what\s+do\s+you\s+know/i,
        /list\s+(your\s+)?(knowledge|what\s+you.*know|entries)/i,
        /show\s+(me\s+)?(your\s+)?(knowledge|what\s+you.*know|entries)/i
    ];
    if (listPatterns.some(p => p.test(contentRaw))) {
        if (customKnowledgeEntries.length === 0) {
            return message.reply("🧠 I don't have any custom knowledge entries yet. Teach me something with `@Shubba learn: [text]`!");
        }

        const lines = [`🧠 **Custom Knowledge Entries (${customKnowledgeEntries.length}):**\n`];
        customKnowledgeEntries.forEach((entry, i) => {
            lines.push(`**[${i + 1}]** ${entry.text}`);
            lines.push(`  *added by ${entry.addedBy} on ${new Date(entry.addedAt).toLocaleDateString()}*\n`);
        });
        lines.push(`\nTo remove an entry: \`@Shubba forget [number]\``);

        const chunks = splitMessage(lines.join('\n'));
        await message.reply(chunks[0]);
        for (let i = 1; i < chunks.length; i++) await message.channel.send(chunks[i]);
        return;
    }

    // ── FORGET / REMOVE a specific entry by number ──────────────────────────
    const forgetMatch = contentRaw.match(/forget\s+(\d+)/i);
    if (forgetMatch) {
        const index = parseInt(forgetMatch[1]) - 1; // Convert 1-based to 0-based
        if (index < 0 || index >= customKnowledgeEntries.length) {
            return message.reply(`❌ No entry #${forgetMatch[1]}. I currently have ${customKnowledgeEntries.length} entry/entries. Use \`@Shubba what do you know\` to list them.`);
        }
        const removed = customKnowledgeEntries.splice(index, 1)[0];
        await saveCustomKnowledgeToGCS();
        // Invalidate knowledge cache so next response uses fresh data
        DYNAMIC_KNOWLEDGE_CACHE = {};
        return message.reply(`✅ Forgot entry #${index + 1}: *"${removed.text.substring(0, 100)}${removed.text.length > 100 ? '...' : ''}"*`);
    }

    // ── LEARN / REMEMBER / NOTE a new piece of knowledge ────────────────────
    const learnPatterns = [
        /^.*(?:learn|remember|note|know that|keep in mind)[:\s]+(.+)/is
    ];

    let newKnowledge = null;
    for (const pattern of learnPatterns) {
        const match = contentRaw.replace(/<@!?\d+>/g, '').trim().match(pattern);
        if (match && match[1].trim().length > 3) {
            newKnowledge = match[1].trim();
            break;
        }
    }

    if (!newKnowledge) {
        return message.reply([
            `🤔 I'm not sure what you want me to learn. Use one of these formats:`,
            ``,
            `• \`@Shubba learn: [text]\``,
            `• \`@Shubba remember: [text]\``,
            `• \`@Shubba note: [text]\``,
            `• \`@Shubba what do you know\` — list all entries`,
            `• \`@Shubba forget [number]\` — remove an entry`
        ].join('\n'));
    }

    // Cap entry length to avoid bloating the prompt
    if (newKnowledge.length > 1000) {
        return message.reply(`❌ That's too long (${newKnowledge.length} chars). Please keep knowledge entries under 1000 characters.`);
    }

    // Add the entry
    customKnowledgeEntries.push({
        text: newKnowledge,
        addedBy: message.author.username,
        addedAt: new Date().toISOString()
    });

    await saveCustomKnowledgeToGCS();

    // Invalidate knowledge cache so the next response already knows this
    DYNAMIC_KNOWLEDGE_CACHE = {};

    const entryNumber = customKnowledgeEntries.length;
    return message.reply(`🧠 **Got it! Learned and saved as entry #${entryNumber}:**\n> ${newKnowledge.substring(0, 300)}${newKnowledge.length > 300 ? '...' : ''}\n\n*This is now part of my permanent knowledge base. To remove it later: \`@Shubba forget ${entryNumber}\`*`);
}

/**
 * Detect whether a message is a "learn/teach" command.
 * Returns true if the message contains a teaching trigger word.
 */
function isLearnCommand(contentLower, contentRaw) {
    // Explicit teach triggers
    const teachTriggers = [
        /\blearn[:\s]/i,
        /\bremember[:\s]/i,
        /\bnote[:\s]/i,
        /\bknow that\b/i,
        /\bkeep in mind\b/i,
        /\bforget\s+\d+/i,
        /\bwhat\s+do\s+you\s+know\b/i,
        /\blist\s+(your\s+)?knowledge\b/i,
        /\bshow\s+(me\s+)?(your\s+)?knowledge\b/i
    ];
    return teachTriggers.some(p => p.test(contentRaw));
}

// ============================================================
// ✨ NEW: AI-POWERED FAQ EDITING
// Owner says "@Shubba [any instruction about the FAQ]"
// Gemini interprets the instruction and returns updated embed JSON.
// ============================================================

/**
 * Detect if a message is a FAQ edit/modify request.
 * Triggers on FAQ-related words combined with action words.
 */
function isFAQRequest(contentLower) {
    const faqWords = ['faq', 'embed', 'announcement', 'frequently asked'];
    const actionWords = ['edit', 'update', 'change', 'add', 'remove', 'delete', 'post', 'repost', 'modify', 'fix', 'new', 'create'];
    
    const hasFAQWord = faqWords.some(w => contentLower.includes(w));
    const hasActionWord = actionWords.some(w => contentLower.includes(w));
    
    return hasFAQWord && hasActionWord;
}

/**
 * Whether the owner just wants to POST the current FAQ without editing it.
 */
function isJustPostFAQ(contentLower) {
    return (
        contentLower.includes('post') || 
        contentLower.includes('repost') || 
        contentLower.includes('send')
    ) && (
        contentLower.includes('faq') || 
        contentLower.includes('embed')
    );
}

/**
 * Handle a FAQ edit request from an owner.
 * Uses Gemini to understand the natural language instruction and modify faqEmbeds accordingly.
 * After editing, shows a preview and asks the owner if they want to post it.
 */
async function handleFAQEdit(message) {
    await message.channel.sendTyping();

    const instruction = message.content;

    // Build a compact summary of current embeds for the prompt
    const currentFAQSummary = faqEmbeds.map((e, i) =>
        `[${i}] id: "${e.id}"\n    title: "${e.title}"\n    description: "${e.description.substring(0, 300)}${e.description.length > 300 ? '...' : ''}"`
    ).join('\n\n');

    const editPrompt = `You are managing the FAQ embeds for a Discord bot called Shubba for the Punchy! Minecraft mod server.

The owner has given you this instruction:
"${instruction}"

Here are the current FAQ embeds (as a numbered list with id, title, description):
${currentFAQSummary}

TASK: Apply the owner's instruction to the embed array and return the COMPLETE updated array as valid JSON.

RULES:
1. Return ONLY a valid JSON array — no explanation, no markdown, no code fences, just the raw JSON array
2. Each embed must have: "id" (short snake_case slug), "title" (string), "description" (string)
3. Discord markdown is allowed in descriptions: **bold**, *italic*, \`code\`, [links](url), <#channelId> mentions
4. Preserve all embeds that are not being changed
5. When adding a new embed, give it a unique id slug and insert it in a logical position
6. When removing an embed, omit it from the array
7. When editing an embed, update only the fields mentioned
8. If the instruction is ambiguous, make a sensible interpretation
9. Keep descriptions accurate and professional — this is a public FAQ

Return ONLY the JSON array, nothing else. Example format:
[{"id":"header","title":"📋 Title","description":"Description text"},{"id":"config","title":"⚙️ Config","description":"Press F8..."}]`;

    const statusMsg = await message.reply("🤔 **Reading your instruction and updating the FAQ...**");

    try {
        const rawResponse = await callGemini(editPrompt, false);

        // Strip any accidental markdown fences if Gemini added them
        const cleaned = rawResponse
            .replace(/^```json?\s*/i, '')
            .replace(/```\s*$/, '')
            .trim();

        let updatedEmbeds;
        try {
            updatedEmbeds = JSON.parse(cleaned);
        } catch (parseErr) {
            console.error("⚠️ FAQ edit: JSON parse failed:", parseErr.message, "\nRaw:", rawResponse.substring(0, 500));
            return statusMsg.edit("❌ **I couldn't parse the updated FAQ.** Please try rephrasing your instruction.");
        }

        // Validate the structure
        if (!Array.isArray(updatedEmbeds) || updatedEmbeds.length === 0) {
            return statusMsg.edit("❌ **The result wasn't a valid embed array.** Please try again.");
        }

        for (const embed of updatedEmbeds) {
            if (!embed.id || !embed.title || typeof embed.description === 'undefined') {
                return statusMsg.edit("❌ **One or more embeds are missing required fields (id, title, description).** Please try again.");
            }
        }

        // Apply the changes
        const oldCount = faqEmbeds.length;
        faqEmbeds = updatedEmbeds;
        await saveFAQToGCS();

        // Build a readable diff summary
        const newCount = faqEmbeds.length;
        const added = newCount - oldCount;
        const diffNote = added > 0 ? ` (+${added} embed${added > 1 ? 's' : ''})` :
                         added < 0 ? ` (${added} embed${added < -1 ? 's' : ''})` : '';

        // Show a preview of all current embed titles
        const embedList = faqEmbeds.map((e, i) => `  ${i + 1}. **${e.title}**`).join('\n');

        const confirmMsg = [
            `✅ **FAQ updated!**${diffNote} Now showing **${newCount} embed${newCount !== 1 ? 's' : ''}**:\n`,
            embedList,
            `\n**Post the updated FAQ to <#${FAQ_CHANNEL_ID}> now?** Reply with \`yes\` or \`@Shubba post the faq\`.`
        ].join('\n');

        return statusMsg.edit(confirmMsg);

    } catch (e) {
        console.error("❌ FAQ edit error:", e);
        return statusMsg.edit("❌ **Something went wrong while processing your instruction.** Check the logs.");
    }
}

