/**
 * Load active ticket channels from Google Cloud Storage.
 * Called on bot startup so tickets survive restarts.
 */
async function loadTicketsFromGCS() {
    try {
        const bucket = storage.bucket(BUCKET_NAME);
        const file = bucket.file(TICKET_FILE_NAME);

        const [exists] = await file.exists();
        if (!exists) {
            console.log("📝 No tickets file found in GCS. Starting fresh.");
            return;
        }

        const [contents] = await file.download();
        const parsed = JSON.parse(contents.toString('utf8'));
        const tickets = parsed.tickets || [];

        tickets.forEach(ticket => {
            ticketChannels.set(ticket.channelId, {
                threadId: ticket.threadId,
                threadName: ticket.threadName,
                opId: ticket.opId,
                guildId: ticket.guildId,
                createdAt: ticket.createdAt,
                addedUsers: ticket.addedUsers || []
            });
        });

        console.log(`✅ Loaded ${ticketChannels.size} active ticket(s) from GCS.`);
    } catch (e) {
        console.error("⚠️ Error loading tickets from GCS:", e.message);
    }
}

/**
 * Save current ticket channels map to Google Cloud Storage.
 */
async function saveTicketsToGCS() {
    try {
        const bucket = storage.bucket(BUCKET_NAME);
        const file = bucket.file(TICKET_FILE_NAME);

        const tickets = [];
        ticketChannels.forEach((info, channelId) => {
            tickets.push({ channelId, ...info });
        });

        const data = {
            tickets,
            lastUpdated: new Date().toISOString()
        };

        await file.save(JSON.stringify(data, null, 2), {
            contentType: 'application/json',
            metadata: { cacheControl: 'no-cache' }
        });

        console.log(`💾 Saved ${tickets.length} ticket(s) to GCS.`);
    } catch (e) {
        console.error("⚠️ Error saving tickets to GCS:", e.message);
    }
}

