/**
 * Sanitize a string for use as a Discord channel name.
 * Discord channel names must be lowercase, no spaces (use hyphens),
 * and only alphanumeric + hyphens + underscores.
 */
function sanitizeChannelName(name) {
    return name
        .toLowerCase()
        .replace(/\s+/g, '-')           // spaces → hyphens
        .replace(/[^a-z0-9\-_]/g, '')   // strip invalid chars
        .replace(/-+/g, '-')            // collapse multiple hyphens
        .slice(0, 80);                  // Discord channel name max 100 chars; keep it short
}

/**
 * Generate an executive summary of a support thread using Gemini.
 * Used when creating a ticket to brief the owners at a glance.
 */
async function generateTicketSummary(thread, messages) {
    try {
        const conversation = messages
            .slice(0, 40) // Limit to 40 messages to avoid prompt overflow
            .map(m => `${m.author.username}: ${m.content.substring(0, 400)}`)
            .join('\n');

        const prompt = `You are Shubba, summarizing a Punchy! Minecraft mod support thread for the development team.

THREAD TITLE: "${thread.name}"

CONVERSATION:
${conversation}

Write a concise EXECUTIVE SUMMARY for the developers. Include:
1. **Issue:** What the user is experiencing (1–2 sentences, specific)
2. **Details:** Relevant technical info (Minecraft version, mod loader, Punchy version, other mods if mentioned)
3. **What's been tried:** Any solutions already attempted
4. **Priority assessment:** Why this was escalated to a private ticket

Keep it under 300 words. Be direct and technical — this is for the development team, not the user.`;

        const summary = await callGemini(prompt, false);
        return summary;
    } catch (e) {
        console.error("⚠️ Failed to generate ticket summary:", e.message);
        return "*(Summary generation failed — please review the linked thread manually.)*";
    }
}

/**
 * Handle the /isolate slash command.
 * - Must be used inside a support forum thread
 * - Creates a private ticket channel at the top of the server
 * - Tags the OP and both owners
 * - Sends an executive summary
 * - Saves the ticket to GCS
 */
async function handleIsolateCommand(interaction) {
    await safeDefer(interaction, { flags: [MessageFlags.Ephemeral] });

    const thread = interaction.channel;
    const guild = interaction.guild;

    // Validate: must be used in a support forum thread
    if (!thread.isThread || !thread.isThread() || thread.parentId !== SUPPORT_FORUM_ID) {
        return safeEditReply(interaction, "❌ `/isolate` can only be used inside a **support forum thread**.");
    }

    // Check if this thread already has an open ticket
    for (const [channelId, info] of ticketChannels.entries()) {
        if (info.threadId === thread.id) {
            const existingChannel = guild.channels.cache.get(channelId);
            if (existingChannel) {
                return safeEditReply(interaction, `❌ This thread already has an active ticket: <#${channelId}>`);
            } else {
                // Channel no longer exists — clean up stale entry
                ticketChannels.delete(channelId);
                await saveTicketsToGCS();
            }
        }
    }

    // Fetch the thread starter to get the OP's user ID
    let opId = null;
    let opUser = null;
    try {
        const starterMessage = await thread.fetchStarterMessage();
        if (starterMessage) {
            opId = starterMessage.author.id;
            opUser = starterMessage.author;
        }
    } catch (e) {
        console.error("⚠️ Could not fetch starter message for isolate:", e.message);
    }

    // Fetch recent messages for the summary
    let messagesForSummary = [];
    try {
        const fetched = await thread.messages.fetch({ limit: 50 });
        messagesForSummary = Array.from(fetched.values()).reverse();
    } catch (e) {
        console.error("⚠️ Could not fetch messages for summary:", e.message);
    }

    // Generate the channel name: ticket-<sanitized-thread-name>
    const safeThreadName = sanitizeChannelName(thread.name);
    const channelName = `🎫-${safeThreadName}`.slice(0, 100);

    // Build permission overwrites:
    // - @everyone: deny all (private channel)
    // - bot itself: allow view + send + manage channel
    // - each owner: allow view + send
    // - OP (if found): allow view + send
    const permissionOverwrites = [
        {
            id: guild.roles.everyone.id,
            deny: [PermissionFlagsBits.ViewChannel]
        },
        {
            id: client.user.id,
            allow: [
                PermissionFlagsBits.ViewChannel,
                PermissionFlagsBits.SendMessages,
                PermissionFlagsBits.ReadMessageHistory,
                PermissionFlagsBits.ManageChannels,
                PermissionFlagsBits.ManageMessages
            ]
        }
    ];

    // Add owners
    for (const devId of DEV_IDS) {
        permissionOverwrites.push({
            id: devId,
            allow: [
                PermissionFlagsBits.ViewChannel,
                PermissionFlagsBits.SendMessages,
                PermissionFlagsBits.ReadMessageHistory
            ]
        });
    }

    // Add OP
    if (opId && !DEV_IDS.includes(opId)) {
        permissionOverwrites.push({
            id: opId,
            allow: [
                PermissionFlagsBits.ViewChannel,
                PermissionFlagsBits.SendMessages,
                PermissionFlagsBits.ReadMessageHistory
            ]
        });
    }

    // Create the ticket channel
    let ticketChannel;
    try {
        ticketChannel = await guild.channels.create({
            name: channelName,
            type: ChannelType.GuildText,
            permissionOverwrites,
            reason: `Ticket created for support thread: ${thread.name}`
        });

        // Move to the very top of the server (position 0)
        await ticketChannel.setPosition(0);

        console.log(`🎫 Created ticket channel: #${channelName} (${ticketChannel.id})`);
    } catch (e) {
        console.error("❌ Failed to create ticket channel:", e.message);
        return safeEditReply(interaction, `❌ Failed to create the ticket channel. Make sure Shubba has **Manage Channels** permission.\n\`${e.message}\``);
    }

    // Save to in-memory Map and GCS
    const ticketInfo = {
        threadId: thread.id,
        threadName: thread.name,
        opId: opId || null,
        guildId: guild.id,
        createdAt: new Date().toISOString(),
        addedUsers: []
    };
    ticketChannels.set(ticketChannel.id, ticketInfo);
    await saveTicketsToGCS();

    // Generate executive summary
    const summary = await generateTicketSummary(thread, messagesForSummary);

    // Build the opening message pings
    const ownerPings = DEV_IDS.map(id => `<@${id}>`).join(' ');
    const opPing = opId ? `<@${opId}>` : '*(OP not found)*';
    const threadLink = `https://discord.com/channels/${guild.id}/${thread.id}`;

    const openingMessage = [
        `🎫 **PRIVATE TICKET OPENED**`,
        ``,
        `**Linked Thread:** [${thread.name}](${threadLink})`,
        `**Opened by:** <@${interaction.user.id}>`,
        `**OP:** ${opPing}`,
        `**Owners:** ${ownerPings}`,
        ``,
        `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
        `📋 **EXECUTIVE SUMMARY**`,
        `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
        ``,
        summary,
        ``,
        `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
        ``,
        `💡 **Tips:**`,
        `• Use \`/add @user\` to add more people to this ticket`,
        `• Use \`/solve\` in this channel to close the ticket and resolve the original thread`,
        `• Tag <@${client.user.id}> to ask Shubba anything`,
    ].join('\n');

    // Send chunks if the summary is very long
    const chunks = splitMessage(openingMessage);
    for (const chunk of chunks) {
        await ticketChannel.send(chunk);
    }

    // Also tag the thread with a note pointing to the ticket
    try {
        await thread.send(`🎫 **This thread has been escalated to a private ticket.** The development team will follow up shortly.`);
    } catch (e) {
        console.error("⚠️ Could not send note in original thread:", e.message);
    }

    await safeEditReply(interaction, `✅ Ticket created: <#${ticketChannel.id}>`);
    console.log(`✅ Ticket opened for thread "${thread.name}" → channel #${channelName}`);
}

/**
 * Handle the /add slash command inside a ticket channel.
 * Adds up to 5 users to the ticket channel's permission overwrites.
 */
async function handleAddToTicketCommand(interaction) {
    await safeDefer(interaction, { flags: [MessageFlags.Ephemeral] });

    const ticketInfo = ticketChannels.get(interaction.channelId);
    if (!ticketInfo) {
        return safeEditReply(interaction, "❌ This command can only be used inside a **ticket channel**.");
    }

    // Gather all user options (user1 through user5)
    const usersToAdd = [];
    for (let i = 1; i <= 5; i++) {
        const user = interaction.options.getUser(`user${i}`);
        if (user && !usersToAdd.some(u => u.id === user.id)) {
            usersToAdd.push(user);
        }
    }

    if (usersToAdd.length === 0) {
        return safeEditReply(interaction, "❌ Please provide at least one user to add.");
    }

    const addedNames = [];
    const alreadyAdded = [];
    const failed = [];

    for (const user of usersToAdd) {
        // Skip if already has access
        const existing = interaction.channel.permissionOverwrites.cache.get(user.id);
        if (existing && existing.allow.has(PermissionFlagsBits.ViewChannel)) {
            alreadyAdded.push(user.username);
            continue;
        }

        try {
            await interaction.channel.permissionOverwrites.edit(user.id, {
                ViewChannel: true,
                SendMessages: true,
                ReadMessageHistory: true
            });

            // Track in ticketInfo
            if (!ticketInfo.addedUsers.includes(user.id)) {
                ticketInfo.addedUsers.push(user.id);
            }

            addedNames.push(`<@${user.id}>`);
        } catch (e) {
            console.error(`❌ Failed to add ${user.username} to ticket:`, e.message);
            failed.push(user.username);
        }
    }

    // Save updated ticket info
    ticketChannels.set(interaction.channelId, ticketInfo);
    await saveTicketsToGCS();

    // Build response
    const lines = [];
    if (addedNames.length > 0) {
        lines.push(`✅ **Added to ticket:** ${addedNames.join(', ')}`);
        // Notify in the channel
        await interaction.channel.send(`👋 ${addedNames.join(', ')} has been added to this ticket.`);
    }
    if (alreadyAdded.length > 0) {
        lines.push(`ℹ️ **Already have access:** ${alreadyAdded.join(', ')}`);
    }
    if (failed.length > 0) {
        lines.push(`❌ **Failed to add:** ${failed.join(', ')}`);
    }

    return safeEditReply(interaction, lines.join('\n') || "Nothing changed.");
}

/**
 * Handle /solve inside a ticket channel.
 * - Stores the solution from the linked thread
 * - Sends a closing message in the ticket
 * - Closes (archives + locks) the linked support thread
 * - Deletes the ticket channel
 * - Removes the ticket from GCS
 */
async function solveTicket(interaction) {
    await safeDefer(interaction, {});

    const ticketInfo = ticketChannels.get(interaction.channelId);
    if (!ticketInfo) {
        return safeEditReply(interaction, "❌ This command can only be used inside a **ticket channel** (or a support thread).");
    }

    const guild = interaction.guild;
    const ticketChannel = interaction.channel;

    // Fetch the linked support thread
    let linkedThread = null;
    try {
        linkedThread = await client.channels.fetch(ticketInfo.threadId);
    } catch (e) {
        console.error("⚠️ Could not fetch linked thread:", e.message);
    }

    // Collect conversation from ticket for learning
    let ticketConversation = "";
    try {
        const ticketMessages = await ticketChannel.messages.fetch({ limit: 50 });
        const ticketMsgArray = Array.from(ticketMessages.values()).reverse();
        ticketConversation = ticketMsgArray
            .map(m => `${m.author.username}: ${m.content.substring(0, 400)}`)
            .join('\n');
    } catch (e) {
        console.error("⚠️ Could not fetch ticket messages for learning:", e.message);
    }

    // Store solution from the linked thread (for the solutions database)
    if (linkedThread) {
        await storeSolution(linkedThread);
    }

    // Also store ticket conversation as a supplementary solution entry
    if (ticketConversation) {
        try {
            if (!SOLUTIONS_BY_VERSION[CURRENT_VERSION_SET]) {
                SOLUTIONS_BY_VERSION[CURRENT_VERSION_SET] = [];
            }
            const ticketSolution = {
                threadName: `[TICKET] ${ticketInfo.threadName}`,
                issue: `Escalated ticket — ${ticketInfo.threadName}`,
                tags: ['Ticket'],
                conversation: ticketConversation,
                solvedDate: new Date().toISOString(),
                threadId: ticketInfo.threadId,
                version: CURRENT_VERSION_SET
            };
            SOLUTIONS_BY_VERSION[CURRENT_VERSION_SET].unshift(ticketSolution);
            if (SOLUTIONS_BY_VERSION[CURRENT_VERSION_SET].length > MAX_SOLUTIONS_PER_VERSION) {
                SOLUTIONS_BY_VERSION[CURRENT_VERSION_SET] = SOLUTIONS_BY_VERSION[CURRENT_VERSION_SET].slice(0, MAX_SOLUTIONS_PER_VERSION);
            }
            await saveSolutionsToGCS();
            console.log(`✅ Stored ticket conversation as solution for version ${CURRENT_VERSION_SET}`);
        } catch (e) {
            console.error("⚠️ Failed to store ticket solution:", e.message);
        }
    }

    // Send closing message in the ticket channel before deleting
    const closingMsg = [
        `✅ **Ticket resolved!** Closing in 5 seconds...`,
        ``,
        `The linked support thread will be archived and locked.`,
        `All conversation has been saved to Shubba's knowledge base.`
    ].join('\n');

    try {
        await safeEditReply(interaction, closingMsg);
    } catch (e) {
        await ticketChannel.send(closingMsg).catch(() => {});
    }

    // Notify in the linked thread that the ticket is resolved
    if (linkedThread) {
        try {
            await linkedThread.send("✅ **Solved!** This thread has been resolved via private ticket. It is now being locked and archived.");
        } catch (e) {
            console.error("⚠️ Could not send closing message in linked thread:", e.message);
        }
    }

    // Wait 5 seconds so users can read the closing message
    await new Promise(resolve => setTimeout(resolve, 5000));

    // Archive and lock the linked support thread
    if (linkedThread) {
        try {
            const cleanName = linkedThread.name.replace('(HUMAN HELP) ', '').replace('[SOLVED] ', '');
            await linkedThread.setName(await safeThreadName('[SOLVED] ', cleanName));
            await linkedThread.setLocked(true, "Resolved via ticket.");
            await linkedThread.setArchived(true);
            delete threadMemory[linkedThread.id];
            console.log(`✅ Linked thread archived: ${linkedThread.name}`);
        } catch (e) {
            console.error("⚠️ Could not archive linked thread:", e.message);
        }
    }

    // Remove from tracking and GCS
    ticketChannels.delete(ticketChannel.id);
    await saveTicketsToGCS();

    // Delete the ticket channel
    try {
        await ticketChannel.delete("Ticket resolved via /solve");
        console.log(`🗑️ Ticket channel deleted: ${ticketChannel.name}`);
    } catch (e) {
        console.error("❌ Failed to delete ticket channel:", e.message);
    }
}

