// ============================================================
// ✨ MODERATION SYSTEM
// Warn → role. 2nd warn → role + 1-week timeout. 3rd → ban.
// All persisted in GCS. Warn roles must exist in the server.
// ============================================================

const MODERATION_FILE_NAME = 'moderation_database.json';
const WARN1_ROLE_NAME = 'Warn 1';
const WARN2_ROLE_NAME = 'Warn 2';

// In-memory warnings store: userId → { warnings: [{reason, date, by}], guildId }
let moderationData = {};

async function loadModerationFromGCS() {
    try {
        const file = storage.bucket(BUCKET_NAME).file(MODERATION_FILE_NAME);
        const [exists] = await file.exists();
        if (!exists) { moderationData = {}; return; }
        const [contents] = await file.download();
        moderationData = JSON.parse(contents.toString('utf8'));
        console.log(`✅ Loaded moderation data (${Object.keys(moderationData).length} users tracked).`);
    } catch (e) { console.error('⚠️ Failed to load moderation data:', e.message); moderationData = {}; }
}

async function saveModerationToGCS() {
    try {
        const file = storage.bucket(BUCKET_NAME).file(MODERATION_FILE_NAME);
        await file.save(JSON.stringify(moderationData, null, 2), { contentType: 'application/json', metadata: { cacheControl: 'no-cache' } });
    } catch (e) { console.error('⚠️ Failed to save moderation data:', e.message); }
}

function parseDuration(str) {
    const match = str.match(/^(\d+)(m|h|d|w)$/i);
    if (!match) return null;
    const [, num, unit] = match;
    const map = { m: 60000, h: 3600000, d: 86400000, w: 604800000 };
    return parseInt(num) * map[unit.toLowerCase()];
}

async function getOrCreateRole(guild, name, color = null) {
    let role = guild.roles.cache.find(r => r.name === name);
    if (!role) {
        role = await guild.roles.create({
            name,
            color: color || 0x99AAB5,
            permissions: [],
            reason: 'Shubba moderation system — auto-created'
        });
        console.log(`✅ Created role: ${name}`);
    }
    return role;
}

/**
 * Publish a moderation action so EVERYONE can see it.
 *
 * These used to be plain-text interaction replies. An interaction reply is tied
 * to the invocation, easy to miss, and reads as private even when it is not — so
 * mod actions effectively had no public record. This posts a real channel
 * message (the record) and leaves the moderator a short confirmation.
 */
async function publishModAction(interaction, { action, target, reason, extra = [] }) {
    const embed = modActionEmbed({
        action,
        target: { id: target.id, tag: target.tag || target.username },
        moderator: { id: interaction.user.id, tag: interaction.user.username },
        reason,
        extra,
    });
    // The channel message is the record — visible, persistent, linkable.
    await interaction.channel?.send({ embeds: [embed] }).catch(e =>
        console.warn('[mod] could not post public record:', e.message));
    // And close out the slash command itself.
    return safeEditReply(interaction, { embeds: [embed] });
}

async function handleWarn(interaction) {
    await safeDefer(interaction, {});
    const target = interaction.options.getMember('user');
    const reason = interaction.options.getString('reason') || 'No reason provided';
    const guild = interaction.guild;

    if (!target) return safeEditReply(interaction, '❌ Could not find that user in this server.');
    if (DEV_IDS.includes(target.user.id)) return safeEditReply(interaction, '❌ Cannot warn owners.');

    const uid = target.user.id;
    if (!moderationData[uid]) moderationData[uid] = { warnings: [], guildId: guild.id };

    moderationData[uid].warnings.push({ reason, date: new Date().toISOString(), by: interaction.user.username });
    const warnCount = moderationData[uid].warnings.length;
    await saveModerationToGCS();

    if (warnCount === 1) {
        // Warn 1: assign Warn 1 role
        const role = await getOrCreateRole(guild, WARN1_ROLE_NAME, 0xFEE75C);
        await target.roles.add(role).catch(() => {});
        await safeEditReply(interaction, [
            `⚠️ **Warning 1/3** issued to ${target.user.username}`,
            `**Reason:** ${reason}`,
            `**Role assigned:** ${WARN1_ROLE_NAME}`,
            `_Next warning will result in a 1-week timeout._`
        ].join('\n'));
    } else if (warnCount === 2) {
        // Warn 2: assign Warn 2 role + 1-week timeout
        const warn1Role = guild.roles.cache.find(r => r.name === WARN1_ROLE_NAME);
        if (warn1Role) await target.roles.remove(warn1Role).catch(() => {});
        const role = await getOrCreateRole(guild, WARN2_ROLE_NAME, 0xED4245);
        await target.roles.add(role).catch(() => {});
        await target.timeout(7 * 24 * 60 * 60 * 1000, `Warn 2 timeout — ${reason}`).catch(() => {});
        await safeEditReply(interaction, [
            `🔇 **Warning 2/3** issued to ${target.user.username}`,
            `**Reason:** ${reason}`,
            `**Role assigned:** ${WARN2_ROLE_NAME}`,
            `**Action:** 1-week timeout applied.`,
            `_One more strike results in a permanent ban._`
        ].join('\n'));
    } else {
        // Warn 3: ban
        await guild.members.ban(target.user.id, { reason: `Strike 3 — ${reason}` }).catch(() => {});
        delete moderationData[uid];
        await saveModerationToGCS();
        await safeEditReply(interaction, [
            `🔨 **Strike 3 — ${target.user.username} has been banned.**`,
            `**Reason:** ${reason}`,
            `_3 warnings reached. Permanent ban applied._`
        ].join('\n'));
    }
}

async function handleMute(interaction) {
    await safeDefer(interaction, {});
    const target = interaction.options.getMember('user');
    const durationStr = interaction.options.getString('duration');
    const reason = interaction.options.getString('reason') || 'No reason provided';

    if (!target) return safeEditReply(interaction, '❌ User not found.');
    if (DEV_IDS.includes(target.user.id)) return safeEditReply(interaction, '❌ Cannot mute owners.');

    const ms = parseDuration(durationStr);
    if (!ms) return safeEditReply(interaction, '❌ Invalid duration. Use formats like: `10m`, `2h`, `1d`, `1w`');

    await target.timeout(ms, reason).catch(e => { throw e; });
    await publishModAction(interaction, { action: 'mute', target: target.user, reason, extra: [{ name: 'Duration', value: durationStr, inline: true }] });
}

async function handleUnmute(interaction) {
    await safeDefer(interaction, {});
    const target = interaction.options.getMember('user');
    if (!target) return safeEditReply(interaction, '❌ User not found.');
    await target.timeout(null).catch(() => {});
    await publishModAction(interaction, { action: 'unmute', target: target.user, reason: 'Timeout lifted by a moderator' });
}

async function handleKick(interaction) {
    await safeDefer(interaction, {});
    const target = interaction.options.getMember('user');
    const reason = interaction.options.getString('reason') || 'No reason provided';
    if (!target) return safeEditReply(interaction, '❌ User not found.');
    if (DEV_IDS.includes(target.user.id)) return safeEditReply(interaction, '❌ Cannot kick owners.');
    const name = target.user.username;
    await target.kick(reason).catch(e => { throw e; });
    await publishModAction(interaction, { action: 'kick', target: target.user, reason });
}

async function handleBan(interaction) {
    await safeDefer(interaction, {});
    const target = interaction.options.getUser('user');
    const reason = interaction.options.getString('reason') || 'No reason provided';
    if (!target) return safeEditReply(interaction, '❌ User not found.');
    if (DEV_IDS.includes(target.id)) return safeEditReply(interaction, '❌ Cannot ban owners.');
    await interaction.guild.members.ban(target.id, { reason }).catch(e => { throw e; });
    await publishModAction(interaction, { action: 'ban', target, reason });
}

async function handleUnban(interaction) {
    await safeDefer(interaction, {});
    const userId = interaction.options.getString('userid');
    await interaction.guild.members.unban(userId, 'Unbanned via /unban').catch(e => { throw e; });
    await publishModAction(interaction, { action: 'unban', target: { id: userId, tag: userId }, reason: 'Unbanned via /unban' });
}

async function handleWarnings(interaction) {
    await safeDefer(interaction, { flags: [MessageFlags.Ephemeral] });
    const target = interaction.options.getUser('user');
    const data = moderationData[target.id];
    if (!data || data.warnings.length === 0) {
        return safeEditReply(interaction, `✅ **${target.username}** has no active warnings.`);
    }
    const lines = data.warnings.map((w, i) =>
        `**[${i + 1}]** ${new Date(w.date).toLocaleDateString()} — ${w.reason} _(by ${w.by})_`
    );
    await safeEditReply(interaction, `⚠️ **${target.username}** has **${data.warnings.length}/3** warning(s):\n\n${lines.join('\n')}`);
}

async function handleClearWarnings(interaction) {
    await safeDefer(interaction, {});
    const target = interaction.options.getUser('user');
    const guild = interaction.guild;

    delete moderationData[target.id];
    await saveModerationToGCS();

    // Remove warn roles
    const member = await guild.members.fetch(target.id).catch(() => null);
    if (member) {
        for (const roleName of [WARN1_ROLE_NAME, WARN2_ROLE_NAME]) {
            const role = guild.roles.cache.find(r => r.name === roleName);
            if (role) await member.roles.remove(role).catch(() => {});
        }
    }
    await safeEditReply(interaction, `✅ All warnings cleared for **${target.username}**. Warn roles removed.`);
}

async function handlePurge(interaction) {
    await safeDefer(interaction, { flags: [MessageFlags.Ephemeral] });

    const channel = interaction.channel;
    const count         = interaction.options.getInteger('count') || 100;
    const userFilter    = interaction.options.getUser('user');
    const afterOption   = interaction.options.getString('after');
    const beforeOption  = interaction.options.getString('before');
    const botsOnly      = interaction.options.getBoolean('bots') || false;
    const humansOnly    = interaction.options.getBoolean('humans') || false;
    const contains      = interaction.options.getString('contains');
    const startsWith    = interaction.options.getString('starts_with');
    const endsWith      = interaction.options.getString('ends_with');
    const hasAttachments= interaction.options.getBoolean('has_attachments') || false;
    const hasLinks      = interaction.options.getBoolean('has_links') || false;
    const hasEmbeds     = interaction.options.getBoolean('has_embeds') || false;
    const includePinned = interaction.options.getBoolean('pinned') || false;

    const resolveId = (opt) => {
        if (!opt) return null;
        const m = opt.match(/\/(\d{17,20})(?:\/|$)/);
        return m ? m[1] : (opt.match(/^\d{17,20}$/) ? opt : null);
    };
    const afterId  = resolveId(afterOption);
    const beforeId = resolveId(beforeOption);

    try {
        const fetchOptions = { limit: Math.min(count, 100) };
        if (afterId)  fetchOptions.after  = afterId;
        if (beforeId) fetchOptions.before = beforeId;

        const fetched = await channel.messages.fetch(fetchOptions);
        let toDelete = Array.from(fetched.values());

        // ── Filters ─────────────────────────────────────────────────────────
        if (!includePinned)  toDelete = toDelete.filter(m => !m.pinned);
        if (userFilter)      toDelete = toDelete.filter(m => m.author.id === userFilter.id);
        if (botsOnly)        toDelete = toDelete.filter(m => m.author.bot);
        if (humansOnly)      toDelete = toDelete.filter(m => !m.author.bot);
        if (contains)        toDelete = toDelete.filter(m => m.content.toLowerCase().includes(contains.toLowerCase()));
        if (startsWith)      toDelete = toDelete.filter(m => m.content.toLowerCase().startsWith(startsWith.toLowerCase()));
        if (endsWith)        toDelete = toDelete.filter(m => m.content.toLowerCase().endsWith(endsWith.toLowerCase()));
        if (hasAttachments)  toDelete = toDelete.filter(m => m.attachments.size > 0);
        if (hasLinks)        toDelete = toDelete.filter(m => /https?:\/\/\S+/.test(m.content));
        if (hasEmbeds)       toDelete = toDelete.filter(m => m.embeds.length > 0);

        // Discord bulk-delete only works on messages < 14 days old
        const twoWeeksAgo = Date.now() - 14 * 24 * 60 * 60 * 1000;
        const deletable   = toDelete.filter(m => m.createdTimestamp > twoWeeksAgo);
        const tooOld      = toDelete.length - deletable.length;

        if (deletable.length === 0) {
            return safeEditReply(interaction, 
                `❌ No messages matched the filters.${tooOld > 0 ? ` (${tooOld} skipped — older than 14 days)` : ''}`
            );
        }

        let deleted = 0;
        if (deletable.length === 1) {
            await deletable[0].delete();
            deleted = 1;
        } else {
            const result = await channel.bulkDelete(deletable, true);
            deleted = result.size;
        }

        // Build human-readable filter summary
        const filters = [];
        if (userFilter)      filters.push(`from @${userFilter.username}`);
        if (botsOnly)        filters.push('bots only');
        if (humansOnly)      filters.push('humans only');
        if (contains)        filters.push(`containing "${contains}"`);
        if (startsWith)      filters.push(`starting with "${startsWith}"`);
        if (endsWith)        filters.push(`ending with "${endsWith}"`);
        if (hasAttachments)  filters.push('has attachments');
        if (hasLinks)        filters.push('has links');
        if (hasEmbeds)       filters.push('has embeds');
        if (afterId)         filters.push(`after ${afterId}`);
        if (beforeId)        filters.push(`before ${beforeId}`);
        if (includePinned)   filters.push('including pinned');
        const filterStr = filters.length > 0 ? `\n**Filters:** ${filters.join(' · ')}` : '';

        let reply = `🗑️ Deleted **${deleted}** message${deleted !== 1 ? 's' : ''}.${filterStr}`;
        if (tooOld > 0) reply += `\n⚠️ ${tooOld} message${tooOld !== 1 ? 's' : ''} skipped (older than 14 days).`;

        await safeEditReply(interaction, reply);
        console.log(`🗑️ Purge by ${interaction.user.username} in #${channel.name}: ${deleted} deleted — ${filterStr || 'no filters'}`);
    } catch (e) {
        console.error('❌ Purge error:', e.message);
        await safeEditReply(interaction, `❌ Purge failed: \`${e.message}\``);
    }
}

async function handleNextUpdate(interaction) {
    if (!interaction.channel?.isThread()) {
        return safeReply(interaction, { content: '❌ Only works in a support thread.', flags: [MessageFlags.Ephemeral] });
    }
    await safeDefer(interaction, {});
    const thread = interaction.channel;

    const msg = [
        `🛠️ **Fixed in Next Update!**`,
        ``,
        `Great news — this issue has been identified and will be resolved in the **next Punchy! update**. 🎉`,
        ``,
        `You don't need to do anything. The fix will ship automatically with the next release.`,
        `Keep an eye on the announcements channel for update notes!`
    ].join('\n');

    await safeEditReply(interaction, msg);

    // Store solution
    await storeSolution(thread).catch(() => {});

    // Rename + lock + archive
    const cleanName = thread.name.replace(/\[.*?\] /g, '');
    try { await thread.setName(await safeThreadName('[Fixed Next Update] ', cleanName)); } catch (e) { console.warn('⚠️ Could not rename:', e.message); }
    try { await thread.setLocked(true, 'Fixed in next update.'); } catch (e) { console.warn('⚠️ Could not lock:', e.message); }
    try { await thread.setArchived(true); } catch (e) { console.warn('⚠️ Could not archive:', e.message); }

    // Clean up tracking
    if (repliedTimers.has(thread.id)) { clearTimeout(repliedTimers.get(thread.id).timeoutId); repliedTimers.delete(thread.id); }
    activeThreadIndex.delete(thread.id);
    delete threadMemory[thread.id];

    console.log(`🛠️ Thread marked "Fixed in Next Update": ${thread.name}`);
}

