// ============================================================
// ✨ DUPLICATE DETECTION SYSTEM
// Tracks all active support threads by title + content summary.
// When a new thread looks like a duplicate, Shubba pings owners
// in dev-chat with buttons to mark as duplicate or dismiss.
// ============================================================

// In-memory index: threadId → { title, summary, url, createdAt }
const activeThreadIndex = new Map();

/**
 * Build a short fingerprint from a thread name + starter message
 * for similarity comparison.
 */
function buildThreadFingerprint(name, content = '') {
    return `${name} ${content}`.toLowerCase()
        .replace(/[^\w\s]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .substring(0, 300);
}

/**
 * Use Gemini to decide if a new thread is likely a duplicate of
 * any existing tracked threads. Returns { isDuplicate, matches[] }
 * where matches is an array of { threadId, threadUrl, title, reason }.
 */
async function checkForDuplicates(newThread, starterContent) {
    if (activeThreadIndex.size === 0) return { isDuplicate: false, matches: [] };

    const candidates = Array.from(activeThreadIndex.values())
        .filter(t => t.threadId !== newThread.id)
        .slice(-60);

    if (candidates.length === 0) return { isDuplicate: false, matches: [] };

    const candidateList = candidates.map((t, i) =>
        `[${i + 1}] ID:${t.threadId} | Title: "${t.title.substring(0, 80)}" | Content: ${t.summary.substring(0, 120)}`
    ).join('\n');

    const prompt = `You are Shubba, a support bot for the Punchy! Minecraft mod. A new support thread has just been posted. Your job is to detect if this is a duplicate of an existing open report.

NEW THREAD:
Title: "${newThread.name}"
Content: "${starterContent.substring(0, 600)}"

EXISTING OPEN THREADS (all non-solved, non-closed):
${candidateList}

DUPLICATE DETECTION RULES:
A thread IS a duplicate if:
- It describes the same specific bug or broken behavior (e.g. both report arm clipping on shield raise)
- It reports the same crash with the same root cause
- It describes the same missing feature or broken animation with matching symptoms
- Even if the title is worded differently — focus on what the user is ACTUALLY experiencing

A thread is NOT a duplicate if:
- It only shares the same general topic (e.g. both about animations, but different animations)
- The symptoms are different even if the affected feature is similar
- One is a crash and one is a visual glitch

IMPORTANT: Be willing to flag probable duplicates — it's better to flag something for a human to dismiss than to miss a real duplicate. Use MEDIUM-HIGH confidence threshold, not ultra-strict.

Respond ONLY with this exact JSON (no markdown, no extra text):
{"isDuplicate": true_or_false, "matches": [{"index": 1, "reason": "one precise sentence describing the match"}]}

If no match: {"isDuplicate": false, "matches": []}
Maximum 2 matches.`;

    try {
        const raw = await callGemini(prompt, false);
        const clean = raw.replace(/```json|```/g, '').trim();
        const parsed = JSON.parse(clean);

        if (!parsed.isDuplicate || !parsed.matches?.length) {
            return { isDuplicate: false, matches: [] };
        }

        const resolvedMatches = parsed.matches
            .map(m => {
                const candidate = candidates[m.index - 1];
                if (!candidate) return null;
                return {
                    threadId: candidate.threadId,
                    threadUrl: candidate.url,
                    title: candidate.title,
                    reason: m.reason
                };
            })
            .filter(Boolean);

        return { isDuplicate: resolvedMatches.length > 0, matches: resolvedMatches };
    } catch (e) {
        console.error('⚠️ Duplicate check failed:', e.message);
        return { isDuplicate: false, matches: [] };
    }
}

/**
 * Send a duplicate alert to the dev channel with action buttons.
 * Owners can click "Mark as Duplicate" or "Not a Duplicate".
 */
async function sendDuplicateAlert(guild, newThread, matches) {
    try {
        const devChannel = await client.channels.fetch(DEV_CHANNEL_ID);
        if (!devChannel) return;

        const matchLines = matches.map((m, i) =>
            `**Match ${i + 1}:** <${m.threadUrl}>\n> ${m.reason.substring(0, 150)}`
        ).join('\n\n');

        const newThreadUrl = `https://discord.com/channels/${guild.id}/${newThread.id}`;
        // No ping at all. The alert is posted where moderators already look;
        // a suspected duplicate never justifies notifying anyone.
        const ownerPings = '';

        const alertContent = [
            `🔍 **Possible Duplicate Detected** ${ownerPings}`,
            ``,
            `New post: **${newThread.name.substring(0, 80)}**`,
            `Link: <${newThreadUrl}>`,
            ``,
            `May be a duplicate of:`,
            matchLines,
            ``,
            `Use the buttons below to decide:`
        ].join('\n');

        // Safety cap — Discord hard limit is 2000 chars
        const alertMsg = alertContent.length > 1900
            ? alertContent.substring(0, 1897) + '...'
            : alertContent;

        // Build buttons — only store IDs in customId (Discord limit: 100 chars)
        // The full URL is reconstructed from the guild ID + thread ID at click time
        const primaryMatchId = matches[0].threadId;

        const row = new ActionRowBuilder().addComponents(
            new ButtonBuilder()
                .setCustomId(`dup_yes:${newThread.id}:${primaryMatchId}`)
                .setLabel('✅ Mark as Duplicate')
                .setStyle(ButtonStyle.Danger),
            new ButtonBuilder()
                .setCustomId(`dup_no:${newThread.id}`)
                .setLabel('❌ Not a Duplicate')
                .setStyle(ButtonStyle.Secondary)
        );

        await devChannel.send({ content: alertMsg, components: [row] });
        console.log(`🔍 Duplicate alert sent to dev channel for thread: ${newThread.name}`);
    } catch (e) {
        console.error('❌ Failed to send duplicate alert:', e.message);
    }
}

/**
 * Handle "Mark as Duplicate" button press.
 * Tags OP, links the original thread, locks thread, schedules 24hr delete.
 */
async function handleMarkAsDuplicate(interaction, newThreadId, originalThreadUrl) {
    await safeDefer(interaction, {});

    try {
        const newThread = await client.channels.fetch(newThreadId).catch(() => null);
        if (!newThread) {
            return safeEditReply(interaction, '⚠️ Could not find the duplicate thread — it may have already been deleted.');
        }

        // Fetch OP
        let opPing = '';
        try {
            const starter = await newThread.fetchStarterMessage();
            if (starter) opPing = `<@${starter.author.id}> `;
        } catch (e) { /* ignore */ }

        const dupeMsg = [
            `🔁 ${opPing}**This post has been marked as a duplicate.**`,
            ``,
            `Please continue the conversation in the original thread: ${originalThreadUrl}`,
            ``,
            `This thread will be automatically closed in **24 hours**. If you believe this is a separate issue, please open a new post with all the required information.`
        ].join('\n');

        await newThread.send(dupeMsg);
        await newThread.setName(await safeThreadName('[DUPLICATE] ', newThread.name.replace('[DUPLICATE] ', '')));
        await newThread.setLocked(true, 'Marked as duplicate by owner.');

        // Schedule delete after 24 hours
        setTimeout(async () => {
            try {
                const t = await client.channels.fetch(newThreadId).catch(() => null);
                if (t && !t.archived) {
                    await t.setArchived(true).catch(() => {});
                }
            } catch (e) {
                console.error('⚠️ Failed to archive duplicate thread after 24hrs:', e.message);
            }
        }, 24 * 60 * 60 * 1000);

        // Remove from active index
        activeThreadIndex.delete(newThreadId);

        // Edit the alert message to remove buttons
        await safeEditReply(interaction, `✅ Marked as duplicate. OP notified, thread locked. Will auto-archive in 24 hours.`);
        await interaction.message.edit({ components: [] }).catch(() => {});

        console.log(`✅ Thread ${newThreadId} marked as duplicate by ${interaction.user.username}`);
    } catch (e) {
        console.error('❌ handleMarkAsDuplicate error:', e.message);
        await safeEditReply(interaction, '⚠️ Something went wrong. Check logs.').catch(() => {});
    }
}

/**
 * Handle "Not a Duplicate" button press.
 * Dismisses the alert, no action on the thread.
 */
async function handleDismissDuplicate(interaction, newThreadId) {
    await safeDefer(interaction, { flags: [MessageFlags.Ephemeral] });
    await interaction.message.edit({ components: [] }).catch(() => {});
    await safeEditReply(interaction, '✅ Dismissed — treated as a new unique post.');
    console.log(`🔍 Duplicate alert dismissed for thread ${newThreadId} by ${interaction.user.username}`);
}

// ============================================================
// END DUPLICATE DETECTION
// ============================================================

// ============================================================
// ✨ ANTI-SPAM & FLYTRAP SYSTEM
//
// TWO layers of detection — no account-age heuristics since
// scammers often use hacked existing accounts:
//
// Layer 1 — Honeypot channel (#message-flytrap)
//   Any message → instant kick. Channel keeps a rotating warning
//   message so innocent users don't accidentally post, but the
//   hint changes every 6 hours to stay unpredictable to bots.
//   Bots that scrape channel descriptions / pinned messages will
//   see a different message each time.
//
// Layer 2 — Behavioral rapid multi-channel spam detection
//   Watches ALL messages. Two tripwires, evaluated on a 5-second
//   sliding window of the user's recent activity:
//     A. 3+ distinct LOCATIONS *and* 3+ messages within 5s
//     B. 3+ attachments across 2+ LOCATIONS (2+ messages) within 3s
//   Either one → automatic kick. Works on accounts of any age.
//
//   "Location" = the parent forum/text channel. Thread IDs collapse to
//   their parent, so opening a thread is NOT a second location.
//
//   Counting: one user action is observed by up to three gateway paths
//   (the raw MESSAGE_CREATE listener, the MessageCreate handler, and
//   ThreadCreate). All three funnel through recordActivity(), which
//   dedupes on the message/thread ID so each action is counted EXACTLY
//   ONCE. Without that, two real messages looked like four and tripped
//   the 3-message clause that exists to prevent exactly that.
//
//   Staff (Moderator / Helper / Helper | Bug Hunter) and devs are exempt —
//   they answer questions across several channels fast enough to look
//   like a bot. If role membership cannot be resolved, this system FAILS
//   SAFE and does not kick.
// ============================================================

// Rotating warning hints — varied wording, different lengths, different tones
// so bots can't trivially detect and filter "honeypot" keywords
const FLYTRAP_HINTS = [
    `⛔ **Do not send messages in this channel.** Sending anything here — even as a joke — will result in an **automatic ban**. This is a security channel. There is no exception for "I was just testing" or "I accidentally clicked here." If you see this, close the channel and move on.`,
    `🔒 **This channel is off-limits.** Any message sent here triggers an immediate ban — no warnings, no exceptions. This applies equally to real spam bots and to members joking around. The system does not distinguish intent.`,
    `🛑 **Automated ban zone.** Do not type here. Do not send files. Do not test this. If you send anything, you will be banned automatically. This rule applies to everyone, including people who think it's funny to try.`,
    `⚠️ **Warning: Automated security channel.** Sending any message here results in an immediate ban — no appeal process for "I was just joking" or "it was an accident." If you're here by accident, close this channel immediately without sending anything.`,
    `🚫 **Do not engage with this channel.** Any activity here — messages, files, reactions — will result in a permanent ban. This is not a test channel. This is not a joke. Joking around here is treated the same as spamming.`,
    `🔐 **Security checkpoint — do not enter.** This channel is monitored. Any message triggers an automatic ban. Members who send messages here "for fun" or "to see what happens" are banned the same as spammers. Close this tab and do not return.`,
    `❌ **Sending anything here will get you banned.** No exceptions for accidents, jokes, or curiosity. If you ended up here by mistake, close it without sending anything. If you send something anyway, your account will be removed from the server immediately.`,
    `🪤 **This is a honeypot channel.** Sending any message here causes an automatic ban. This applies to spam bots AND to real members who think they're being funny. The system cannot tell the difference — and neither does the moderation team.`,
];

// Tracks recent messages per user: userId → [{ channelId, locationId, threadId, dedupeKey, timestamp, ... }]
// SINGLE shared store. Written to ONLY through recordActivity() below, which
// dedupes — never push into this directly.
const recentMessageActivity = new Map();

// Roles that are never auto-moderated. Staff answer questions rapidly across
// #general-en / #bug-report / #wiki-questions and are the members MOST likely
// to trip a 3-locations-in-5s tripwire.
const HELPER_ROLE_ID = '1512896900465164328';             // Helper
const HELPER_BUG_HUNTER_ROLE_ID = '1450232834701787209';  // Helper | Bug Hunter
const AUTOMOD_EXEMPT_ROLE_IDS = [
    MOD_ROLE_ID,                 // Moderator (declared with the other role IDs above)
    HELPER_ROLE_ID,
    HELPER_BUG_HUNTER_ROLE_ID,
];

// ─── SPAM TRIPWIRE CORE ─────────────────────────── TESTABLE-BLOCK-START ────
// Everything between the TESTABLE-BLOCK markers is pure: no discord.js objects,
// no module-level state, no I/O. The store and clock are parameters. test/
// anti-spam.test.js extracts this exact source range and evaluates it, so the
// tests exercise the shipped logic rather than a copy of it.

const SPAM_HISTORY_WINDOW_MS = 5000;      // Tripwire A window
const SPAM_ATTACHMENT_WINDOW_MS = 3000;   // Tripwire B window
const SPAM_MIN_LOCATIONS = 3;             // Tripwire A: distinct locations
const SPAM_MIN_MESSAGES = 3;              // Tripwire A: total messages
const SPAM_ATTACH_MIN_TOTAL = 3;          // Tripwire B: attachments
const SPAM_ATTACH_MIN_LOCATIONS = 2;      // Tripwire B: distinct locations
const SPAM_ATTACH_MIN_MESSAGES = 2;       // Tripwire B: total messages

/**
 * Record ONE user action in the sliding window, exactly once.
 *
 * Discord surfaces a single user action to us over as many as three paths:
 *   1. the raw MESSAGE_CREATE gateway listener (fastest — wins the race),
 *   2. the MessageCreate handler (via checkBehavioralSpam),
 *   3. ThreadCreate (for forum/thread posts).
 * A thread's starter message carries a message ID equal to the thread ID, so
 * all three describe the same action under the same `dedupeKey`. The second and
 * third sightings must NOT add another entry — that inflation is what defeated
 * the 3-message safety clause on Tripwire A.
 *
 * @returns {{history: Array, deduped: boolean}} `deduped: true` means this
 *          action was already recorded; the caller must not re-evaluate.
 */
function recordActivity(store, uid, entry, now) {
    const history = (store.get(uid) || []).filter(m => now - m.timestamp < SPAM_HISTORY_WINDOW_MS);

    const existing = entry.dedupeKey != null
        ? history.find(m => m.dedupeKey != null && m.dedupeKey === entry.dedupeKey)
        : null;

    if (existing) {
        // Same action, second observer. Don't count it again — but do let a path
        // that knows more about the action improve the stored record. ThreadCreate
        // knows the authoritative parentId; the raw path may only have seen an
        // uncached thread and been unable to resolve a parent.
        if (entry.locationKnown && !existing.locationKnown) {
            existing.locationId = entry.locationId;
            existing.locationKnown = true;
        }
        if (existing.threadId == null && entry.threadId != null) existing.threadId = entry.threadId;
        if ((entry.attachments || 0) > (existing.attachments || 0)) existing.attachments = entry.attachments;
        store.set(uid, history);
        return { history, deduped: true };
    }

    history.push(entry);
    store.set(uid, history);
    return { history, deduped: false };
}

/**
 * Evaluate both tripwires against a recorded window.
 *
 * Entries whose location could not be resolved (`locationKnown === false` — an
 * uncached thread whose parent we don't know) still count toward the message
 * totals but do NOT contribute a distinct location. Counting an unresolved
 * thread as its own location is what would make three posts in ONE forum look
 * like three separate locations, so we stay conservative: an unknown location
 * can never be the thing that pushes a member over a threshold.
 *
 * @returns {null | {kind: string, reason: string, hist: Array}}
 */
function evaluateTripwires(history, now) {
    const located = history.filter(m => m.locationKnown !== false);

    // ── Tripwire A: 3+ locations AND 3+ messages in 5s ──────────────────────
    // Both clauses required. The message clause is the guard against a single
    // action being seen on more than one gateway path; it only works because
    // recordActivity() has already collapsed those duplicates.
    const uniqueLocations = new Set(located.map(m => m.locationId));
    if (uniqueLocations.size >= SPAM_MIN_LOCATIONS && history.length >= SPAM_MIN_MESSAGES) {
        return {
            kind: 'multi-channel',
            reason: `Rapid multi-channel spam: ${uniqueLocations.size} channels, ${history.length} messages in <${SPAM_HISTORY_WINDOW_MS / 1000}s`,
            hist: history,
        };
    }

    // ── Tripwire B: 3+ attachments across 2+ locations in 3s ────────────────
    const within = history.filter(m => now - m.timestamp < SPAM_ATTACHMENT_WINDOW_MS);
    const withinLocated = within.filter(m => m.locationKnown !== false);
    const totalAttachments = within.reduce((sum, m) => sum + (m.attachments || 0), 0);
    const attachmentLocations = new Set(withinLocated.filter(m => m.attachments > 0).map(m => m.locationId));
    if (totalAttachments >= SPAM_ATTACH_MIN_TOTAL &&
        attachmentLocations.size >= SPAM_ATTACH_MIN_LOCATIONS &&
        within.length >= SPAM_ATTACH_MIN_MESSAGES) {
        return {
            kind: 'attachment-flood',
            reason: `Attachment spam: ${totalAttachments} attachments across ${attachmentLocations.size} channels in ${SPAM_ATTACHMENT_WINDOW_MS / 1000}s`,
            hist: within,
        };
    }

    return null;
}

/**
 * Decide what auto-moderation may do to a user.
 *
 *   'exempt'       → bot, dev, or staff. Take no action at all.
 *   'cleanup-only' → roles could NOT be determined. FAIL SAFE: never kick;
 *                    clean the spam up and let a human decide.
 *   'kick'         → confirmed non-staff member. Kick is authorised.
 *
 * `deps` exists so tests can drive this without a live guild.
 */
async function resolveAutoModVerdict(guild, user, deps = {}) {
    const devIds = deps.devIds || DEV_IDS;
    const exemptRoleIds = deps.exemptRoleIds || AUTOMOD_EXEMPT_ROLE_IDS;

    if (!user || !user.id) return 'exempt';
    if (user.bot) return 'exempt';
    if (devIds.includes(user.id)) return 'exempt';

    if (!guild || !guild.members) return 'cleanup-only';   // FAIL SAFE

    // Cache first — the GuildMembers intent is enabled, so staff are essentially
    // always cached and this costs nothing on the fast kick path.
    let member = null;
    try { member = guild.members.cache?.get(user.id) || null; } catch (e) { member = null; }

    // Cache miss: one REST lookup. The user may have left the guild, the fetch
    // may time out, or the bot may lack permission — all resolve to null, and
    // null means "unknown roles", which must never escalate to a kick.
    if (!member) {
        try { member = await guild.members.fetch(user.id); } catch (e) { member = null; }
    }
    if (!member) return 'cleanup-only';                     // FAIL SAFE
    if (member.user?.bot) return 'exempt';

    const roleCache = member.roles?.cache;
    if (!roleCache || typeof roleCache.has !== 'function') return 'cleanup-only';  // FAIL SAFE

    for (const roleId of exemptRoleIds) {
        if (roleId && roleCache.has(roleId)) return 'exempt';
    }
    return 'kick';
}
// ─── SPAM TRIPWIRE CORE ───────────────────────────── TESTABLE-BLOCK-END ────

// "Snapped out of existence" counter — persisted to GCS, starting at 15
let snappedCount = 15;

async function saveSnappedCount() {
    try {
        gcsJsonSave('snapped_count.json', JSON.stringify({ count: snappedCount }));
    } catch(e) {}
}

async function loadSnappedCount() {
    try {
        const bucket = storage.bucket(BUCKET_NAME);
        const [exists] = await bucket.file('snapped_count.json').exists();
        if (exists) {
            const [data] = await bucket.file('snapped_count.json').download();
            const parsed = JSON.parse(data.toString());
            snappedCount = Math.max(15, parsed.count || 15);
            console.log(`✅ Snapped count loaded: ${snappedCount}`);
        }
    } catch(e) {}
}

// Clean up old tracking data every 10 minutes
setInterval(() => {
    const cutoff = Date.now() - 10 * 60 * 1000;
    for (const [uid, msgs] of recentMessageActivity.entries()) {
        const fresh = msgs.filter(m => m.timestamp > cutoff);
        if (fresh.length === 0) recentMessageActivity.delete(uid);
        else recentMessageActivity.set(uid, fresh);
    }
}, 10 * 60 * 1000);

/**
 * Hard ban — used by Layer 1 (flytrap honeypot).
 * Kicks, deletes messages, logs to dev channel.
 * The snapped counter is appended to the next hint rotation in the flytrap channel.
 */
async function executeSpamAction(guild, user, reason, triggerMessage = null) {
    if (!user || !user.id || user.bot || DEV_IDS.includes(user.id)) return;

    // Staff / dev / unresolvable-roles gate. 'cleanup-only' still deletes the
    // offending message but never kicks.
    const verdict = await resolveAutoModVerdict(guild, user);
    if (verdict === 'exempt') {
        console.log(`🛡️ Flytrap skipped for ${user.username} (${user.id}) — exempt (staff/dev/bot)`);
        return;
    }

    console.log(`🪤 FLYTRAP: ${user.username} (${user.id}) — ${reason}`);
    try {
        let msgContent = '';
        let attachmentLines = [];
        if (triggerMessage) {
            msgContent = triggerMessage.content
                ? `\`${triggerMessage.content.substring(0, 300)}\``
                : '*(no text)*';
            if (triggerMessage.attachments?.size > 0) {
                attachmentLines = Array.from(triggerMessage.attachments.values())
                    .map(a => `• ${a.name} — ${a.url}`);
            }
            await triggerMessage.delete().catch(() => {});
        }

        // Soft ban: kick + delete recent messages.
        // Only when roles were positively resolved to a non-staff member.
        if (verdict === 'kick') {
            const member = await guild.members.fetch(user.id).catch(() => null);
            if (member) await member.kick(`[Shubba Flytrap] ${reason}`);
        } else {
            console.warn(`⚠️ Flytrap: roles unresolved for ${user.username} (${user.id}) — FAIL SAFE, no kick`);
        }

        // Increment snapped counter
        snappedCount++; saveSnappedCount().catch(()=>{});

        // Update the flytrap channel hint to include the new counter
        rotateFlyTrapHint().catch(() => {});

        const devChannel = await client.channels.fetch(DEV_CHANNEL_ID).catch(() => null);
        if (devChannel) {
            const lines = [
                `🪤 **Flytrap Triggered**`,
                `**User:** ${user.username} (${user.id})`,
                `**Reason:** ${reason}`,
                `**Message:** ${msgContent}`,
            ];
            if (attachmentLines.length > 0) lines.push(`**Attachments:**\n${attachmentLines.join('\n')}`);
            lines.push(`**Action:** Kicked. Total snapped: **${snappedCount}**`);
            await devChannel.send(lines.join('\n'));
        }
        console.log(`✅ Flytrap kicked: ${user.username} — total snapped: ${snappedCount}`);
    } catch (e) {
        console.error(`❌ Flytrap kick failed for ${user.username}:`, e.message);
        const devChannel = await client.channels.fetch(DEV_CHANNEL_ID).catch(() => null);
        if (devChannel) await devChannel.send(`🪤 **Flytrap** detected **${user.username}** (${user.id}) — kick failed: \`${e.message}\` — handle manually.`);
    }
}

/**
 * Soft ban (kick + delete recent messages) — used by Layer 2 (behavioral multi-channel spam).
 * Posts the "Snapped out of existence" embed.
 */
// Track users currently being processed by anti-spam so we don't trigger twice
// during the kick window (the first messages arrive simultaneously over the wire).
const _activeKicks = new Set();

async function executeSoftBan(guild, user, reason, triggerMessage = null, spamChannelIds = [], spamThreadIds = [], deepScan = false) {
    if (!user || !user.id || user.bot || DEV_IDS.includes(user.id)) return;
    if (_activeKicks.has(user.id)) return; // already kicking
    _activeKicks.add(user.id);

    // Everything below runs inside try/finally so the _activeKicks guard is
    // always released. Without it, a throw anywhere in this function would pin
    // the user in the set forever and silently disable moderation for them.
    try {
        await _executeSoftBanInner(guild, user, reason, triggerMessage, spamChannelIds, spamThreadIds, deepScan);
    } finally {
        _activeKicks.delete(user.id);
    }
}

async function _executeSoftBanInner(guild, user, reason, triggerMessage, spamChannelIds, spamThreadIds, deepScan) {
    // Staff / dev / unresolvable-roles gate — the single chokepoint every
    // behavioral tripwire funnels through.
    const verdict = await resolveAutoModVerdict(guild, user);
    if (verdict === 'exempt') {
        console.log(`🛡️ Anti-spam skipped for ${user.username} (${user.id}) — exempt (staff/dev/bot)`);
        recentMessageActivity.delete(user.id);
        return;
    }

    const startMs = Date.now();
    console.log(`🚨 ANTI-SPAM: ${user.username} (${user.id}) — ${reason}${deepScan ? ' [deep scan]' : ''}`);

    // ── SNAPSHOT before clearing activity ────────────────────────────────────
    const history = recentMessageActivity.get(user.id) || [];
    const channelsToCheck = new Set([
        ...spamChannelIds,
        ...history.map(m => m.channelId).filter(Boolean),
        ...(triggerMessage ? [triggerMessage.channelId] : []),
    ]);
    const threadIdsToDelete = new Set([
        ...spamThreadIds,
        ...history.map(m => m.threadId).filter(Boolean),
    ]);
    recentMessageActivity.delete(user.id);

    // ── DEEP SCAN: add every text channel in the guild ───────────────────────
    // For flytrap triggers we can't rely on recentMessageActivity alone — the
    // spammer may have posted in other channels minutes ago, outside our 5s
    // tracking window. So we sweep ALL text channels the bot can see.
    if (deepScan) {
        for (const [, ch] of guild.channels.cache) {
            if (ch && ch.isTextBased && ch.isTextBased() && !ch.isThread?.()) {
                channelsToCheck.add(ch.id);
            }
        }
        console.log(`🔍 Deep scan: checking ${channelsToCheck.size} channels for ${user.username}'s messages`);
    }

    // ── FAST PATH: KICK FIRST ────────────────────────────────────────────────
    // Once kicked, the user can't send more messages. Deletion happens after.
    // This is critical for shutting down active spam in <1s after detection.
    let kicked = false;
    let kickError = null;
    if (verdict === 'kick') {
        try {
            // guild.members.kick(userId, reason) is the fastest API surface. It does
            // NOT fetch the member first — it goes straight to the REST kick endpoint
            // with the user ID. Saves a 50-300ms member lookup roundtrip vs the
            // member.kick() pattern.
            await guild.members.kick(user.id, `[Shubba Anti-Spam] ${reason}`);
            kicked = true;
            console.log(`👢 Kicked ${user.username} in ${Date.now() - startMs}ms`);
        } catch(e) {
            kickError = e.message;
            console.error(`❌ Kick failed for ${user.username}: ${e.message}`);
        }
    } else {
        // verdict === 'cleanup-only': we could not confirm the user is not staff.
        // FAIL SAFE — clean up the spam, alert the dev channel, kick nobody.
        kickError = 'roles unresolved — fail-safe, no kick (needs manual review)';
        console.warn(`⚠️ Anti-spam FAIL SAFE for ${user.username} (${user.id}): could not resolve roles, not kicking`);
    }

    // ── PARALLEL CLEANUP (happens after kick, user can't react) ──────────────
    let deletedThreads = 0;
    let deletedMessages = 0;
    const cleanupOps = [];

    // Trigger message
    if (triggerMessage) {
        cleanupOps.push(triggerMessage.delete()
            .then(() => { deletedMessages++; })
            .catch(() => {}));
    }

    // Thread deletions
    for (const threadId of threadIdsToDelete) {
        cleanupOps.push((async () => {
            try {
                const thread = await client.channels.fetch(threadId).catch(() => null);
                if (thread && thread.isThread && thread.isThread()) {
                    await thread.delete(`[Shubba Anti-Spam] Spam thread by ${user.username}`);
                    deletedThreads++;
                }
            } catch(e) {}
        })());
    }

    // Message cleanup across channels — parallel + bulkDelete
    for (const channelId of channelsToCheck) {
        cleanupOps.push((async () => {
            try {
                const ch = await client.channels.fetch(channelId).catch(() => null);
                if (!ch?.isTextBased || !ch.isTextBased()) return;

                const recent = await ch.messages.fetch({ limit: 100 }).catch(() => null);
                if (!recent) return;
                const userMsgs = Array.from(recent.values()).filter(m => m.author.id === user.id);
                if (userMsgs.length === 0) return;

                const fresh = userMsgs.filter(m => Date.now() - m.createdTimestamp < 14 * 24 * 60 * 60 * 1000);
                const old = userMsgs.filter(m => Date.now() - m.createdTimestamp >= 14 * 24 * 60 * 60 * 1000);

                if (fresh.length >= 2 && ch.bulkDelete) {
                    try {
                        const deleted = await ch.bulkDelete(fresh, true).catch(() => null);
                        if (deleted) deletedMessages += deleted.size;
                    } catch(e) {
                        for (const msg of fresh) {
                            await msg.delete().catch(() => {});
                            deletedMessages++;
                        }
                    }
                } else {
                    for (const msg of fresh) {
                        await msg.delete().catch(() => {});
                        deletedMessages++;
                    }
                }
                for (const msg of old) {
                    await msg.delete().catch(() => {});
                    deletedMessages++;
                }
            } catch(e) {}
        })());
    }

    await Promise.allSettled(cleanupOps);
    const totalMs = Date.now() - startMs;
    console.log(`🗑️ Cleanup done in ${totalMs}ms total: ${deletedMessages} msgs, ${deletedThreads} threads`);

    // Counter + dev embed
    if (kicked) {
        snappedCount++;
        saveSnappedCount().catch(()=>{});
    }

    try {
        const devChannel = await client.channels.fetch(DEV_CHANNEL_ID).catch(() => null);
        if (devChannel) {
            const embed = new EmbedBuilder()
                .setColor(kicked ? 0x7c6ff7 : 0xff5050)
                .setTitle(kicked ? '👢 Snapped Out of Existence' : '⚠️ Anti-Spam Triggered (kick failed)')
                .setDescription(`**${user.username}** (${user.id}) ${kicked ? 'was kicked' : 'detected'} for spam.\n\n**Reason:** ${reason}`)
                .addFields(
                    { name: 'Action', value: `${kicked ? '✅ Kicked' : `❌ Not kicked (${kickError || 'unknown'})`} · 🗑️ ${deletedMessages} msgs · 🧵 ${deletedThreads} threads`, inline: false },
                    { name: 'Speed', value: `Kicked in ${kicked ? Date.now() - startMs : '—'}ms · Total cleanup ${totalMs}ms`, inline: false }
                )
                .setFooter({ text: `Snapped out of existence accounts: ${snappedCount}` })
                .setTimestamp();
            await devChannel.send({ embeds: [embed] });
        }
    } catch(e) {}
}

/**
 * Layer 1 — Honeypot trigger.
 */
async function handleFlyTrapTrigger(message) {
    // Use executeSoftBan — it does FULL cleanup: deletes the trigger message,
    // PLUS scans every channel the user posted in recently (from recentMessageActivity)
    // and deletes those too, PLUS kills any spam threads they created.
    // The old executeSpamAction only deleted the single flytrap message, which is
    // why flytrap-tripped users kept leaving spam behind in other channels.
    await executeSoftBan(
        message.guild,
        message.author,
        'Sent a message in honeypot channel #message-flytrap',
        message,
        [message.channelId],   // ensure flytrap channel itself is scanned
        [],
        true                   // deepScan — flytrap victims often spammed other channels earlier
    );
}

/**
 * Layer 2 — Rapid multi-channel spam detection (MessageCreate path).
 *
 * Key insight: Discord fires MessageCreate for the thread starter message,
 * which has a different channelId than the parent forum. If we naively count
 * channel IDs, ONE forum post creates TWO "channels" (parent + thread) in
 * one action — a guaranteed false positive at the 2-channel threshold.
 *
 * Fix: normalize thread channelIds to their parent. A thread and its parent
 * count as the SAME location for spam purposes.
 *
 * This is the SLOW path and is normally a no-op. The raw gateway listener sees
 * the same MESSAGE_CREATE ~10-20ms earlier and records it first, so by the time
 * this runs, recordActivity() reports `deduped` and we return without counting
 * or re-evaluating anything. It stays wired up as a fallback for the case where
 * the raw packet was missed (or the raw listener is not installed), which keeps
 * detection working without ever double-counting.
 *
 * Thresholds live in evaluateTripwires() — see the SPAM TRIPWIRE CORE block.
 */
async function checkBehavioralSpam(message) {
    if (!message?.author || message.author.bot || !message.guild) return;
    if (DEV_IDS.includes(message.author.id)) return;
    if (_activeKicks.has(message.author.id)) return;
    const uid = message.author.id;
    const now = Date.now();

    // Normalize: if this message is in a thread, use the parent channel ID as
    // the "location" so opening a thread doesn't count as a new channel.
    const channel = message.channel;
    const isThread = !!(channel?.isThread && channel.isThread());
    const locationId = isThread ? (channel.parentId || channel.id) : message.channelId;

    const { history, deduped } = recordActivity(recentMessageActivity, uid, {
        dedupeKey: message.id,                   // same key the raw path uses
        channelId: message.channelId,            // exact channel — used for message deletion later
        locationId,                              // normalized — used for spam threshold counting
        locationKnown: !isThread || !!channel.parentId,
        threadId: isThread ? channel.id : null,
        messageId: message.id,
        attachments: message.attachments?.size || 0,
        timestamp: now,
    }, now);

    // Already seen on a faster path — counting or judging it again would act on
    // the same evidence twice.
    if (deduped) return;

    const verdict = evaluateTripwires(history, now);
    if (verdict) return _trigger(message, verdict.kind, verdict.reason, verdict.hist);
}

async function _trigger(message, kind, reason, relevantHistory) {
    const spamChannelIds = Array.from(new Set(relevantHistory.map(m => m.channelId).filter(Boolean)));
    const spamThreadIds = relevantHistory.map(m => m.threadId).filter(Boolean);
    console.log(`🪤 [${kind}] ${message.author.username}: ${reason}`);

    // Don't delete the activity here — executeSoftBan needs to read it for full
    // channel coverage. executeSoftBan clears it after taking a snapshot.
    await executeSoftBan(
        message.guild,
        message.author,
        reason,
        message,
        spamChannelIds,
        spamThreadIds
    );
}

/**
 * Rotate the flytrap warning message.
 * Called on boot and every 6 hours so the hint text stays unpredictable.
 * Also called immediately after a flytrap trigger to update the counter.
 */
let _flyTrapMsgId = null;
async function rotateFlyTrapHint() {
    try {
        const channel = await client.channels.fetch(FLYTRAP_CHANNEL_ID).catch(() => null);
        if (!channel) return;

        const hint = FLYTRAP_HINTS[Math.floor(Math.random() * FLYTRAP_HINTS.length)];
        // Append the snapped counter
        const fullHint = `${hint}\n\n> 👢 **Snapped out of existence accounts: ${snappedCount}**`;

        if (_flyTrapMsgId) {
            try {
                const existing = await channel.messages.fetch(_flyTrapMsgId);
                await existing.edit(fullHint);
                console.log('🪤 Flytrap hint rotated (edited existing message).');
                return;
            } catch (e) {
                _flyTrapMsgId = null;
            }
        }

        const recent = await channel.messages.fetch({ limit: 20 });
        for (const msg of recent.values()) {
            if (msg.author.id === client.user?.id) await msg.delete().catch(() => {});
        }

        const sent = await channel.send(fullHint);
        _flyTrapMsgId = sent.id;
        console.log('🪤 Flytrap hint posted fresh.');
    } catch (e) {
        console.error('⚠️ Failed to rotate flytrap hint:', e.message);
    }
}

// Legacy name kept for compatibility — routes to rotateFlyTrapHint
async function ensureFlyTrapSticky() {
    await rotateFlyTrapHint();
}

