/**
 * Detect language from text content
 * Returns language code (e.g., 'EN-US', 'ZH-CN')
 */
function detectLanguage(text) {
    const textLower = text.toLowerCase();
    
    // Check for Chinese characters
    if (/[\u4e00-\u9fa5]/.test(text)) {
        return 'ZH-CN';
    }
    
    // Check for Japanese characters (Hiragana, Katakana, Kanji)
    if (/[\u3040-\u309f\u30a0-\u30ff\u4e00-\u9faf]/.test(text)) {
        return 'JA-JP';
    }
    
    // Check for Cyrillic (Russian)
    if (/[\u0400-\u04ff]/.test(text)) {
        return 'RU-RU';
    }
    
    // Keyword scoring for Latin-script languages.
    //
    // ⚠️ English MUST be scored as a competitor. It previously wasn't — it was
    // only the fallback when nothing else matched — so any English sentence
    // containing a word that also appears in another list won outright.
    // "how do I do sword smear frames?" scored 2 for Portuguese (\bdo\b twice)
    // and 0 for English, and a plain English question got answered in Portuguese.
    //
    // Single-letter tokens (o, e, y, a) are deliberately excluded: they carry
    // almost no signal and collide constantly.
    const languageKeywords = {
        'EN-US': ['the', 'and', 'is', 'are', 'you', 'your', 'to', 'it', 'my', 'not', 'can', 'how',
                  'do', 'does', 'with', 'have', 'this', 'that', 'for', 'in', 'on', 'of', 'me',
                  'help', 'error', 'problem', 'animation', 'mod', 'but', 'when', 'why', 'what',
                  'there', 'still', 'work', 'works', 'working', 'fix', 'know', 'want', 'make'],
        'DE-DE': ['der', 'die', 'das', 'und', 'ich', 'ist', 'nicht', 'haben', 'werden', 'können',
                  'mein', 'fehler', 'hilfe', 'wie', 'kann', 'machen', 'aber', 'auch', 'funktioniert', 'bitte'],
        'ES-ES': ['el', 'la', 'que', 'es', 'no', 'un', 'por', 'con', 'mi', 'pero', 'problema', 'ayuda',
                  'dónde', 'puedo', 'cómo', 'qué', 'sobre', 'errores', 'hacer', 'tengo', 'está',
                  'más', 'también', 'funciona', 'gracias', 'una', 'los', 'las'],
        'FR-FR': ['le', 'un', 'et', 'être', 'avoir', 'que', 'pour', 'dans', 'ce', 'mon', 'erreur',
                  'problème', 'aide', 'où', 'comment', 'puis', 'faire', 'avec', 'mais', 'aussi',
                  'fonctionne', 'merci', 'les', 'des'],
        'PT-BR': ['de', 'que', 'do', 'da', 'em', 'um', 'para', 'com', 'não', 'meu', 'erro', 'ajuda',
                  'onde', 'posso', 'como', 'sobre', 'erros', 'fazer', 'tenho', 'está', 'mais',
                  'também', 'funciona', 'obrigado', 'você', 'uma', 'dos']
    };

    // Diacritics and punctuation that effectively only occur in one language.
    // Worth several keywords each — "¿dónde?" is unambiguous where "como" is not.
    const strongMarkers = [
        [/[¿¡ñ]/, 'ES-ES'],
        [/[ãõ]/, 'PT-BR'],
        [/[ß]|[äöü]/, 'DE-DE'],
        [/[œàèùêâôî]/, 'FR-FR'],
    ];

    const scores = {};
    for (const [lang, keywords] of Object.entries(languageKeywords)) {
        let score = 0;
        for (const keyword of keywords) {
            const matches = textLower.match(new RegExp(`\\b${keyword}\\b`, 'gi'));
            if (matches) score += matches.length;
        }
        scores[lang] = score;
    }

    // Diacritic evidence is strong; weight it above ordinary keyword hits.
    for (const [re, lang] of strongMarkers) {
        const hits = (text.match(new RegExp(re.source, 'gi')) || []).length;
        if (hits) scores[lang] += 2 + hits;
    }

    const enScore = scores['EN-US'];
    let detectedLang = 'EN-US';
    let maxScore = enScore;
    for (const [lang, score] of Object.entries(scores)) {
        if (lang !== 'EN-US' && score > maxScore) { maxScore = score; detectedLang = lang; }
    }

    // A non-English guess must BEAT English outright and clear the noise floor.
    // Ties go to English: shared tokens ("do", "como") are evidence of nothing.
    if (detectedLang !== 'EN-US' && (maxScore <= enScore || maxScore < 2)) return 'EN-US';
    return detectedLang;
}

/**
 * Discord-safe wiki hyperlink. Always wiki.punchymod.com — the GitHub wiki is
 * not publicly readable and every link into it 404s for users.
 */
function getWikiLink(pageName, langCode) {
    return `<${wikiPageUrl(pageName, langCode)}>`; // angle brackets suppress embeds
}

// State Tracking
let DYNAMIC_KNOWLEDGE_CACHE = {};
const KNOWLEDGE_CACHE_DURATION = 10 * 60 * 1000;
let LATEST_VERSIONS = {};
const pausedThreads = new Set();

// ── PASSIVE MODE ──────────────────────────────────────────────────────────────
// When active, Shubba silently skips responding in the support forum but still
// learns from threads in the background. Auto-expires after PASSIVE_DURATION_MS.
const PASSIVE_DURATION_MS = 5 * 24 * 60 * 60 * 1000; // 5 days
let passiveModeExpiry = null; // null = not active; Date timestamp = active until

function isPassiveModeActive() {
    if (!passiveModeExpiry) return false;
    if (Date.now() >= passiveModeExpiry) {
        passiveModeExpiry = null;
        savePassiveModeToGCS().catch(() => {});
        console.log('✅ Passive mode expired — Shubba is responding again');
        return false;
    }
    return true;
}

async function savePassiveModeToGCS() {
    try {
        const data = JSON.stringify({ expiry: passiveModeExpiry });
        // Write to tmp first then upload — avoids EPIPE on Cloud Run
        const tmpPath = require('path').join(require('os').tmpdir(), 'passive_mode.json');
        require('fs').writeFileSync(tmpPath, data);
        await storage.bucket(BUCKET_NAME).upload(tmpPath, {
            destination: 'passive_mode.json',
            metadata: { contentType: 'application/json' }
        });
        require('fs').unlinkSync(tmpPath);
    } catch(e) { console.warn('⚠️ Failed to save passive mode:', e.message); }
}

async function loadPassiveModeFromGCS() {
    try {
        const file = storage.bucket(BUCKET_NAME).file('passive_mode.json');
        const [exists] = await file.exists();
        if (!exists) return;
        const [data] = await file.download();
        const parsed = JSON.parse(data.toString());
        if (parsed.expiry && Date.now() < parsed.expiry) {
            passiveModeExpiry = parsed.expiry;
            const remainingHours = Math.round((parsed.expiry - Date.now()) / 36e5);
            console.log(`⏸️ Passive mode restored — expires in ~${remainingHours}h`);
        }
    } catch(e) { console.warn('⚠️ Failed to load passive mode:', e.message); }
}

// ── MOD ANALYTICS TRACKER ───────────────────────────────────────────────────
async function fetchModrinthDownloads(slug) {
    const r = await axios.get(`https://api.modrinth.com/v2/project/${slug}`, {
        headers: { 'User-Agent': 'Shubba-ModAnalytics/1.0 (hello@kennethrodas.com)' },
        timeout: 15000
    });
    return { total: r.data.downloads, followers: r.data.followers ?? null };
}

async function fetchCurseForgeDownloads(cfSlug) {
    // Optional integration. Without a key, skip this source — collectModSnapshot
    // catches it, marks the source ok:false and still saves the Modrinth numbers,
    // so analytics degrade instead of the snapshot (or the bot) falling over.
    if (!CF_API_KEY) throw new Error('CF_API_KEY not set — CurseForge stats skipped');
    if (!cfModIdCache[cfSlug]) {
        const search = await axios.get(
            `https://api.curseforge.com/v1/mods/search?gameId=432&slug=${cfSlug}&pageSize=1`,
            { headers: { 'x-api-key': CF_API_KEY, 'Content-Type': 'application/json' }, timeout: 15000 }
        );
        if (!search.data.data?.length) throw new Error(`CF: no mod found for slug "${cfSlug}"`);
        cfModIdCache[cfSlug] = search.data.data[0].id;
    }
    const modId = cfModIdCache[cfSlug];
    const r = await axios.get(`https://api.curseforge.com/v1/mods/${modId}`, {
        headers: { 'x-api-key': CF_API_KEY, 'Content-Type': 'application/json' }, timeout: 15000
    });
    return { total: r.data.data.downloadCount, followers: r.data.data.thumbsUpCount ?? null, modId };
}

async function collectModSnapshot() {
    const timestamp = new Date().toISOString();
    const results = {};
    await Promise.all(MOD_SOURCES.map(async (src) => {
        try {
            const data = src.platform === 'modrinth'
                ? await fetchModrinthDownloads(src.slug)
                : await fetchCurseForgeDownloads(src.cfSlug);
            results[src.key] = { ...data, ok: true };
        } catch (e) {
            console.warn(`[mod-analytics] ${src.key} failed: ${e.message}`);
            results[src.key] = { total: 0, ok: false, err: e.message };
        }
    }));
    return { timestamp, results };
}

async function saveModSnapshotToGCS(snapshot) {
    modAnalyticsHistory.push(snapshot);
    if (modAnalyticsHistory.length > MOD_ANALYTICS_MAX_HISTORY) {
        modAnalyticsHistory = modAnalyticsHistory.slice(-MOD_ANALYTICS_MAX_HISTORY);
    }
    await gcsJsonSave(MOD_ANALYTICS_GCS_KEY, modAnalyticsHistory);
    console.log(`[mod-analytics] Snapshot saved @ ${snapshot.timestamp} (${modAnalyticsHistory.length} total)`);
}

async function loadModAnalyticsHistory() {
    try {
        const file = storage.bucket(BUCKET_NAME).file(MOD_ANALYTICS_GCS_KEY);
        const [exists] = await file.exists();
        if (!exists) { modAnalyticsHistory = []; return; }
        const [data] = await file.download();
        const parsed = JSON.parse(data.toString());
        modAnalyticsHistory = Array.isArray(parsed) ? parsed : [];
        console.log(`[mod-analytics] Loaded ${modAnalyticsHistory.length} historical snapshots`);
    } catch(e) { console.warn('[mod-analytics] load history error:', e.message); modAnalyticsHistory = []; }
}

/**
 * Compute totals for a snapshot.
 */
function computeSnapTotals(snapshot) {
    if (!snapshot) return null;
    const r = snapshot.results;
    const punchyTotal = (r.punchy_mr?.total ?? 0) + (r.punchy_cf?.total ?? 0);
    const hmiCoreTotal = (r.hmi_mr?.total ?? 0) + (r.hmi_cf?.total ?? 0);
    const hmiEcoTotal = hmiCoreTotal
        + (r.hmi_refoxed_cf?.total ?? 0)
        + (r.hmi_reforged_cf?.total ?? 0)
        + (r.hmi_reforged_mr?.total ?? 0);
    return {
        timestamp: new Date(snapshot.timestamp).getTime(),
        punchy: punchyTotal,
        punchy_mr: r.punchy_mr?.total ?? 0,
        punchy_cf: r.punchy_cf?.total ?? 0,
        hmi_core: hmiCoreTotal,
        hmi_mr: r.hmi_mr?.total ?? 0,
        hmi_cf: r.hmi_cf?.total ?? 0,
        hmi_eco: hmiEcoTotal,
        hmi_refoxed_cf: r.hmi_refoxed_cf?.total ?? 0,
        hmi_reforged_cf: r.hmi_reforged_cf?.total ?? 0,
        hmi_reforged_mr: r.hmi_reforged_mr?.total ?? 0,
    };
}

/**
 * Find the snapshot closest to `targetMs` ago from latest. Returns null if no
 * snapshot in the lookback window (within ±25% of target span to allow some slack).
 */
function findSnapshotNear(latest, targetMsAgo) {
    if (!latest) return null;
    const targetTime = new Date(latest.timestamp).getTime() - targetMsAgo;
    const tolerance = targetMsAgo * 0.25; // ±25% slack
    let best = null;
    let bestDiff = Infinity;
    for (const s of modAnalyticsHistory) {
        const t = new Date(s.timestamp).getTime();
        const diff = Math.abs(t - targetTime);
        if (diff < tolerance && diff < bestDiff) {
            best = s;
            bestDiff = diff;
        }
    }
    return best;
}

/**
 * Compute deltas (downloads gained) between latest and a reference snapshot.
 * Normalises to a 24h rate so comparisons across snapshot intervals are fair.
 */
function computeDeltas(latestTotals, refSnapshot, expectedMsAgo) {
    if (!latestTotals || !refSnapshot) return null;
    const refTotals = computeSnapTotals(refSnapshot);
    if (!refTotals) return null;
    const actualMs = latestTotals.timestamp - refTotals.timestamp;
    if (actualMs <= 0) return null;
    const scale = expectedMsAgo / actualMs; // normalise rate to expected window
    return {
        actualSpanHours: Math.round(actualMs / 3600000 * 10) / 10,
        from: new Date(refTotals.timestamp).toISOString(),
        punchy: Math.round((latestTotals.punchy - refTotals.punchy) * scale),
        punchy_mr: Math.round((latestTotals.punchy_mr - refTotals.punchy_mr) * scale),
        punchy_cf: Math.round((latestTotals.punchy_cf - refTotals.punchy_cf) * scale),
        hmi_core: Math.round((latestTotals.hmi_core - refTotals.hmi_core) * scale),
        hmi_mr: Math.round((latestTotals.hmi_mr - refTotals.hmi_mr) * scale),
        hmi_cf: Math.round((latestTotals.hmi_cf - refTotals.hmi_cf) * scale),
        hmi_eco: Math.round((latestTotals.hmi_eco - refTotals.hmi_eco) * scale),
    };
}

function buildModSummary(snapshot) {
    if (!snapshot) return null;
    const r = snapshot.results;
    const punchyTotal = (r.punchy_mr?.total ?? 0) + (r.punchy_cf?.total ?? 0);
    const hmiCoreTotal = (r.hmi_mr?.total ?? 0) + (r.hmi_cf?.total ?? 0);
    const hmiEcoTotal = hmiCoreTotal
        + (r.hmi_refoxed_cf?.total ?? 0)
        + (r.hmi_reforged_cf?.total ?? 0)
        + (r.hmi_reforged_mr?.total ?? 0);

    // Compute deltas — daily (24h) and weekly (7d)
    const latestTotals = computeSnapTotals(snapshot);
    const ONE_DAY = 24 * 60 * 60 * 1000;
    const ONE_WEEK = 7 * ONE_DAY;
    const ONE_HOUR = 60 * 60 * 1000;
    const dayRef = findSnapshotNear(snapshot, ONE_DAY);
    const weekRef = findSnapshotNear(snapshot, ONE_WEEK);
    const hourRef = findSnapshotNear(snapshot, ONE_HOUR * 3); // since last snapshot (≈3h interval)

    return {
        timestamp: snapshot.timestamp,
        punchy: {
            total: punchyTotal,
            modrinth: r.punchy_mr?.total ?? 0,
            curseforge: r.punchy_cf?.total ?? 0,
            modrinthFollowers: r.punchy_mr?.followers ?? null
        },
        hmi_core: {
            total: hmiCoreTotal,
            modrinth: r.hmi_mr?.total ?? 0,
            curseforge: r.hmi_cf?.total ?? 0
        },
        hmi_eco: {
            total: hmiEcoTotal,
            breakdown: {
                hmi_modrinth: r.hmi_mr?.total ?? 0,
                hmi_curseforge: r.hmi_cf?.total ?? 0,
                refoxed_curseforge: r.hmi_refoxed_cf?.total ?? 0,
                reforged_curseforge: r.hmi_reforged_cf?.total ?? 0,
                reforged_modrinth: r.hmi_reforged_mr?.total ?? 0
            }
        },
        leader_1v1: punchyTotal >= hmiCoreTotal ? 'Punchy!' : 'Hold My Items',
        leader_eco: punchyTotal >= hmiEcoTotal ? 'Punchy!' : 'HMI Ecosystem',
        diff_1v1: Math.abs(punchyTotal - hmiCoreTotal),
        diff_eco: Math.abs(punchyTotal - hmiEcoTotal),
        // Daily and weekly download deltas (downloads in the period, normalised to that period)
        daily: computeDeltas(latestTotals, dayRef, ONE_DAY),
        weekly: computeDeltas(latestTotals, weekRef, ONE_WEEK),
        recent: computeDeltas(latestTotals, hourRef, ONE_HOUR * 3) // last interval — useful for spike detection
    };
}

