const MODRINTH_USER_AGENT = 'Shubba-PunchyDependents/1.0 (+https://github.com/punchy-mod)';
const MODRINTH_DELAY_MS = 250;

function _sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function loadDependentsState() {
    // Published results
    try {
        const file = storage.bucket(BUCKET_NAME).file(PUNCHY_DEPENDENTS_GCS_KEY);
        const [exists] = await file.exists();
        if (exists) {
            const [data] = await file.download();
            punchyDependentsResults = JSON.parse(data.toString());
            console.log(`[dependents] Loaded results: ${punchyDependentsResults.dependants?.length ?? 0} dependents, ${punchyDependentsResults.mentions?.length ?? 0} mentions`);
        }
    } catch(e) { console.warn('[dependents] load results error:', e.message); }

    // In-progress accumulator
    try {
        const file = storage.bucket(BUCKET_NAME).file(PUNCHY_DEPENDENTS_WORKING_KEY);
        const [exists] = await file.exists();
        if (exists) {
            const [data] = await file.download();
            punchyDependentsWorking = JSON.parse(data.toString());
            console.log(`[dependents] Resumed working: ${punchyDependentsWorking.dependants?.length ?? 0} dependents, ${punchyDependentsWorking.mentions?.length ?? 0} mentions so far`);
        }
    } catch(e) { console.warn('[dependents] load working error:', e.message); }

    // Per-project cache (slim — just timestamps + flags, NOT full version arrays)
    try {
        const file = storage.bucket(BUCKET_NAME).file(PUNCHY_DEPENDENTS_CACHE_KEY);
        const [exists] = await file.exists();
        if (exists) {
            const [data] = await file.download();
            punchyDependentsCache = JSON.parse(data.toString());
            console.log(`[dependents] Loaded cache: ${Object.keys(punchyDependentsCache).length} entries`);
        }
    } catch(e) { console.warn('[dependents] load cache error:', e.message); }

    // Progress pointer
    try {
        const file = storage.bucket(BUCKET_NAME).file(PUNCHY_DEPENDENTS_PROGRESS_KEY);
        const [exists] = await file.exists();
        if (exists) {
            const [data] = await file.download();
            const parsed = JSON.parse(data.toString());
            if (parsed && parsed.type) punchyDependentsProgress = parsed;
            console.log(`[dependents] Resuming at type=${punchyDependentsProgress.type} offset=${punchyDependentsProgress.offset}`);
        }
    } catch(e) { console.warn('[dependents] load progress error:', e.message); }
}

async function _modrinthSearchPage(projectType, offset) {
    const params = new URLSearchParams({
        facets: JSON.stringify([[`project_type:${projectType}`]]),
        limit: String(DEPENDENTS_PAGE_SIZE),
        offset: String(offset),
        index: 'updated',
    });
    const res = await axios.get(`https://api.modrinth.com/v2/search?${params}`, {
        headers: { 'User-Agent': MODRINTH_USER_AGENT },
        timeout: 30000
    }).catch(e => { console.warn(`[dependents] search ${projectType} offset ${offset} failed:`, e.message); return null; });
    if (!res || res.status !== 200) return null;
    return { hits: res.data.hits, total: res.data.total_hits };
}

async function _checkProjectVersionsForPunchy(projectId, lastUpdated) {
    const cached = punchyDependentsCache[projectId];
    if (cached && cached.checkedAt && new Date(cached.checkedAt).getTime() >= new Date(lastUpdated).getTime()) {
        return { fromCache: true, versions: cached.versions || null };
    }
    const res = await axios.get(`https://api.modrinth.com/v2/project/${projectId}/versions`, {
        headers: { 'User-Agent': MODRINTH_USER_AGENT },
        timeout: 30000
    }).catch(() => null);
    if (!res || res.status !== 200) return { fromCache: false, versions: null };
    const matches = [];
    for (const version of res.data) {
        const dep = (version.dependencies || []).find(d => d.project_id === PUNCHY_PROJECT_ID);
        if (dep) {
            matches.push({
                versionId: version.id,
                versionName: version.name,
                dependencyType: dep.dependency_type,
                gameVersions: version.game_versions,
                loaders: version.loaders,
                datePublished: version.date_published,
            });
        }
    }
    return { fromCache: false, versions: matches.length > 0 ? matches : null };
}

function _hasPunchyMention(project) {
    if (project.project_id === PUNCHY_PROJECT_ID) return false;
    if (project.slug === PUNCHY_SLUG) return false;
    const haystacks = [project.description || '', project.title || ''];
    for (const text of haystacks) {
        for (const pattern of PUNCHY_MENTION_PATTERNS) {
            if (pattern.test(text)) return true;
        }
    }
    return false;
}

function _newWorkingAccumulator() {
    return {
        startedAt: new Date().toISOString(),
        totalChecked: 0,
        dependants: [],
        mentions: [],
        progressByType: {}, // type → { processed, total }
    };
}

async function _saveProgress() {
    await gcsJsonSave(PUNCHY_DEPENDENTS_PROGRESS_KEY, punchyDependentsProgress);
}

async function _saveWorking() {
    if (punchyDependentsWorking) await gcsJsonSave(PUNCHY_DEPENDENTS_WORKING_KEY, punchyDependentsWorking);
}

async function _saveCache() {
    await gcsJsonSave(PUNCHY_DEPENDENTS_CACHE_KEY, punchyDependentsCache);
}

async function _publishWorkingAsResults() {
    if (!punchyDependentsWorking) return;
    const w = punchyDependentsWorking;

    // Sort & finalize
    w.dependants.sort((a, b) => (b.downloads || 0) - (a.downloads || 0));
    w.mentions.sort((a, b) => (b.downloads || 0) - (a.downloads || 0));

    const dependants = w.dependants;
    const mentions = w.mentions;

    const output = {
        lastScraped: new Date().toISOString(),
        startedAt: w.startedAt,
        elapsedSec: Math.round((Date.now() - new Date(w.startedAt).getTime()) / 1000),
        punchyProjectId: PUNCHY_PROJECT_ID,
        totalChecked: w.totalChecked,
        counts: {
            explicit: dependants.length,
            explicitByType: dependants.reduce((acc, d) => { acc[d.projectType] = (acc[d.projectType]||0) + 1; return acc; }, {}),
            mentions: mentions.length,
            mentionsByType: mentions.reduce((acc, d) => { acc[d.projectType] = (acc[d.projectType]||0) + 1; return acc; }, {}),
            requiredOnly: dependants.filter(d => d.dependencyTypes.includes('required')).length,
            optionalOnly: dependants.filter(d => d.dependencyTypes.includes('optional')).length,
            embedded: dependants.filter(d => d.dependencyTypes.includes('embedded')).length,
        },
        dependants,
        mentions,
    };

    await gcsJsonSave(PUNCHY_DEPENDENTS_GCS_KEY, output);
    punchyDependentsResults = output;

    // Wipe working file for next cycle
    try {
        const f = storage.bucket(BUCKET_NAME).file(PUNCHY_DEPENDENTS_WORKING_KEY);
        await f.delete().catch(() => {});
    } catch(e) {}
    punchyDependentsWorking = null;

    console.log(`[dependents] ✅ CYCLE PUBLISHED — ${dependants.length} explicit, ${mentions.length} mentions (checked ${output.totalChecked} total)`);
}

/**
 * Run ONE chunk of the scrape (one page of one type), then return.
 * Updates progress + working accumulator + cache. When the cycle completes,
 * promotes working → published results.
 */
async function runDependentsChunk() {
    if (isDependentsScraping) {
        console.log('[dependents] Chunk already running, skipping');
        return { skipped: true };
    }
    isDependentsScraping = true;

    try {
        // Lazy-init working accumulator at start of new cycle
        if (!punchyDependentsWorking) {
            punchyDependentsWorking = _newWorkingAccumulator();
            // Reset progress to start
            punchyDependentsProgress = { type: DEPENDENTS_PROJECT_TYPES[0], offset: 0, totalForType: null };
            await _saveProgress();
            console.log('[dependents] 🔄 Starting new scrape cycle');
        }

        const { type, offset } = punchyDependentsProgress;
        if (!DEPENDENTS_PROJECT_TYPES.includes(type)) {
            // Shouldn't happen, but reset gracefully
            punchyDependentsProgress = { type: DEPENDENTS_PROJECT_TYPES[0], offset: 0, totalForType: null };
            await _saveProgress();
            return { reset: true };
        }

        console.log(`[dependents] Chunk: type=${type} offset=${offset}`);

        const page = await _modrinthSearchPage(type, offset);
        if (!page) {
            // Network error — bail out, retry next hour
            console.warn(`[dependents] Page fetch failed — retry next chunk`);
            return { failed: true };
        }

        const { hits, total } = page;
        punchyDependentsProgress.totalForType = total;
        punchyDependentsWorking.progressByType[type] = { processed: offset + hits.length, total };

        let depCount = 0;
        let mentionCount = 0;

        for (const project of hits) {
            const projectId = project.project_id;
            const lastUpdated = project.date_modified || project.date_created || new Date().toISOString();

            let result = null;
            try {
                result = await _checkProjectVersionsForPunchy(projectId, lastUpdated);
            } catch(e) { /* swallow */ }

            const versions = result?.versions || null;
            const fromCache = result?.fromCache;
            const isExplicit = !!versions;
            const isImplicit = !isExplicit && _hasPunchyMention(project);

            // SLIM cache entry — store flags + versions only when matched. Don't
            // hold full project metadata in cache (keeps the cache small even
            // with ~3000 entries).
            punchyDependentsCache[projectId] = {
                checkedAt: lastUpdated,
                isDependant: isExplicit,
                hasMention: isImplicit,
                ...(versions ? { versions } : {}),
            };

            if (isExplicit) {
                punchyDependentsWorking.dependants.push({
                    slug: project.slug,
                    title: project.title,
                    projectId,
                    projectType: type,
                    modrinthUrl: `https://modrinth.com/${type}/${project.slug}`,
                    iconUrl: project.icon_url || null,
                    author: project.author,
                    downloads: project.downloads,
                    follows: project.follows,
                    dateModified: project.date_modified,
                    dependencyTypes: [...new Set(versions.map(v => v.dependencyType))],
                    versions,
                });
                depCount++;
            } else if (isImplicit) {
                punchyDependentsWorking.mentions.push({
                    slug: project.slug,
                    title: project.title,
                    projectId,
                    projectType: type,
                    modrinthUrl: `https://modrinth.com/${type}/${project.slug}`,
                    iconUrl: project.icon_url || null,
                    author: project.author,
                    downloads: project.downloads,
                    follows: project.follows,
                    description: (project.description || '').slice(0, 300),
                });
                mentionCount++;
            }

            punchyDependentsWorking.totalChecked++;

            // Only sleep when we actually hit the version endpoint (not from cache)
            if (!fromCache) await _sleep(MODRINTH_DELAY_MS);
        }

        console.log(`[dependents] Chunk done: ${type} ${offset+hits.length}/${total} | +${depCount} explicit, +${mentionCount} mentions`);

        // Advance progress
        const nextOffset = offset + DEPENDENTS_PAGE_SIZE;
        if (nextOffset >= total || hits.length === 0) {
            // Done with this type — move to next
            const idx = DEPENDENTS_PROJECT_TYPES.indexOf(type);
            const nextType = DEPENDENTS_PROJECT_TYPES[idx + 1];
            if (nextType) {
                punchyDependentsProgress = { type: nextType, offset: 0, totalForType: null };
                console.log(`[dependents] Type "${type}" complete, advancing to "${nextType}"`);
            } else {
                // Cycle complete — publish results
                console.log(`[dependents] All types complete, publishing results`);
                await _saveCache();
                await _publishWorkingAsResults();
                punchyDependentsProgress = { type: DEPENDENTS_PROJECT_TYPES[0], offset: 0, totalForType: null };
                await _saveProgress();
                return { cycleComplete: true };
            }
        } else {
            punchyDependentsProgress = { type, offset: nextOffset, totalForType: total };
        }

        // Persist incrementally so a crash mid-cycle doesn't lose progress
        await _saveProgress();
        await _saveWorking();
        await _saveCache();

        return {
            chunkComplete: true,
            type,
            processedThisChunk: hits.length,
            totalProcessed: punchyDependentsWorking.totalChecked,
            depCount,
            mentionCount,
        };
    } catch(e) {
        console.error('[dependents] chunk error:', e.message);
        return { error: e.message };
    } finally {
        isDependentsScraping = false;
    }
}

function startPunchyDependentsCron() {
    console.log(`[dependents] Cron registered — chunks every ${DEPENDENTS_CHUNK_INTERVAL_MS/60000}min, ${DEPENDENTS_PAGE_SIZE} projects/chunk`);
    // First chunk after 5 min
    setTimeout(() => { runDependentsChunk().catch(e => console.error('[dependents] initial chunk error:', e.message)); }, 5 * 60 * 1000);
    // Then every hour
    setInterval(() => { runDependentsChunk().catch(e => console.error('[dependents] cron chunk error:', e.message)); }, DEPENDENTS_CHUNK_INTERVAL_MS);
}
