/**
 * Saves a small JSON payload to GCS via tmp file to avoid EPIPE on Cloud Run.
 * Cloud Run kills long-lived streaming TCP connections, so .save() (which streams)
 * fails on larger payloads. Writing to /tmp then uploading is reliable.
 */
async function gcsJsonSave(fileName, data) {
    const tmpPath = require('path').join(require('os').tmpdir(), `gcs_${fileName.replace(/\//g,'_')}`);
    try {
        require('fs').writeFileSync(tmpPath, typeof data === 'string' ? data : JSON.stringify(data, null, 2));
        await storage.bucket(BUCKET_NAME).upload(tmpPath, {
            destination: fileName,
            metadata: { contentType: 'application/json', cacheControl: 'no-cache' }
        });
    } finally {
        try { require('fs').unlinkSync(tmpPath); } catch(e) {}
    }
}
