// --- 5. HELPERS ---

/**
 * Split a reply into Discord-sized chunks WITHOUT breaking code fences.
 *
 * The old version split on the nearest newline and ignored ``` fences, so any
 * answer whose JSON block straddled the boundary produced a chunk ending in an
 * unclosed fence — Discord then rendered the whole remainder as one broken code
 * block. Shubba emits JSON constantly, so this fired often and looked like the
 * bot "failing".
 *
 * Here a fence left open at a cut is closed on the way out and reopened (with
 * its original language tag) on the way in, so every chunk is valid on its own.
 */


async function analyzeAttachments(message, threadId) {
    let details = "";
    let logContent = "";
    let hasVideo = false;
    let hasImage = false;
    const memory = getThreadMemory(threadId);

    // First, check for log URLs in the message content
    const logUrls = extractLogUrls(message.content);
    if (logUrls.length > 0) {
        details += `- Found ${logUrls.length} log URL(s)\n`;
        for (const url of logUrls) {
            const fetchedLog = await fetchLogFromUrl(url);
            if (fetchedLog) {
                logContent += `\n--- START OF LOG FROM: ${url} ---\n${fetchedLog.substring(0, 50000)}\n--- END OF LOG ---\n`;
                memory.hasLog = true;
            }
        }
    }

    // Then check attachments
    for (const attachment of message.attachments.values()) {
        const nameLower = attachment.name.toLowerCase();
        const contentType = attachment.contentType || "";
        details += `- Attached: ${attachment.name} (${contentType || 'unknown type'}, ${Math.round(attachment.size / 1024)}KB)\n`;
        
        memory.attachments.push({
            name: attachment.name,
            url: attachment.url,
            type: contentType,
            timestamp: Date.now()
        });
        
        // Video detection
        if (contentType.startsWith('video/') || nameLower.endsWith('.mp4') || nameLower.endsWith('.mov') || nameLower.endsWith('.webm')) {
            hasVideo = true;
            details += `  → VIDEO FILE detected\n`;
        }
        // Image detection (not video)
        else if (
            contentType.startsWith('image/') ||
            nameLower.endsWith('.png') || nameLower.endsWith('.jpg') ||
            nameLower.endsWith('.jpeg') || nameLower.endsWith('.webp') ||
            nameLower.endsWith('.gif')
        ) {
            hasImage = true;
            details += `  → IMAGE FILE detected: ${attachment.url}\n`;
            logContent += `\n--- IMAGE ATTACHED: ${attachment.name} ---\nURL: ${attachment.url}\nThe user has attached a screenshot/image. Acknowledge that you can see it and respond accordingly.\n--- END IMAGE ---\n`;
        }

        const isLog = nameLower.includes('log') || nameLower.includes('crash');
        const isModlist = nameLower.includes('mod') || nameLower.includes('lista');
        if (isLog) memory.hasLog = true;
        if (isModlist) memory.hasModlist = true;

        // Read any text-readable file — expanded well beyond logs/modlists
        const TEXT_EXTENSIONS = ['.txt', '.json', '.json5', '.cfg', '.conf', '.config',
            '.properties', '.yaml', '.yml', '.toml', '.xml', '.log', '.md', '.csv',
            '.js', '.ts', '.java', '.py', '.lua', '.sh', '.mcfunction', '.nbt'];
        const isTextReadable = contentType.startsWith('text/')
            || contentType === 'application/json'
            || contentType === 'application/xml'
            || TEXT_EXTENSIONS.some(ext => nameLower.endsWith(ext))
            || isLog || isModlist;

        if (isTextReadable) {
            try {
                const response = await axios.get(attachment.url, { 
                    responseType: 'arraybuffer',
                    timeout: 30000,
                    maxContentLength: 50 * 1024 * 1024
                });
                const buffer = Buffer.from(response.data);
                let text;
                if (buffer.length >= 2 && ((buffer[0] === 0xFF && buffer[1] === 0xFE) || (buffer[0] === 0xFE && buffer[1] === 0xFF))) {
                    text = buffer.toString('utf16le');
                } else if (buffer.includes(0x00)) {
                    text = buffer.toString('utf16le');
                } else {
                    text = buffer.toString('utf8');
                }
                const label = isLog ? 'LOG/CRASH FILE' : isModlist ? 'MODLIST FILE' : 'FILE CONTENTS';
                logContent += `\n--- ${label}: ${attachment.name} ---\n${text.substring(0, 50000)}\n--- END OF ${attachment.name} ---\n`;
                details += `  → READ CONTENTS (${text.length} chars)\n`;
            } catch (e) { 
                console.log(`⚠️ Failed to read attachment: ${attachment.name}`, e.message);
                logContent += `\n--- FILE: ${attachment.name} (Failed to read: ${e.message}) ---\n`;
            }
        }
    }
    return { details, logContent, hasVideo, hasImage };
}

async function applyTagsFromText(message, thread) {
    const content = message.content.toLowerCase();

    // Collect desired tag NAMES in priority order. Discord caps a thread at 5
    // tags, and a post like "crash with a visual glitch in a modpack on fabric
    // 26.2" matches far more than 5. Ordering matters: whatever lands first
    // survives the cap, so loader/version (which triage actually filters on)
    // come before symptom labels.
    const desiredNames = [];

    // Mod loaders
    if (content.includes('neoforge') || content.includes('neo forge')) desiredNames.push('NeoForge');
    else if (content.includes('forge')) desiredNames.push('Forge');
    if (content.includes('fabric')) desiredNames.push('Fabric');

    // Versions (check longest first so '1.21' can't shadow '1.21.11')
    const sortedVersions = sortVersionsBySpecificity(
        [...TAG_CATEGORIES.VERSIONS].filter(v => v !== 'All')
    );
    for (const v of sortedVersions) {
        if (content.includes(v)) { desiredNames.push(v); break; }
    }

    // Issue types
    if (content.includes('crash') || content.includes('fatal error') || content.includes('java.lang')) desiredNames.push('Crash / Fatal Error');
    if (content.includes('visual') || content.includes('texture') || content.includes('render') || content.includes('graphic') || content.includes('glitch')) desiredNames.push('Visual Bug');
    if (content.includes('animation') || content.includes('anim ')) desiredNames.push('Animation Bug');
    if (content.includes('modpack') || content.includes('mod pack')) desiredNames.push('Modpack Issue');
    if (content.includes('compat') || content.includes('conflict') || (content.includes('mod') && (content.includes('work together') || content.includes('doesnt work with') || content.includes("doesn't work with")))) desiredNames.push('Compatibility Issue');

    if (desiredNames.length === 0) return;

    // Resolve against the forum's REAL tags and cap to Discord's limit. Passing
    // an over-long array makes setAppliedTags() reject, and the old code
    // swallowed that rejection — so a multi-symptom report ended up with NO
    // tags while still logging success.
    const existingIds = thread.appliedTags || [];
    const finalIds = buildAppliedTagIds(thread.parent, desiredNames, existingIds);

    // Nothing to do if the cap left us exactly where we started.
    const unchanged = finalIds.length === existingIds.length
        && finalIds.every(id => existingIds.includes(id));
    if (unchanged) return;

    try {
        await thread.setAppliedTags(finalIds);
        console.log(`🏷️ Auto-applied ${finalIds.length} tag(s) to thread: "${thread.name}"`);
    } catch (e) {
        // Log the real outcome — never claim success on failure.
        console.warn(`⚠️ Could not set tags on "${thread.name}": ${e.message}`);
    }
}

/**
 * Apply tags based on what user says in a follow-up message.
 * Only called when a user explicitly mentions their loader/version in chat
 * without editing the post tags (e.g. "I'm on Fabric" as a reply).
 */
async function applyTagsFromConversation(message, thread) {
    return applyTagsFromText(message, thread);
}

/**
 * Flag a thread as needing a human.
 *
 * PINGING IS THE EXCEPTION, NOT THE RULE. This used to @-ping BOTH owners on
 * EVERY escalation — including transient AI failures and "a video was posted"
 * — so kewz. and PunchyMan were notified constantly for things no dev needed
 * to see. Renaming the thread to "(HUMAN HELP)" is already visible to anyone
 * scanning the forum; a ping should mean "a person must act now".
 *
 * @param {object} thread
 * @param {string} reason
 * @param {'silent'|'mods'|'devs'} [notify='silent']
 *   silent — rename + red embed, no ping. THE DEFAULT. Use whenever the signal
 *            is uncertain: anything Shubba caused itself, anything it only
 *            suspects, anything a human will see anyway by reading the forum.
 *   devs   — ping the owners. ONLY when the case is unambiguous and a person
 *            genuinely must act: e.g. the user supplied a video AND full
 *            reproduction context. If you are unsure, it is not certain, and
 *            the answer is silent.
 *   mods   — reserved; currently unused. The owner does not want the
 *            Moderator/Helper roles pinged by the bot.
 */
async function requestHumanHelp(thread, reason, notify = 'silent') {
    if (thread.name.startsWith('(HUMAN HELP)')) return;
    try {
        const cleanName = thread.name.replace('[SOLVED] ', '');
        const truncated = ('(HUMAN HELP) ' + cleanName).substring(0, 100);
        await thread.setName(truncated);

        let pings = '';
        if (notify === 'devs') {
            pings = DEV_IDS.map(id => `<@${id}>`).join(' ');
        } else if (notify === 'mods') {
            pings = [MOD_ROLE_ID, HELPER_ROLE_ID].filter(Boolean).map(id => `<@&${id}>`).join(' ');
        }

        const isWikiForum = thread.parentId === WIKI_FORUM_ID;
        const helpType = isWikiForum ? "Wiki question needs human help" : "Support issue needs human help";
        const payload = {
            embeds: [noticeEmbed({
                title: '🚩 Human help requested',
                description: `${helpType}
**Reason:** ${reason}`,
                color: COLORS.ESCALATE,
                footer: "Shubba has stepped aside and won't reply again unless tagged.",
            })],
        };
        // Pings only fire from message content, so only set it when we mean it.
        if (pings) payload.content = pings;
        await thread.send(payload);
        console.log(`🚩 Flagged "${thread.name}" (notify=${notify}) — ${reason}`);
    } catch (e) { console.error("Failed to flag thread:", e); }
}

/**
 * Generate a safe thread name within Discord's 100-char limit.
 * When prefix + name > 100, uses Gemini to produce a short context-aware title.
 * Falls back to hard truncation if Gemini fails.
 */
async function safeThreadName(prefix, originalName) {
    const full = `${prefix}${originalName}`;
    if (full.length <= 100) return full;

    // Strip any existing status prefix from the original name for cleaner context
    const bare = originalName
        .replace(/^\[(SOLVED|CLOSED|INACTIVE|DUPLICATE|Fixed in Next Update|HUMAN HELP)\]\s*/i, '')
        .replace(/^\(HUMAN HELP\)\s*/i, '')
        .trim();

    try {
        const prompt = `Summarize this Minecraft mod bug report title into a SHORT version (max ${95 - prefix.length} characters). 
Keep the core issue clear. No quotes. Just the title text.
Original: "${bare}"`;
        const short = (await callGemini(prompt, false)).trim().replace(/^["']|["']$/g, '').substring(0, 95 - prefix.length);
        if (short.length > 5) return `${prefix}${short}`;
    } catch (e) {
        console.warn('⚠️ Could not generate short thread title:', e.message);
    }

    // Hard fallback
    return full.substring(0, 97) + '...';
}

async function solveThread(thread, interactionOrMessage) {
    try {
        const isWikiForum = thread.parentId === WIKI_FORUM_ID;
        
        if (isWikiForum) {
            // Wiki threads → distill into custom_knowledge (evergreen, not version-pinned)
            await storeWikiKnowledge(thread).catch(e => 
                console.warn(`⚠️ Failed to store wiki knowledge: ${e.message}`)
            );
        } else {
            // Support threads → solutions database (version-specific)
            await storeSolution(thread);
        }
        
        const cleanName = thread.name.replace('(HUMAN HELP) ', '').replace('[SOLVED] ', '');
        const newName = await safeThreadName('[SOLVED] ', cleanName);
        // Green embed — matches the red escalation embed so thread state is
        // readable from the colour alone when scrolling a busy forum.
        const payload = {
            embeds: [noticeEmbed({
                title: isWikiForum ? '✅ Answered' : '✅ Solved',
                description: isWikiForum
                    ? 'This wiki question is now locked and archived.\nGot another one? Open a new post.'
                    : 'This thread is now locked and archived.\nNeed more help? Open a new post.',
                color: COLORS.SOLVED,
            })],
        };

        if (interactionOrMessage.editReply) {
            try {
                await interactionOrMessage.editReply(payload);
            } catch (e) {
                await thread.send(payload).catch(() => {});
            }
        } else if (interactionOrMessage.reply && !interactionOrMessage.author) {
            try {
                await interactionOrMessage.reply(payload);
            } catch (e) {
                await thread.send(payload).catch(() => {});
            }
        } else {
            await thread.send(payload).catch(() => {});
        }

        // Rename — try/catch independently so lock/archive still run even if rename fails
        try {
            await thread.setName(newName);
        } catch (e) {
            console.warn(`⚠️ Could not rename thread: ${e.message}`);
        }

        // Lock — try/catch independently
        try {
            await thread.setLocked(true, "Thread marked as solved.");
        } catch (e) {
            console.warn(`⚠️ Could not lock thread (missing Manage Threads permission?): ${e.message}`);
        }

        // Archive — always attempt regardless of lock result
        try {
            await thread.setArchived(true);
        } catch (e) {
            console.warn(`⚠️ Could not archive thread: ${e.message}`);
        }
        
        // Cancel any pending /replied auto-archive timer for this thread
        if (repliedTimers.has(thread.id)) {
            clearTimeout(repliedTimers.get(thread.id).timeoutId);
            repliedTimers.delete(thread.id);
        }

        // Remove from duplicate index
        activeThreadIndex.delete(thread.id);

        delete threadMemory[thread.id];
        
        console.log(`✅ Thread solved: ${newName} (${isWikiForum ? 'Wiki' : 'Support'})`);
    } catch (e) {
        console.error("❌ Error solving thread:", e);
        const errMsg = "⚠️ Something went wrong while solving. The thread may not have been fully archived — check bot permissions (Manage Threads + Manage Channels).";
        
        try {
            if (interactionOrMessage.editReply) {
                await interactionOrMessage.editReply({ content: errMsg }).catch(() => {});
            } else if (interactionOrMessage.followUp) {
                await interactionOrMessage.followUp({ content: errMsg, flags: [MessageFlags.Ephemeral] }).catch(() => {});
            } else {
                await thread.send({ content: errMsg }).catch(() => {});
            }
        } catch (err) {
            console.error("Failed to send error message:", err.message);
        }
    }
}

