// ============================================================
// POST FAQ — plain text, editable, validated
// ============================================================
async function postFAQ(triggerMessage) {
    const faqChannel = await client.channels.fetch(FAQ_CHANNEL_ID);
    if (!faqChannel) {
        return triggerMessage.reply('❌ Could not find the FAQ channel. Check FAQ_CHANNEL_ID.');
    }

    // Pre-flight validation — catch corruption before touching Discord
    if (!Array.isArray(faqEmbeds) || faqEmbeds.length === 0) {
        return triggerMessage.reply(
            '⚠️ **FAQ data is empty or corrupt in memory.** Run `/faq_reset` to restore defaults, then try again.'
        );
    }

    const problems = [];
    faqEmbeds.forEach((e, i) => {
        if (!e || typeof e.id !== 'string' || !e.id) problems.push(`Entry ${i + 1}: missing or invalid id`);
        if (!e || typeof e.title !== 'string' || !e.title) problems.push(`Entry ${i + 1}: missing title`);
        if (e && e.description && typeof e.description !== 'string') problems.push(`Entry ${i + 1}: description is not a string`);
        if (e && e.description && e.description.length > 1980) {
            console.warn(`⚠️ FAQ entry "${e.id}" is very long (${e.description.length} chars) — will be split across messages`);
        }
    });

    if (problems.length > 0) {
        return triggerMessage.reply(
            `⚠️ **FAQ has ${problems.length} problem(s) — not posting:**\n${problems.map(p => `• ${p}`).join('\n')}\n\nFix the entries or run \`/faq_reset\` to restore defaults.`
        );
    }

    let posted = 0;
    let edited = 0;
    const errors = [];

    for (const e of faqEmbeds) {
        const header = `**${e.title}**`;
        const body = (e.description || '').trim() || '*(no content)*';
        const full = `${header}\n\n${body}`;
        const chunks = splitMessage(full, 1990);

        const existingMsgId = faqMessageIds[e.id];

        if (existingMsgId) {
            try {
                const existingMsg = await faqChannel.messages.fetch(existingMsgId);
                // Only edit if content actually changed
                if (existingMsg.content !== chunks[0]) {
                    await existingMsg.edit(chunks[0]);
                    edited++;
                }
                // If there are additional chunks beyond the first, post them as new messages
                for (let i = 1; i < chunks.length; i++) {
                    await faqChannel.send(chunks[i]);
                }
                continue;
            } catch (err) {
                if (err.code === 10008) {
                    // Message was deleted — post fresh
                    console.warn(`⚠️ FAQ message for "${e.id}" was deleted, reposting...`);
                    delete faqMessageIds[e.id];
                } else {
                    errors.push(`"${e.id}": ${err.message}`);
                    continue;
                }
            }
        }

        // Post new
        try {
            const sentMsg = await faqChannel.send(chunks[0]);
            faqMessageIds[e.id] = sentMsg.id;
            for (let i = 1; i < chunks.length; i++) {
                await faqChannel.send(chunks[i]);
            }
            posted++;
        } catch (err) {
            errors.push(`"${e.id}": ${err.message}`);
        }
    }

    // Always persist updated message IDs even if some failed
    await saveFAQToGCS();

    const parts = [];
    if (posted > 0) parts.push(`${posted} new`);
    if (edited > 0) parts.push(`${edited} edited`);
    if (posted === 0 && edited === 0) parts.push('no changes needed');

    let reply = `✅ FAQ updated in <#${FAQ_CHANNEL_ID}>! (${parts.join(', ')})`;
    if (errors.length > 0) {
        reply += `\n⚠️ **${errors.length} error(s):**\n${errors.map(e => `• ${e}`).join('\n')}`;
    }

    await triggerMessage.reply(reply);
    console.log(`📋 FAQ post: ${posted} new, ${edited} edited, ${errors.length} errors — by ${triggerMessage.author.username}`);
}

