// ── Reaction Role Handler ─────────────────────────────────────
client.on('messageReactionAdd', async (reaction, user) => {
    if (user.bot) return;
    if (reaction.partial) { try { await reaction.fetch(); } catch(e) { return; } }

    const thread = reaction.message.channel;
    const isAddonThread = thread?.parentId === ADDON_FORUM_ID;

    // ── Addon forum 🔥 reactions ──────────────────────────────
    if (isAddonThread && reaction.emoji.name === '🔥') {
        const threadId = thread.id;
        // LEAK FIX: only the thread's STARTER post grants the role. This used to
        // accept a 🔥 on ANY message in the thread, so reacting to a random
        // comment handed out the addon role.
        if (!isStarterMessage(reaction.message.id, threadId)) return;
        const addon = addonRolesStore[threadId];
        if (!addon) return;

        if (addon.roleId) {
            // Role exists — assign it immediately
            try {
                const member = await thread.guild.members.fetch(user.id);
                await member.roles.add(addon.roleId);
                console.log(`🔥 Addon role ${addon.roleName} given to ${user.username}`);
            } catch(e) { console.log('⚠️ Addon role assign error:', e.message); }
        } else {
            // Role doesn't exist yet — track this user
            if (!addon.pendingReactors.includes(user.id)) {
                addon.pendingReactors.push(user.id);
                await saveAddonRolesToGCS();
                console.log(`🔥 Tracked pending reactor ${user.username} for addon ${threadId}`);
            }
        }
        return;
    }

    // ── Standard reaction roles ───────────────────────────────
    // Exact matching: a custom emoji is identified by its ID, never its name.
    const match = findReactionRole(reactionRolesStore, reaction.message.id, reaction.emoji);
    if (!match) return;
    const guild = reaction.message.guild;
    if (!guild) return;
    try {
        const role = guild.roles.cache.get(match.roleId) || await guild.roles.fetch(match.roleId).catch(() => null);
        // Never let a misconfigured mapping hand out a privileged role to
        // anyone who clicks an emoji.
        const verdict = canGrantRole(role, { botHighestRole: guild.members.me?.roles?.highest });
        if (!verdict.allowed) {
            console.warn(`🛑 Refused reaction role ${match.roleId} for ${user.username}: ${verdict.reason}`);
            return;
        }
        const member = await guild.members.fetch(user.id);
        if (member.roles.cache.has(match.roleId)) return; // already has it
        await member.roles.add(match.roleId);
        console.log(`🎭 Reaction role: gave ${role.name} to ${user.username}`);
    } catch(e) { console.log(`⚠️ Reaction role add error: ${e.message}`); }
});

client.on('messageReactionRemove', async (reaction, user) => {
    if (user.bot) return;
    if (reaction.partial) { try { await reaction.fetch(); } catch(e) { return; } }

    const thread = reaction.message.channel;
    const isAddonThread = thread?.parentId === ADDON_FORUM_ID;

    // ── Addon forum 🔥 removal ────────────────────────────────
    if (isAddonThread && reaction.emoji.name === '🔥') {
        if (!isStarterMessage(reaction.message.id, thread.id)) return;
        const addon = addonRolesStore[thread.id];
        if (!addon) return;
        if (addon.roleId) {
            try {
                const member = await thread.guild.members.fetch(user.id);
                await member.roles.remove(addon.roleId);
                console.log(`🔥 Removed addon role ${addon.roleName} from ${user.username}`);
            } catch(e) { console.log('⚠️ Addon role remove error:', e.message); }
        } else {
            // Remove from pending list
            addon.pendingReactors = addon.pendingReactors.filter(id => id !== user.id);
            await saveAddonRolesToGCS();
        }
        return;
    }

    // ── Standard reaction roles ───────────────────────────────
    const match = findReactionRole(reactionRolesStore, reaction.message.id, reaction.emoji);
    if (!match) return;
    const guild = reaction.message.guild;
    if (!guild) return;
    try {
        const member = await guild.members.fetch(user.id);
        await member.roles.remove(match.roleId);
        console.log(`🎭 Reaction role: removed ${match.roleId} from ${user.username}`);
    } catch(e) { console.log(`⚠️ Reaction role remove error: ${e.message}`); }
});

// ── Auto Message: Join/Leave ──────────────────────────────────
client.on('guildMemberAdd', async member => {
    const msgs = autoMessagesStore.filter(m => m.trigger === 'join');
    for (const m of msgs) {
        try {
            const ch = await client.channels.fetch(m.channel).catch(() => null)
                || client.channels.cache.find(c => c.name === m.channel);
            if (ch?.isTextBased()) {
                const text = m.content.replace(/\{user\}/g, `<@${member.id}>`).replace(/\{username\}/g, member.user.username);
                await ch.send(text);
            }
        } catch(e) { console.log('Auto join message error:', e.message); }
    }
});

client.on('guildMemberRemove', async member => {
    const msgs = autoMessagesStore.filter(m => m.trigger === 'leave');
    for (const m of msgs) {
        try {
            const ch = await client.channels.fetch(m.channel).catch(() => null)
                || client.channels.cache.find(c => c.name === m.channel);
            if (ch?.isTextBased()) {
                const text = m.content.replace(/\{user\}/g, member.user.username).replace(/\{username\}/g, member.user.username);
                await ch.send(text);
            }
        } catch(e) { console.log('Auto leave message error:', e.message); }
    }
});

// Addon roles + audit run after ready
client.once(Events.ClientReady, () => {
    loadAddonRolesFromGCS().then(async () => {
        const guild = client.guilds.cache.first();
        if (guild) {
            // Step 1: Back-register any existing addon threads that aren't in the store yet
            await backRegisterExistingAddons(guild).catch(e => console.log('⚠️ Back-register error:', e.message));
            // Step 2: Update the pinned info post
            updateAddonPinnedPost(guild).catch(() => {});
            // Step 3: Audit role assignments for 🔥 reactors
            auditAddonRoles(guild).catch(e => console.log('⚠️ Addon role audit error:', e.message));
        }
    });
});